        Specimen(id = "lake-superior-agate-spec", name = "Agate, Lake Superior", rockClass = RockClass.CRYSTAL, category = "Silicate — Chalcedony variety", tagline = "Minnesota's state gem — iron-rich bands in rich red and orange.", emoji = "\uD83D\uDD34", colorHex = 0xFFCC5533, description = "Lake Superior agates are among the oldest agates on Earth — formed over 1.1 billion years ago in ancient lava flows. Their rich, iron-oxide red, orange, and yellow banding is unmistakable and makes them the official state gemstone of Minnesota. They're found as water-worn pebbles along the shores of Lake Superior and in glacial deposits across the Midwest.", formation = "Silica-rich water filled gas cavities in 1.1-billion-year-old basalt lava flows. Layer upon layer of chalcedony deposited over millions of years, with iron oxides creating the distinctive red-orange colors.", hardness = "6.5–7", luster = "Waxy to vitreous", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO₂ (with Fe₂O₃)", commonColors = listOf("Iron red", "Burnt orange", "Golden yellow", "White quartz banding"), whereFound = listOf("Lake Superior shoreline, Minnesota, USA", "Wisconsin, USA", "Michigan, USA", "Ontario, Canada"), funFacts = listOf("Each agate took over a billion years to form — among the oldest agates on Earth.", "The red bands are iron that rusted in the lava billions of years ago.", "Glaciers scattered them across the Midwest — you can find them hundreds of miles from Lake Superior."), uses = "Jewelry, cabochons, Minnesota's official state gem.", rarity = "Common (along Lake Superior)"),
