        Specimen(id = "plume-agate", name = "Agate, Plume", rockClass = RockClass.CRYSTAL, category = "Silicate — Chalcedony variety", tagline = "Feathery inclusions that look like frozen smoke.", emoji = "\uD83E\uDEB6", colorHex = 0xFFDD8866, description = "Plume agate is chalcedony containing three-dimensional, plume-like inclusions of iron and manganese oxides that look like feathers, flames, or puffs of smoke. Each specimen is a unique natural artwork.", formation = "Mineral-laden solutions crystallize intricate, feathery structures within clear chalcedony.", hardness = "6.5\u20137", luster = "Vitreous", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO\u2082 (with Fe/Mn oxides)", commonColors = listOf("Clear with red plumes", "White with black", "Orange-brown"), whereFound = listOf("Oregon, USA", "Texas, USA", "Mexico", "Morocco"), funFacts = listOf("Plume agates from Oregon are world-famous among collectors.", "The plumes are three-dimensional \u2014 not flat like moss agate.", "Some display plumes in red, orange, yellow, and white."), uses = "Jewelry, lapidary art, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "polka-dot-agate", name = "Agate, Polka Dot", rockClass = RockClass.CRYSTAL, category = "Silicate — Chalcedony variety", tagline = "Oregon's spotted wonder — perfect dots in translucent chalcedony.", emoji = "\u26AB", colorHex = 0xFF776655, description = "Polka dot agate from Oregon features perfectly round, dot-like inclusions of various colors — brown, red, yellow, and orange — suspended in translucent gray-blue chalcedony. The dots are evenly distributed like a dalmatian pattern, creating one of the most visually distinctive agate varieties.", formation = "Orbicular inclusions formed around tiny nuclei in silica gel before the chalcedony fully hardened. Different trace elements created the color variation in each dot.", hardness = "6.5–7", luster = "Waxy to vitreous", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO₂ (with Fe/Mn oxide dots)", commonColors = listOf("Gray-blue with brown dots", "Translucent with red spots", "Milky with orange dots"), whereFound = listOf("Oregon, USA", "Central Oregon high desert"), funFacts = listOf("The dots are actually orbicular formations — like tiny spheres within spheres.", "Oregon is the only significant source of polka dot agate.", "Each dot represents a separate nucleation event in the silica gel."), uses = "Jewelry, cabochons, distinctive collector specimens.", rarity = "Uncommon"),
        Specimen(id = "sagenitic-agate", name = "Agate, Sagenitic", rockClass = RockClass.CRYSTAL, category = "Silicate — Chalcedony variety", tagline = "Needle-like crystal sprays frozen forever in translucent stone.", emoji = "\u2728", colorHex = 0xFFDDA955, description = "Sagenitic agate contains radiating sprays of needle-like mineral inclusions — typically golden rutile, black tourmaline, or goethite — that form starburst, fan, and spray patterns within translucent chalcedony. The golden-yellow needle sprays contrast beautifully with the clear gray agate, creating specimens that look like frozen fireworks.", formation = "Needle-like crystals of rutile, tourmaline, or goethite grew first in a cavity. Silica-rich solutions then surrounded and preserved the crystal sprays in chalcedony.", hardness = "6.5–7", luster = "Vitreous (with silky internal sprays)", streak = "White", crystalSystem = "Microcrystalline (with included crystals)", chemicalFormula = "SiO₂ (with TiO₂ / FeOOH inclusions)", commonColors = listOf("Golden needles in clear", "Black sprays in gray", "Red-brown starbursts"), whereFound = listOf("Brazil", "India", "Oregon, USA", "Mexico"), funFacts = listOf("The term 'sagenitic' comes from Greek 'sagene' meaning 'net'.", "The needle crystals grew first and were encased later by chalcedony.", "Rutile inclusions create the most spectacular golden starburst patterns."), uses = "Jewelry, collector specimens, lapidary art.", rarity = "Uncommon"),
        Specimen(id = "ammolite", name = "Ammolite", rockClass = RockClass.CRYSTAL, category = "Biogenic gem — Fossil ammonite shell", tagline = "The rarest gemstone on Earth — a rainbow from the Cretaceous.", emoji = "\uD83E\uDEAA", colorHex = 0xFFCC3344, description = "Ammolite is an opal-like organic gemstone formed from the fossilized, mineralized shells of ammonites. Found almost exclusively in Alberta, Canada, it displays an incredible play-of-color — brilliant flashes of red, green, blue, gold, and purple that shift as you move it. It's one of only three organic gemstones (along with pearl and amber) recognized by the jewelry industry. Rarity: Rare (gem quality).", formation = "Formed from the aragonite shells of ammonites (Placenticeras) buried in the Bearpaw Formation 71 million years ago. Heat, pressure, and mineralization transformed the nacreous shell layers into a thin, iridescent gem material.", hardness = "3.5–4.5", luster = "Vitreous to resinous", streak = "White", crystalSystem = "Orthorhombic (aragonite microcrystals)", chemicalFormula = "CaCO₃ (aragonite) with Fe, Cu, Si trace elements", commonColors = listOf("Red-green flash", "Blue-purple iridescence", "Gold-orange play-of-color", "Full rainbow spectrum"), whereFound = listOf("Alberta, Canada (Bearpaw Formation)", "Montana, USA", "England (rare)"), funFacts = listOf("Ammolite is rarer than diamond — gem-quality material comes from a single geological formation in Alberta.", "Named a gemstone by CIBJO in 1981 — one of only three organic gems.", "The best specimens show a full spectrum of colors in a crackled 'dragon skin' pattern."), uses = "High-end jewelry, collector gemstones, investment-grade gems.", rarity = "Rare (gem quality)", geologicalPeriod = "Late Cretaceous", age = "~71 mya"),
        Specimen(id = "ammonite", name = "Ammonite", rockClass = RockClass.FOSSIL, category = "Cephalopod — Ammonoidea", tagline = "The spiral-shelled hunter of prehistoric seas.", emoji = "\uD83D\uDC1A", colorHex = 0xFFC9A87C, description = "Ammonites were shelled cephalopods that swam the oceans for over 300 million years, from the Devonian to the end of the Cretaceous. Their coiled shells are among the most common and beautiful fossils worldwide.", formation = "Ammonite shells sank to the seafloor after death. Fine sediment filled the chambers, mineralizing into fossil casts and molds over millions of years.", hardness = "—", luster = "Iridescent to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite / Aragonite replacement", commonColors = listOf("Brown", "Gray", "Iridescent (ammolite)"), whereFound = listOf("Morocco", "Madagascar", "England", "Alberta, Canada"), funFacts = listOf("Some ammonites grew to over 6 feet in diameter.", "The iridescent gem ammolite comes from fossil ammonite shells.", "Ammonites are excellent index fossils — their rapid evolution helps date rocks."), uses = "Collector specimens, jewelry (ammolite), and scientific dating.", rarity = "Common", geologicalPeriod = "Devonian – Cretaceous", age = "419 – 66 mya"),
        Specimen(id = "amphibolite", name = "Amphibolite", rockClass = RockClass.METAMORPHIC, category = "Medium-grade metamorphic rock", tagline = "Dark and dense — basalt reborn under crustal pressure.", emoji = "\uD83C\uDFD4\uFE0F", colorHex = 0xFF334433, description = "Amphibolite is a medium-grade metamorphic rock composed mainly of amphibole (hornblende) and plagioclase feldspar. One of the toughest rocks on Earth.", formation = "Basalt or gabbro metamorphosed under moderate temperature and pressure (500-700°C).", hardness = "5\u20136", luster = "Vitreous to pearly", streak = "\u2014", crystalSystem = "Granoblastic to foliated", chemicalFormula = "Mixed amphibole and feldspar", commonColors = listOf("Dark green-black", "Black", "Gray-green"), whereFound = listOf("Canadian Shield", "Scotland", "Norway", "Adirondacks, New York, USA"), funFacts = listOf("Amphibolite is one of the toughest and most durable rocks.", "Often used as railroad ballast because of its toughness.", "The name comes from amphibole — the dominant mineral."), uses = "Crushed stone, railroad ballast, dimension stone.", rarity = "Common"),
        Specimen(id = "andalusite", name = "Andalusite", rockClass = RockClass.MINERAL, category = "Silicate — Nesosilicate (includes Chiastolite)", tagline = "Cross-shaped crystals showing a dark cross in cross-section — the chiastolite variety.", emoji = "\u271D\uFE0F", colorHex = 0xFF996633, description = "Andalusite is an aluminum silicate that forms distinctive prismatic crystals. When cut in cross-section, many andalusite crystals display a dark cross or checkerboard pattern caused by graphite inclusions — a striking natural formation called chiastolite. Chiastolite is the same mineral as andalusite; the cross is simply graphite pushed aside during crystal growth.", formation = "Crystallizes during medium-grade metamorphism of aluminum-rich sedimentary rocks. Chiastolite specifically forms in contact metamorphic zones where graphite schists are heated by granite intrusions; the graphite is pushed to the crystal corners by the growing andalusite, creating the cross pattern.", hardness = "6.5–7.5", luster = "Vitreous to dull", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Al₂SiO₅ (with graphite inclusions in chiastolite)", commonColors = listOf("Brown", "Olive-green", "Pink", "Gray with black cross", "Brown with dark cross"), whereFound = listOf("California, USA", "Spain", "Brazil", "Sri Lanka", "Asturias, Spain", "Massachusetts, USA", "South Australia", "China"), funFacts = listOf("Chiastolite (cross-bearing andalusite) was worn as a religious talisman by medieval pilgrims.", "One of three polymorphs of Al₂SiO₅ — alongside kyanite and sillimanite.", "Named after Andalusia, Spain where it was first described.", "Medieval pilgrims wore chiastolite as protective amulets.", "The cross is different in every crystal — no two are identical.", "It's also called 'lapis crucifer' — the cross-bearing stone."), uses = "Refractory ceramics, collector specimens, religious jewelry, amulets.", rarity = "Common to Uncommon"),
        Specimen(id = "anglesite", name = "Anglesite", rockClass = RockClass.MINERAL, category = "Sulfate mineral", tagline = "Brilliant glassy crystals born from oxidized galena.", emoji = "\uD83D\uDC8E", colorHex = 0xFFF0F4FF, description = "Anglesite is lead sulfate, forming when galena oxidizes. Its colorless to pale blue, adamantine crystals are among the most brilliant in the mineral world — with a luster that rivals diamond.", formation = "Forms in the oxidation zone of lead sulfide deposits, particularly in arid climates.", hardness = "2.5\u20133", luster = "Adamantine to vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "PbSO\u2084", commonColors = listOf("Colorless", "Pale blue", "Gray", "Yellow", "Green"), whereFound = listOf("Wales", "Morocco", "Namibia", "Arizona, USA"), funFacts = listOf("Anglesite's luster is so brilliant it can be mistaken for a gemstone.", "Named after the Isle of Anglesey in Wales where it was discovered.", "The finest transparent crystals are highly sought by collectors."), uses = "Lead ore, collector specimens, gemstone (rare).", rarity = "Uncommon"),
        Specimen(id = "anhydrite", name = "Anhydrite", rockClass = RockClass.MINERAL, category = "Sulfate mineral", tagline = "Gypsum without water — the mineral that thirsts.", emoji = "\uD83E\uDDC2", colorHex = 0xFFDDDDFF, description = "Anhydrite is calcium sulfate without water — the anhydrous version of gypsum. When exposed to water at the surface, it absorbs it and expands into gypsum, which is why it's rarely seen at the Earth's surface.", formation = "Evaporates in warm, shallow marine basins where gypsum continues to dehydrate.", hardness = "3\u20133.5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "CaSO\u2084", commonColors = listOf("Colorless", "White", "Blue-gray", "Lavender"), whereFound = listOf("Mexico", "Peru", "Poland", "New Mexico, USA"), funFacts = listOf("Anhydrite turns into gypsum when it gets wet — expanding up to 60%.", "Named from Greek 'anhydros' meaning 'without water.'", "Billions of tons exist underground but rarely at the surface."), uses = "Cement, plaster, soil treatment, sulfuric acid production.", rarity = "Common"),
        Specimen(id = "annabergite", name = "Annabergite", rockClass = RockClass.MINERAL, category = "Arsenate mineral", tagline = "Apple-green crusts and crystals where nickel weathers.", emoji = "\uD83C\uDF4F", colorHex = 0xFF7CB342, description = "Annabergite is a secondary nickel arsenate forming bright apple-green crusts and delicate acicular crystals. It's the nickel analog of erythrite and serves the same role — a vivid indicator mineral that marks hidden nickel deposits.", formation = "Alteration of nickel arsenide minerals in the oxidized zone of ore deposits.", hardness = "1.5\u20132.5", luster = "Adamantine to pearly", streak = "Pale green", crystalSystem = "Monoclinic", chemicalFormula = "Ni\u2083(AsO\u2084)\u2082\u00B78H\u2082O", commonColors = listOf("Apple green", "Yellowish-green", "Emerald green"), whereFound = listOf("Germany", "Greece", "Quebec, Canada", "New South Wales, Australia"), funFacts = listOf("Named after Annaberg, Germany where it was first discovered.", "The nickel analog of erythrite — they often occur together in the same deposit.", "Its color is among the brightest greens in the mineral kingdom."), uses = "Nickel indicator mineral, collector specimens.", rarity = "Rare"),
        Specimen(id = "anorthosite", name = "Anorthosite", rockClass = RockClass.IGNEOUS, category = "Intrusive plutonic rock", tagline = "Almost pure feldspar — the rock that makes up the Moon's highlands.", emoji = "\uD83C\uDF19", colorHex = 0xFFDDDDEE, description = "Anorthosite is a rare igneous rock composed almost entirely of plagioclase feldspar. It's the dominant rock of the lunar highlands — the bright areas visible from Earth.", formation = "Crystallizes from magma in large, deep-seated intrusions. On the Moon, it formed from the ancient magma ocean.", hardness = "6\u20136.5", luster = "Vitreous to pearly", streak = "\u2014", crystalSystem = "Phaneritic (plagioclase)", chemicalFormula = "Mostly Ca-feldspar", commonColors = listOf("White", "Gray", "Bluish-gray", "Iridescent"), whereFound = listOf("Adirondacks, New York, USA", "Labrador, Canada", "Norway", "The Moon"), funFacts = listOf("The Moon's bright highlands are made of anorthosite.", "Labradorite gemstone is found in anorthosite bodies.", "Adirondack anorthosite sparkles with blue iridescence."), uses = "Building stone, labradorite gem mining, lunar geology.", rarity = "Uncommon"),
        Specimen(id = "anthracite", name = "Coal, Anthracite", rockClass = RockClass.METAMORPHIC, category = "Metamorphosed coal", tagline = "The highest-grade coal — hard, shiny, and almost pure carbon.", emoji = "\uD83D\uDD36", colorHex = 0xFF222222, description = "Anthracite is the highest rank of coal, metamorphosed under intense heat and pressure to be over 92% carbon. It burns with a clean, hot, smokeless flame and has a brilliant submetallic luster.", formation = "Bituminous coal is further buried, heated, and pressed, driving off volatile compounds and concentrating carbon.", hardness = "2.5\u20133", luster = "Submetallic, brilliant", streak = "Black", crystalSystem = "Amorphous", chemicalFormula = "C (92\u201398%)", commonColors = listOf("Jet black", "Lustrous black"), whereFound = listOf("Pennsylvania, USA", "Wales, UK", "China", "Ukraine"), funFacts = listOf("Anthracite burns with almost no smoke \u2014 it's 'smokeless coal.'", "Pennsylvania's Coal Region has produced the world's finest anthracite.", "It's the highest-carbon, highest-energy form of coal."), uses = "Home heating, steelmaking, water filtration, carbon products.", rarity = "Common"),
        Specimen(id = "apophyllite", name = "Apophyllite", rockClass = RockClass.MINERAL, category = "Silicate — Phyllosilicate", tagline = "Glassy cubes that flash like mirrors.", emoji = "\uD83D\uDC8E", colorHex = 0xFFCCFFCC, description = "Apophyllite is a potassium calcium silicate forming striking glassy, pseudo-cubic crystals with a perfect mirror-like basal cleavage. Its pearly flash and association with zeolites in Indian basalt quarries make it a collector favorite.", formation = "Crystallizes in cavities of basaltic lava alongside zeolites like stilbite and heulandite.", hardness = "4.5–5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Tetragonal", chemicalFormula = "KCa₄Si₈O₂₀(F,OH)·8H₂O", commonColors = listOf("Colorless", "White", "Green", "Pink", "Peach"), whereFound = listOf("India (Pune)", "Brazil", "Germany", "Oregon, USA"), funFacts = listOf("Apophyllite means 'to leaf apart' — it flakes when heated.", "The mirror-like basal cleavage is so perfect it looks like glass.", "The green variety is colored by trace vanadium."), uses = "Collector specimens, mineral displays.", rarity = "Common"),
        Specimen(id = "archimedes", name = "Archimedes (Corkscrew Bryozoan)", rockClass = RockClass.FOSSIL, category = "Bryozoan — Fenestrata", tagline = "A stone corkscrew from the Mississippian seafloor.", emoji = "\uD83E\uDDF0", colorHex = 0xFFB8A68C, description = "Archimedes is a distinctive bryozoan with a central spiral axis from which a delicate fan-shaped colony extended. The corkscrew-like central stem is what usually fossilizes, giving it the nickname 'Archimedes screw.'", formation = "The spiral central axis of the colony was buried in Mississippian limestone and shale. The delicate fan portion rarely preserves.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan"), whereFound = listOf("Kentucky, USA", "Indiana, USA", "Illinois, USA", "Alabama, USA"), funFacts = listOf("Named after the Greek mathematician Archimedes, who invented the screw pump.", "The corkscrew is actually the central axis \u2014 the colony extended outward like a Chinese fan.", "Archimedes fossils are so abundant in some areas that they're used as index fossils."), uses = "Collector specimens, index fossils, educational displays.", rarity = "Common", geologicalPeriod = "Mississippian", age = "359 – 323 mya"),
        Specimen(id = "arkose", name = "Arkose", rockClass = RockClass.SEDIMENTARY, category = "Clastic sedimentary rock", tagline = "Pink feldspar-rich sandstone — granite's graveyard.", emoji = "\uD83C\uDFD4\uFE0F", colorHex = 0xFFDDAA99, description = "Arkose is a sandstone rich in feldspar (over 25%), indicating that the sediment was derived from the rapid erosion of granite and not transported far. Its pink color from potassium feldspar makes it distinctive.", formation = "Rapid erosion of granite in arid or tectonically active areas deposits feldspar-rich sand.", hardness = "6\u20137", luster = "Dull to vitreous grains", streak = "\u2014", crystalSystem = "Clastic aggregate", chemicalFormula = "Mostly SiO\u2082 and K-feldspar", commonColors = listOf("Pink", "Reddish", "Gray-pink"), whereFound = listOf("Colorado, USA", "Scotland", "Australia", "Namibia"), funFacts = listOf("Arkose means the granite source was very close \u2014 feldspar weathers quickly.", "The pink color comes from potassium feldspar grains.", "It's a key indicator of ancient mountain ranges nearby."), uses = "Building stone, decorative aggregate, geological indicator.", rarity = "Common"),
        Specimen(id = "arsenopyrite", name = "Arsenopyrite", rockClass = RockClass.MINERAL, category = "Sulfide mineral", tagline = "The most common arsenic mineral — silvery, brittle, and dangerous.", emoji = "\u2699\uFE0F", colorHex = 0xFFC0C0C0, description = "Arsenopyrite is an iron arsenic sulfide and the most abundant arsenic mineral. Its silver-white crystals with a metallic luster are distinctive, but heating it releases toxic arsenic fumes — never heat-test this mineral.", formation = "Forms in high-temperature hydrothermal veins and pegmatites, often associated with gold, cassiterite, and wolframite.", hardness = "5.5\u20136", luster = "Metallic", streak = "Dark grayish-black", crystalSystem = "Monoclinic (pseudo-orthorhombic)", chemicalFormula = "FeAsS", commonColors = listOf("Silver-white", "Steel-gray", "Tarnished iridescent"), whereFound = listOf("Portugal", "Peru", "Bolivia", "Ontario, Canada"), funFacts = listOf("Crushing arsenopyrite releases a garlic-like odor of arsenic.", "It's a key indicator mineral for gold deposits.", "The name comes from 'arsenic' + 'pyrite' — the arsenic version of fool's gold."), uses = "Arsenic ore, gold exploration indicator, industrial arsenic.", rarity = "Common"),
        Specimen(id = "augite", name = "Augite", rockClass = RockClass.MINERAL, category = "Silicate — Pyroxene group", tagline = "Black stubby prisms — the most common pyroxene in basalt.", emoji = "\u2B1B", colorHex = 0xFF222222, description = "Augite is a calcium magnesium iron pyroxene and the most common pyroxene mineral in basaltic rocks. Its short, stubby black crystals are a major component of dark volcanic rocks worldwide.", formation = "Crystallizes from mafic magma at high temperatures, making it one of the first minerals to form in cooling basalt.", hardness = "5.5–6", luster = "Vitreous to resinous", streak = "Greenish-gray", crystalSystem = "Monoclinic", chemicalFormula = "(Ca,Na)(Mg,Fe,Al)(Si,Al)₂O₆", commonColors = listOf("Black", "Dark green", "Brownish-black"), whereFound = listOf("Italy (Vesuvius)", "Hawaii, USA", "Germany", "Iceland"), funFacts = listOf("Augite is a major component of lunar basalts brought back by Apollo astronauts.", "Named from Greek 'auge' meaning luster — from its shiny cleavage surfaces.", "It's the dark mineral you see as black specks in many volcanic rocks."), uses = "Rock-forming mineral indicator, educational specimens.", rarity = "Common"),
        Specimen(id = "autunite", name = "Autunite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Glowing yellow-green crystals — uranium's beautiful warning.", emoji = "\u2622\uFE0F", colorHex = 0xFFC7EA46, description = "Autunite is a hydrated calcium uranium phosphate with brilliant yellow-green tabular crystals that fluoresce intensely green-yellow under UV light. It's radioactive and dehydrates over time, transforming into meta-autunite.", formation = "Forms in the oxidized zone of uranium deposits as a secondary mineral.", hardness = "2\u20132.5", luster = "Vitreous to pearly", streak = "Yellow", crystalSystem = "Tetragonal", chemicalFormula = "Ca(UO\u2082)\u2082(PO\u2084)\u2082\u00B710-12H\u2082O", commonColors = listOf("Lemon yellow", "Chartreuse", "Yellow-green"), whereFound = listOf("France", "Portugal", "Washington, USA", "Australia"), funFacts = listOf("Autunite fluoresces brilliant green-yellow under UV light.", "Named after Autun, France where it was discovered.", "Dehydrates to meta-autunite — specimens must be stored in sealed containers."), uses = "Uranium ore indicator, collector specimens (handle with care).", rarity = "Uncommon"),
        Specimen(id = "axinite", name = "Axinite", rockClass = RockClass.MINERAL, category = "Silicate — Cyclosilicate (Borosilicate)", tagline = "Purple-brown axe-head crystals from alpine clefts.", emoji = "\uD83E\uDE93", colorHex = 0xFF7B5D8A, description = "Axinite is a calcium aluminum borosilicate forming distinctive wedge-shaped ('axe-head') crystals in shades of clove-brown, violet, and purple. It's a classic mineral of alpine-type metamorphic deposits.", formation = "Crystallizes in contact metamorphic rocks and alpine-type veins in granite and basalt.", hardness = "6.5–7", luster = "Vitreous", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "(Ca,Fe,Mn)₃Al₂BSi₄O₁₅OH", commonColors = listOf("Clove-brown", "Violet", "Gray", "Yellow"), whereFound = listOf("France", "Mexico", "California, USA", "Russia"), funFacts = listOf("Named from Greek 'axine' meaning axe — the crystals look like axe heads.", "It's strongly pyroelectric — develops an electric charge when heated.", "Axinite can be faceted into beautiful, unusual gemstones."), uses = "Collector specimens, gemstone (rare).", rarity = "Uncommon"),
        Specimen(id = "baculites", name = "Baculites - Fossilized", rockClass = RockClass.FOSSIL, category = "Cephalopod — Ammonoidea", tagline = "The straight-shelled ammonite of the Cretaceous seaway.", emoji = "\uD83E\uDEB3", colorHex = 0xFFB8966E, description = "Baculites is an ammonite that started with a coiled shell tip but grew into a long, straight shaft. These streamlined swimmers were abundant in the Western Interior Seaway that split North America during the Cretaceous.", formation = "Shells accumulated on the seafloor after death and were preserved in marine shales and limestones.", hardness = "—", luster = "Iridescent to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite / Aragonite", commonColors = listOf("Brown", "Gray", "Iridescent"), whereFound = listOf("South Dakota, USA", "Wyoming, USA", "Alberta, Canada", "France"), funFacts = listOf("Baculites are excellent index fossils for dating Late Cretaceous rocks.", "Some specimens show exquisite suture patterns \u2014 the zigzag lines where chamber walls met the shell.", "They could reach over 6 feet in length."), uses = "Index fossils, collector specimens, jewelry.", rarity = "Common", geologicalPeriod = "Late Cretaceous", age = "100 – 66 mya"),
        Specimen(id = "belemnite", name = "Belemnite", rockClass = RockClass.FOSSIL, category = "Cephalopod — Belemnitida", tagline = "The bullet-shaped internal shell of the Mesozoic squid.", emoji = "\uD83D\uDE80", colorHex = 0xFFBC8F5B, description = "Belemnites were squid-like cephalopods that swam in Jurassic and Cretaceous seas. What fossilizes is their internal bullet-shaped skeleton (the guard or rostrum), which gave them their streamlined torpedo shape in life.", formation = "The dense calcite guard sank to the seafloor after death and was buried in marine sediment. These are some of the most abundant and recognizable Mesozoic fossils.", hardness = "—", luster = "Vitreous to dull", streak = "—", crystalSystem = "Radial calcite", chemicalFormula = "Calcite", commonColors = listOf("Amber", "Brown", "Gray"), whereFound = listOf("England", "Germany", "Russia", "Montana, USA"), funFacts = listOf("Belemnite fossils were once called 'thunderbolts' — people thought they fell from the sky.", "They had 10 arms with hooks, not suckers like modern squid.", "The ink sac is sometimes fossilized alongside the guard."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Jurassic – Cretaceous", age = "201 – 66 mya"),
        Specimen(id = "benitoite", name = "Benitoite", rockClass = RockClass.MINERAL, category = "Silicate — Cyclosilicate", tagline = "California's state gem — sapphire-blue crystals found nowhere else.", emoji = "\uD83D\uDC99", colorHex = 0xFF3366CC, description = "Benitoite is a rare barium titanium silicate and California's official state gem. Its intense sapphire-blue, triangular crystals fluoresce brilliant blue under shortwave UV light. It's found in only one significant locality on Earth — San Benito County, California.", formation = "Crystallizes in natrolite veins within glaucophane schist under high-pressure, low-temperature conditions unique to subduction zones.", hardness = "6–6.5", luster = "Vitreous", streak = "White", crystalSystem = "Hexagonal (trigonal)", chemicalFormula = "BaTiSi₃O₉", commonColors = listOf("Sapphire blue", "Colorless", "Pink (rare)"), whereFound = listOf("San Benito County, California, USA", "Japan (trace)", "Arkansas, USA (trace)"), funFacts = listOf("Benitoite fluoresces brilliant chalk-blue under shortwave UV light.", "It's rarer than diamond — only one commercial mine exists on Earth.", "Named after San Benito County, California where it was discovered in 1907."), uses = "Collector gemstone, California state gem, UV fluorescent display.", rarity = "Rare"),
        Specimen(id = "goshenite", name = "Beryl, Goshenite", rockClass = RockClass.CRYSTAL, category = "Silicate — Beryl variety", tagline = "Pure colorless beryl — the transparent parent of all beryl gems.", emoji = "\uD83D\uDC8E", colorHex = 0xFFF0F8FF, description = "Goshenite is the pure, colorless variety of beryl — beryl without trace impurities that cause color. It's the 'parent' of emerald, aquamarine, morganite, and heliodor, named after Goshen, Massachusetts where it was first found.", formation = "Crystallizes in granite pegmatites from beryllium-rich residual magma without chromophore impurities.", hardness = "7.5–8", luster = "Vitreous", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "Be₃Al₂Si₆O₁₈", commonColors = listOf("Colorless", "White", "Silvery"), whereFound = listOf("Massachusetts, USA", "Brazil", "China", "Pakistan"), funFacts = listOf("Goshenite is pure beryl without any coloring agents.", "Named after Goshen, Massachusetts where it was first found.", "Ancient Greeks used clear beryl as lenses for magnifying glasses."), uses = "Gemstone, optical lenses, beryllium source.", rarity = "Common"),
        Specimen(id = "heliodor", name = "Beryl, Heliodor", rockClass = RockClass.CRYSTAL, category = "Silicate — Beryl variety", tagline = "Sun-colored beryl — golden-yellow from Namibia's desert.", emoji = "\uD83C\uDF1E", colorHex = 0xFFFFDD44, description = "Heliodor is the golden-yellow to greenish-yellow variety of beryl, colored by trace iron. Its name means 'gift of the sun' in Greek, and the finest crystals come from Namibia and Brazil.", formation = "Crystallizes in granite pegmatites alongside other beryl varieties.", hardness = "7.5–8", luster = "Vitreous", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "Be₃Al₂Si₆O₁₈ (with Fe)", commonColors = listOf("Golden yellow", "Greenish-yellow", "Lemon", "Honey"), whereFound = listOf("Namibia", "Brazil", "Madagascar", "Ukraine"), funFacts = listOf("Heliodor means 'gift of the sun' — perfectly describing its golden glow.", "It's the same mineral as emerald and aquamarine — just colored by iron.", "Namibian heliodor from the Erongo Mountains is considered the world's finest."), uses = "Gemstone, jewelry, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "morganite", name = "Beryl, Morganite", rockClass = RockClass.CRYSTAL, category = "Silicate — Beryl variety", tagline = "Soft peach-pink beryl — the romantic gem of the beryl family.", emoji = "\uD83C\uDF51", colorHex = 0xFFFFAAAA, description = "Morganite is the pink-to-peach variety of beryl, colored by trace manganese. Named after financier J.P. Morgan, it's the softer, more romantic cousin of emerald and aquamarine.", formation = "Crystallizes in granite pegmatites from beryllium-rich residual magma.", hardness = "7.5–8", luster = "Vitreous", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "Be₃Al₂Si₆O₁₈ (with Mn)", commonColors = listOf("Peach", "Soft pink", "Rose", "Salmon"), whereFound = listOf("Madagascar", "Brazil", "California, USA", "Afghanistan"), funFacts = listOf("Named after J.P. Morgan, the American financier and gem collector.", "Morganite is sometimes called 'pink emerald' or 'rose beryl.'", "The finest peach-colored crystals come from Madagascar."), uses = "Gemstone, jewelry, collector specimens.", rarity = "Rare"),
        Specimen(id = "bismuth-crystal", name = "Bismuth, Lab-Grown", rockClass = RockClass.MINERAL, category = "Native element", tagline = "Rainbow stair-step crystals — the most colorful metal.", emoji = "\uD83C\uDF08", colorHex = 0xFFFF44AA, description = "Bismuth is a native element metal that forms stunning iridescent, stair-step (hopper) crystals when cooled from a melt. The rainbow colors are a thin oxide film — natural bismuth rarely forms visible crystals.", formation = "Natural bismuth is rare; most collector crystals are lab-grown by cooling purified bismuth from its melting point.", hardness = "2\u20132.5", luster = "Metallic with iridescent oxide", streak = "Silver-white", crystalSystem = "Trigonal (hopper)", chemicalFormula = "Bi", commonColors = listOf("Rainbow iridescent", "Silver", "Pink-gold"), whereFound = listOf("Lab-grown (collector market)", "Bolivia (natural)", "Germany", "Australia"), funFacts = listOf("Bismuth is the most diamagnetic metal — it repels magnetic fields.", "The rainbow colors come from a thin oxide layer, like oil on water.", "It's non-toxic and used in Pepto-Bismol — yes, the pink medicine."), uses = "Lab-grown collector crystals, pharmaceuticals, low-melt alloys.", rarity = "Common (lab), Rare (natural crystals)"),
        Specimen(id = "blastoid", name = "Blastoid - Fossilized", rockClass = RockClass.FOSSIL, category = "Echinoderm — Blastoidea", tagline = "The tiny flower bud of the Carboniferous seafloor.", emoji = "\uD83C\uDF3C", colorHex = 0xFFD2B07A, description = "Blastoids are extinct echinoderms related to crinoids, with a distinctive bud-shaped body (theca) made of precisely arranged calcite plates. They are delicate, beautiful fossils popular with collectors.", formation = "Blastoids lived attached to the seafloor by a thin stem. After death, the stem broke away and the theca was buried in carbonate sediment.", hardness = "—", luster = "Dull to vitreous", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Tan", "White"), whereFound = listOf("Indiana, USA", "Illinois, USA", "Kentucky, USA", "Germany"), funFacts = listOf("Blastoids are also called 'sea buds' because of their flower-like shape.", "The five-fold symmetry of echinoderms is perfectly preserved in blastoid fossils.", "They went extinct at the same time as the trilobites in the Permian extinction."), uses = "Collector specimens, educational displays.", rarity = "Uncommon", geologicalPeriod = "Silurian – Permian", age = "444 – 252 mya"),
        Specimen(id = "brachiopod", name = "Brachiopod - Fossilized", rockClass = RockClass.FOSSIL, category = "Brachiopoda", tagline = "Not a clam — a completely different lineage that ruled the Paleozoic.", emoji = "\uD83D\uDC0A", colorHex = 0xFFD2B48C, description = "Brachiopods are marine animals with two shells, often mistaken for clams. Unlike clams (which have left-right shells), brachiopod shells are top-bottom. They were the dominant filter-feeders of the Paleozoic Era.", formation = "Burial in shallow sea sediment preserved both hinged and separated shells. Pyritized specimens from certain sites glow metallic.", hardness = "—", luster = "Dull to metallic", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite replacement / Pyrite", commonColors = listOf("Brown", "Gray", "Brassy (pyrite)"), whereFound = listOf("New York, USA", "Ohio, USA", "England", "China"), funFacts = listOf("Brachiopods have been around for over 500 million years.", "They are NOT related to clams — the two-shell design is convergent evolution.", "Some are preserved in pyrite and look like brass."), uses = "Collector specimens, index fossils for dating rocks.", rarity = "Common", geologicalPeriod = "Cambrian – Present", age = "541 mya – today"),
        Specimen(id = "brochantite", name = "Brochantite", rockClass = RockClass.MINERAL, category = "Sulfate mineral", tagline = "Emerald-green needles on copper-rich rocks.", emoji = "\uD83E\uDEA2", colorHex = 0xFF2E8B57, description = "Brochantite is a copper sulfate hydroxide forming needle-like emerald-green crystals. Common in the oxidized zones of copper deposits, it often grows alongside malachite and azurite in arid copper districts.", formation = "Precipitates from copper-rich solutions in arid environments where copper sulfides oxidize.", hardness = "3.5\u20134", luster = "Vitreous", streak = "Pale green", crystalSystem = "Monoclinic", chemicalFormula = "Cu\u2084SO\u2084(OH)\u2086", commonColors = listOf("Emerald green", "Dark green", "Bluish-green"), whereFound = listOf("Arizona, USA", "Chile", "Namibia", "Russia"), funFacts = listOf("Named after French geologist A.J.M. Brochant de Villiers.", "Statues exposed to acid rain develop brochantite as a green patina.", "It's one of the most common copper sulfate minerals in arid regions."), uses = "Copper ore indicator, collector specimens.", rarity = "Common"),
        Specimen(id = "bronzite", name = "Bronzite", rockClass = RockClass.MINERAL, category = "Silicate — Pyroxene group", tagline = "Bronze-brown with metallic flash — nature's metal-in-stone.", emoji = "\uD83D\uDD36", colorHex = 0xFF886644, description = "Bronzite is a variety of enstatite with a distinctive bronze-brown color and metallic submetallic luster. When cut as cabochons, it shows a dramatic bronze schiller effect.", formation = "Crystallizes in ultramafic igneous rocks like peridotite and serpentinite.", hardness = "5.5", luster = "Vitreous to metallic (schiller)", streak = "Gray", crystalSystem = "Orthorhombic", chemicalFormula = "(Mg,Fe)\u2082Si\u2082O\u2086", commonColors = listOf("Bronze-brown", "Greenish-brown", "Golden-brown"), whereFound = listOf("Austria", "South Africa", "India", "New York, USA"), funFacts = listOf("The bronze schiller effect is caused by microscopic inclusions.", "Named for its resemblance to polished bronze.", "Popular in men's jewelry for its masculine, metallic look."), uses = "Cabochons, jewelry, ornamental stone.", rarity = "Common"),
        Specimen(id = "calamites", name = "Calamites (Giant Horsetail)", rockClass = RockClass.FOSSIL, category = "Plant — Equisetopsida", tagline = "The 30-foot prehistoric horsetail that built coal forests.", emoji = "\uD83C\uDF3F", colorHex = 0xFF6B7A5C, description = "Calamites were giant tree-sized horsetails that grew in Carboniferous swamps. Their jointed, ribbed trunks could exceed 30 feet tall and are common fossils in coal-bearing rocks worldwide.", formation = "Trunks, branches, and leaves were buried in swamp sediments that later became coal. The characteristic ribbed, jointed stem pattern is unmistakable.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Carbon film / Coal", commonColors = listOf("Black on gray", "Brown"), whereFound = listOf("Pennsylvania, USA", "West Virginia, USA", "Wales", "Germany"), funFacts = listOf("Modern horsetails are living descendants that grow only a few feet tall.", "Calamites contributed to the massive coal deposits of the Carboniferous.", "The ribbed trunk pattern looks like a giant piece of bamboo."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Carboniferous – Permian", age = "359 – 252 mya"),
        Specimen(id = "carnotite", name = "Carnotite", rockClass = RockClass.MINERAL, category = "Vanadate mineral", tagline = "Canary-yellow powder that paints desert sandstone.", emoji = "\uD83D\uDFE1", colorHex = 0xFFFFD300, description = "Carnotite is a potassium uranium vanadate that forms bright yellow crusts and powdery coatings on sandstone. It was a key uranium ore during the Manhattan Project and still paints the Colorado Plateau in vivid yellow patches.", formation = "Precipitates from groundwater in arid environments where uranium and vanadium are present in sandstone.", hardness = "2", luster = "Earthy to dull", streak = "Yellow", crystalSystem = "Monoclinic", chemicalFormula = "K\u2082(UO\u2082)\u2082(VO\u2084)\u2082\u00B73H\u2082O", commonColors = listOf("Canary yellow", "Lemon", "Greenish-yellow"), whereFound = listOf("Colorado Plateau, USA", "Utah, USA", "Arizona, USA", "Kazakhstan"), funFacts = listOf("Carnotite powered the early nuclear age — mined heavily for uranium in the 1940s-50s.", "Named after French mining engineer Adolphe Carnot.", "Glows faintly yellow-green under UV light."), uses = "Historical uranium/vanadium ore, radiation detector test source.", rarity = "Common"),
        Specimen(id = "cassiterite", name = "Cassiterite, Bolivia", rockClass = RockClass.MINERAL, category = "Oxide mineral", tagline = "The primary tin ore — legendary twinned crystals from Bolivia.", emoji = "\uD83C\uDF30", colorHex = 0xFF3C2415, description = "Cassiterite is tin dioxide and the only commercially important tin ore. Its high density, adamantine luster, and dark brown-to-black color make it easy to identify in the field. Twinned crystals from Bolivia are legendary among collectors.", formation = "Crystallizes in high-temperature hydrothermal veins and granite pegmatites, often with wolframite and arsenopyrite.", hardness = "6\u20137", luster = "Adamantine to greasy", streak = "White to pale brown", crystalSystem = "Tetragonal", chemicalFormula = "SnO\u2082", commonColors = listOf("Dark brown", "Black", "Reddish-brown", "Yellow"), whereFound = listOf("Bolivia", "Malaysia", "Cornwall, England", "China"), funFacts = listOf("Cassiterite is 2x heavier than most rocks — its high density is unmistakable.", "Tin from cassiterite made the Bronze Age possible.", "The name comes from Greek 'kassiteros' meaning tin."), uses = "Tin ore — essential for solder, bronze, and electronics.", rarity = "Common"),
        Specimen(id = "cerussite", name = "Cerussite", rockClass = RockClass.MINERAL, category = "Carbonate mineral", tagline = "Lead carbonate in twinned crystals of incredible brilliance.", emoji = "\u2728", colorHex = 0xFFF5F5F0, description = "Cerussite is lead carbonate forming colorless to white crystals with adamantine luster and high dispersion. Its V-shaped and reticulated twins are among the most desirable mineral specimens — but it's surprisingly dense from its lead content.", formation = "Alteration product of galena in the oxidized zone of lead deposits.", hardness = "3\u20133.5", luster = "Adamantine to vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "PbCO\u2083", commonColors = listOf("Colorless", "White", "Smoky gray", "Pale blue"), whereFound = listOf("Namibia (Tsumeb)", "Morocco", "Arizona, USA", "Australia"), funFacts = listOf("Cerussite is 6.5x denser than water — surprisingly heavy for a clear crystal.", "The reticulated twins look like intricate snowflakes in stone.", "Named from Latin 'cerussa' meaning white lead."), uses = "Lead ore, collector specimens, historical white pigment.", rarity = "Uncommon"),
        Specimen(id = "bloodstone", name = "Bloodstone (Heliotrope)", rockClass = RockClass.CRYSTAL, category = "Silicate — Chalcedony/Jasper variety", tagline = "Dark green chalcedony with drops of blood-red jasper.", emoji = "\uD83E\uDE9B", colorHex = 0xFF224422, description = "Bloodstone is dark green chalcedony or jasper with vivid red spots of iron oxide that look like drops of blood. Ancient warriors carried it into battle believing it would stop bleeding, and medieval Christians associated it with the crucifixion.", formation = "Forms in cavities and veins of volcanic rocks where iron-rich solution creates the red spots in green chalcedony.", hardness = "6.5–7", luster = "Vitreous to waxy", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO₂ (with Fe)", commonColors = listOf("Dark green with red spots", "Forest green", "Blue-green"), whereFound = listOf("India", "Brazil", "Australia", "Scotland"), funFacts = listOf("Ancient warriors carried bloodstone as a talisman to stop bleeding.", "March's alternate birthstone alongside aquamarine.", "The finest material comes from India's Kathiawar Peninsula."), uses = "Jewelry, carvings, religious artifacts, men's signet rings.", rarity = "Uncommon"),
        Specimen(id = "carnelian", name = "Carnelian", rockClass = RockClass.CRYSTAL, category = "Silicate — Chalcedony variety", tagline = "Fiery orange-red chalcedony — the warrior's stone.", emoji = "\uD83D\uDD34", colorHex = 0xFFCC4422, description = "Carnelian is a reddish-orange to brown variety of chalcedony colored by iron oxide. It was one of the most popular gemstones of the ancient world — carved into seals, scarabs, and signet rings by Egyptians, Romans, and Vikings.", formation = "Forms in volcanic rocks and weathered zones where silica-rich groundwater deposits in cavities.", hardness = "6.5–7", luster = "Waxy to vitreous", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO₂ (with Fe)", commonColors = listOf("Fiery orange", "Red", "Brownish-red", "Honey"), whereFound = listOf("India", "Brazil", "Madagascar", "Oregon, USA"), funFacts = listOf("Ancient Egyptians called it 'the blood of Isis' and placed it in tombs.", "Napoleon brought a carnelian seal back from Egypt to France.", "It darkens in sunlight — ancient lapidaries knew this and enhanced color by heating."), uses = "Jewelry, carvings, signet rings, cameos.", rarity = "Common"),
        Specimen(id = "onyx", name = "Onyx", rockClass = RockClass.CRYSTAL, category = "Silicate — Chalcedony variety", tagline = "Parallel-banded chalcedony — the stone of cameos.", emoji = "\u26AB\u26AA", colorHex = 0xFF333333, description = "Onyx is chalcedony with parallel, contrasting bands — most famously black and white. For thousands of years, skilled artisans have carved cameos and intaglios from onyx, taking advantage of the color contrast between layers.", formation = "Deposited layer by layer in volcanic cavities by silica-rich solutions over thousands of years.", hardness = "6.5–7", luster = "Waxy to vitreous", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO₂", commonColors = listOf("Black and white", "Brown", "Red-brown (sardonyx)"), whereFound = listOf("Brazil", "India", "Madagascar", "Mexico"), funFacts = listOf("Most 'black onyx' sold today is dyed gray chalcedony.", "Sardonyx is onyx with red-brown bands — one of the oldest known gems.", "Ancient Romans carved the portraits of emperors into onyx cameos."), uses = "Cameos, intaglios, jewelry, cabochons.", rarity = "Common"),
        Specimen(id = "sardonyx", name = "Agate, Sardonyx", rockClass = RockClass.CRYSTAL, category = "Silicate — Chalcedony variety", tagline = "Red-and-white banded onyx — the oldest known engraved gem.", emoji = "\uD83C\uDFC5", colorHex = 0xFFAA5533, description = "Sardonyx is onyx with reddish-brown (sard) bands alternating with white layers. It's one of the oldest gemstones used for engraved signets and was prized by Greeks, Romans, and Persians for official seals.", formation = "Same process as onyx — iron oxide gives the bands their reddish color.", hardness = "6.5–7", luster = "Waxy to vitreous", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO₂ (with Fe)", commonColors = listOf("Red and white", "Brown and white", "Orange and cream"), whereFound = listOf("India", "Brazil", "Germany", "Uruguay"), funFacts = listOf("Sard is the reddish-brown variety of chalcedony.", "Roman soldiers wore sardonyx signets engraved with Mars, god of war.", "August's secondary birthstone."), uses = "Signet rings, cameos, jewelry, carvings.", rarity = "Uncommon"),
        Specimen(id = "chalk-rock", name = "Chalk", rockClass = RockClass.SEDIMENTARY, category = "Biogenic sedimentary rock", tagline = "Tiny plankton shells — the white cliffs of the Cretaceous.", emoji = "\u270F\uFE0F", colorHex = 0xFFFFFFF5, description = "Chalk is a soft, white, porous limestone made of countless microscopic coccolithophore plates. The White Cliffs of Dover are the world's most famous chalk formation, and the Cretaceous Period is named after chalk.", formation = "Microscopic algae skeletons accumulate on the deep seafloor over millions of years.", hardness = "2", luster = "Earthy", streak = "White", crystalSystem = "Microcrystalline calcite", chemicalFormula = "CaCO\u2083 (biogenic)", commonColors = listOf("White", "Cream"), whereFound = listOf("Dover, England", "Kansas, USA", "France", "Denmark"), funFacts = listOf("Chalk is made of the skeletons of trillions of microscopic algae.", "The Cretaceous Period is named after chalk (creta = chalk in Latin).", "Blackboard chalk today is mostly gypsum, not real chalk."), uses = "Writing chalk, cement, soil conditioner, antacid.", rarity = "Common"),
        Specimen(id = "chambersite", name = "Chambersite", rockClass = RockClass.MINERAL, category = "Borate mineral", tagline = "Manganese borate — Texas's microscopic treasure.", emoji = "\uD83D\uDC8E", colorHex = 0xFF8866AA, description = "Chambersite is a rare manganese borate forming tiny, dark purple tetrahedral crystals. It was first discovered in a Texas salt dome and is found in only a few locations worldwide.", formation = "Crystallizes in salt dome cap rocks and marine evaporite deposits.", hardness = "7", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Mn₃B₇O₁₃Cl", commonColors = listOf("Deep purple", "Colorless", "Pale lavender"), whereFound = listOf("Texas, USA (Barbers Hill)", "Louisiana, USA", "China"), funFacts = listOf("One of the few borate minerals that's harder than quartz.", "Named after Chambers County, Texas where it was discovered.", "The purple color comes from manganese — same element as in amethyst."), uses = "Collector specimens.", rarity = "Rare"),
        Specimen(id = "charoite", name = "Charoite", rockClass = RockClass.MINERAL, category = "Silicate — Complex silicate", tagline = "Swirling purple stone from a single Siberian river.", emoji = "\uD83D\uDC9C", colorHex = 0xFF7B4FA0, description = "Charoite is an incredibly rare complex potassium sodium calcium silicate found exclusively along the Chara River in Siberia. Its swirling, fibrous patterns of lavender, purple, and white are unmistakable and highly sought by lapidary artists.", formation = "Forms through the interaction of a syenite intrusion with limestone at relatively low temperatures and pressures.", hardness = "5–6", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "K(Ca,Na)₂Si₄O₁₀(OH,F)·H₂O", commonColors = listOf("Lavender", "Deep purple", "White swirls", "Lilac"), whereFound = listOf("Chara River, Yakutia, Siberia, Russia"), funFacts = listOf("Charoite is found nowhere else on Earth — a true single-locality gem.", "Discovered in the 1940s but not described to science until 1978.", "The swirling patterns are caused by fibrous crystals intergrown in complex ways."), uses = "Jewelry, ornamental carvings, decorative objects.", rarity = "Rare"),
        Specimen(id = "chlorastrolite", name = "Chlorastrolite", rockClass = RockClass.MINERAL, category = "Silicate — Pumpellyite group", tagline = "Michigan's state gem — turtleback-patterned green pebbles.", emoji = "\uD83D\uDC22", colorHex = 0xFF448866, description = "Chlorastrolite, also known as Isle Royale greenstone, is Michigan's state gem. These beach-worn pebbles display a distinctive turtleback or alligator-skin pattern of radiating green crystals on a darker matrix.", formation = "Crystallizes in the gas cavities of basaltic lava flows, later weathered and polished by Lake Superior waves into beach pebbles.", hardness = "5–6", luster = "Silky to waxy", streak = "White", crystalSystem = "Monoclinic (fibrous aggregate)", chemicalFormula = "Ca₂(Mg,Fe)Al₂(SiO₄)(Si₂O₇)(OH)₂·H₂O", commonColors = listOf("Blue-green", "Dark green", "Olive", "Teal"), whereFound = listOf("Isle Royale, Michigan, USA", "Keweenaw Peninsula, Michigan, USA"), funFacts = listOf("Michigan's official state gemstone.", "Almost all chlorastrolite is found as water-worn beach pebbles.", "The turtleback pattern is unique and makes authentic specimens easy to identify."), uses = "Jewelry, cabochons, collector specimens.", rarity = "Rare"),
        Specimen(id = "alexandrite", name = "Alexandrite", rockClass = RockClass.CRYSTAL, category = "Oxide — Chrysoberyl variety", tagline = "Emerald by day, ruby by night — the color-change king.", emoji = "\uD83D\uDC9A\uD83D\uDD34", colorHex = 0xFF226644, description = "Alexandrite is the phenomenal color-change variety of chrysoberyl. In daylight it's green to bluish-green; under incandescent light it transforms to red to purplish-red. This dramatic change is unmatched in the gem world.", formation = "Crystallizes in pegmatites and mica schists where beryllium and chromium meet — a geological rarity.", hardness = "8.5", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "BeAl\u2082O\u2084 (with Cr)", commonColors = listOf("Green (daylight)", "Red-purple (incandescent)", "Bluish-green", "Purplish-red"), whereFound = listOf("Russia (Ural Mountains)", "Brazil", "Sri Lanka", "Tanzania"), funFacts = listOf("Discovered on the birthday of Czar Alexander II — hence the name.", "The color change is called the 'alexandrite effect.'", "Fine alexandrite can exceed diamond in value per carat."), uses = "Gemstone, jewelry, investment-grade collector stone.", rarity = "Rare"),
        Specimen(id = "cobaltite", name = "Cobaltite", rockClass = RockClass.MINERAL, category = "Sulfide mineral", tagline = "Pinkish-silver crystals of cobalt — the goblin metal.", emoji = "\uD83D\uDC95", colorHex = 0xFFD8A0A8, description = "Cobaltite is cobalt arsenic sulfide, forming metallic pinkish-silver cubic and pyritohedral crystals. Medieval miners cursed it as 'kobold' (goblin) ore because it produced toxic arsenic fumes during smelting.", formation = "Deposited from high-temperature hydrothermal fluids in veins, often alongside other sulfide minerals.", hardness = "5.5", luster = "Metallic", streak = "Grayish-black", crystalSystem = "Orthorhombic (pseudo-cubic)", chemicalFormula = "CoAsS", commonColors = listOf("Pinkish-silver", "Reddish-silver", "Gray"), whereFound = listOf("Sweden", "Ontario, Canada", "Morocco", "Idaho, USA"), funFacts = listOf("The element cobalt is named after German goblins (kobolds).", "Cobalt gives blue glass and ceramics their deep color.", "It's the primary ore of cobalt — crucial for rechargeable batteries."), uses = "Cobalt ore, blue pigments, battery materials, superalloys.", rarity = "Uncommon"),
        Specimen(id = "coelacanth-fossil", name = "Coelacanth Fossil", rockClass = RockClass.FOSSIL, category = "Fish — Coelacanthiformes", tagline = "The fish that came back from the dead.", emoji = "\uD83D\uDC21", colorHex = 0xFF6B7F8E, description = "Coelacanths were thought to have gone extinct with the dinosaurs 66 million years ago \u2014 until a living one was caught off South Africa in 1938. Fossil coelacanths are prized specimens representing one of the most famous 'Lazarus taxa.'", formation = "Preserved in marine limestone and shale from the Devonian through Cretaceous, then seemingly vanishing from the fossil record.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate / Calcite", commonColors = listOf("Brown", "Gray", "Tan"), whereFound = listOf("Germany (Solnhofen)", "Brazil", "Madagascar", "South Africa (living)"), funFacts = listOf("The 1938 discovery of a living coelacanth was one of the greatest biological sensations of the century.", "Coelacanths have lobed fins that move like legs \u2014 suggesting the transition to land.", "Living coelacanths are deep-water fish, which may explain why they escaped detection for so long."), uses = "Collector specimens, scientific study, evolutionary biology.", rarity = "Rare", geologicalPeriod = "Devonian – Present", age = "400 mya – today"),
        Specimen(id = "colemanite", name = "Colemanite", rockClass = RockClass.MINERAL, category = "Borate mineral", tagline = "Sharp glassy crystals — Death Valley's borate treasure.", emoji = "\uD83D\uDC8E", colorHex = 0xFFF8F0D8, description = "Colemanite is a calcium borate forming beautiful glassy, prismatic crystals in the borate deposits of Death Valley and Turkey. It was a major source of borax in the early 20th century.", formation = "Evaporates from boron-rich alkaline lake waters in arid desert basins.", hardness = "4.5", luster = "Vitreous to adamantine", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "CaB₃O₄(OH)₃·H₂O", commonColors = listOf("Colorless", "White", "Pale yellow", "Gray"), whereFound = listOf("Death Valley, California, USA", "Turkey", "Argentina", "Kazakhstan"), funFacts = listOf("Named after William T. Coleman, a pioneer of California's borax industry.", "Death Valley colemanite was hauled by 20-mule teams in the 1880s.", "It's strongly pyroelectric — develops an electric charge when heated."), uses = "Boron ore, collector specimens, historical significance.", rarity = "Common"),
        Specimen(id = "conichalcite", name = "Conichalcite", rockClass = RockClass.MINERAL, category = "Arsenate mineral", tagline = "Grass-green botryoidal crusts on copper rocks.", emoji = "\uD83D\uDFE2", colorHex = 0xFF55AA44, description = "Conichalcite is a calcium copper arsenate forming vivid grass-green botryoidal crusts in the oxidized zone of copper deposits. It's one of the most colorful arsenate minerals.", formation = "A secondary mineral formed by the weathering of copper arsenides and sulfides.", hardness = "4.5", luster = "Vitreous to earthy", streak = "Green", crystalSystem = "Orthorhombic", chemicalFormula = "CaCu(AsO\u2084)(OH)", commonColors = listOf("Grass green", "Emerald green", "Yellow-green"), whereFound = listOf("Arizona, USA", "Mexico", "Spain", "Chile"), funFacts = listOf("Conichalcite means 'powder' and 'copper' in Greek.", "Often found with malachite, azurite, and olivenite.", "Its green color rivals malachite in intensity."), uses = "Collector specimens, copper arsenate indicator.", rarity = "Uncommon"),
        Specimen(id = "conularia", name = "Conularia - Fossilized", rockClass = RockClass.FOSSIL, category = "Cnidarian (?) — Conulata", tagline = "The mysterious four-sided pyramid of Paleozoic seas.", emoji = "\uD83D\uDD3A", colorHex = 0xFFB89868, description = "Conularia is an enigmatic fossil with a four-sided pyramidal shell decorated with fine transverse ridges. Its exact biological affinity is still debated \u2014 most paleontologists place it among the cnidarians, related to corals and jellyfish.", formation = "Shells were buried in fine-grained marine sediments. The phosphate or calcite shell fossilizes as a flattened pyramid.", hardness = "—", luster = "Dull to pearly", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite / Phosphate", commonColors = listOf("Brown", "Gray", "Black"), whereFound = listOf("New York, USA", "Indiana, USA", "Ohio, USA", "Brazil"), funFacts = listOf("Conularia's biological classification has been debated for over 150 years.", "The four-sided symmetry is unique among known cnidarians.", "Some specimens show soft-tissue preservation \u2014 a rare find."), uses = "Collector specimens, scientific study.", rarity = "Uncommon", geologicalPeriod = "Cambrian – Triassic", age = "541 – 201 mya"),
        Specimen(id = "coprolite", name = "Coprolite", rockClass = RockClass.FOSSIL, category = "Trace fossil — Feces", tagline = "Prehistoric poop — a window into ancient diets.", emoji = "\uD83D\uDCA9", colorHex = 0xFF8B6D4B, description = "Coprolites are fossilized animal droppings that preserve what ancient animals ate. They can contain fish scales, bone fragments, plant matter, and even the remains of smaller animals eaten by predators.", formation = "Feces were buried quickly in sediment and mineralized. Phosphates and calcium carbonate replaced the organic material.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate replacement", commonColors = listOf("Brown", "Gray", "Tan"), whereFound = listOf("Washington, USA", "England", "Morocco", "South Dakota, USA"), funFacts = listOf("The largest coprolite known is over 17 inches long — from a T. rex.", "Coprolites can contain bone fragments showing what carnivores ate.", "Fish coprolites often contain perfectly preserved fish scales."), uses = "Collector specimens, scientific study of ancient diets.", rarity = "Common", geologicalPeriod = "Various", age = "Varies by specimen"),
        Specimen(id = "coquina", name = "Coquina", rockClass = RockClass.SEDIMENTARY, category = "Biogenic sedimentary rock", tagline = "A rock made entirely of seashells loosely cemented.", emoji = "\uD83D\uDC1A", colorHex = 0xFFEEDDCC, description = "Coquina is a soft, porous limestone made almost entirely of broken seashell fragments loosely cemented together. It forms on beaches where wave action concentrates shells.", formation = "Wave action concentrates shell fragments on beaches, which are then lightly cemented by calcite from groundwater.", hardness = "Soft to very soft", luster = "Dull", streak = "\u2014", crystalSystem = "Bioclastic aggregate", chemicalFormula = "CaCO\u2083 (shell fragments)", commonColors = listOf("Tan", "Cream", "White", "Orange-brown"), whereFound = listOf("Florida, USA", "Mexico", "Australia", "Brazil"), funFacts = listOf("Castillo de San Marcos in Florida is built from coquina.", "Cannonballs bounced off coquina walls without penetrating.", "It's one of the few rocks you can identify by its shell fragments."), uses = "Building stone, decorative stone, aquarium rock.", rarity = "Common"),
        Specimen(id = "iolite", name = "Cordierite, Iolite", rockClass = RockClass.CRYSTAL, category = "Silicate — Cyclosilicate", tagline = "The Viking compass stone — blue from one angle, clear from another.", emoji = "\uD83E\uDEDF", colorHex = 0xFF5577BB, description = "Iolite is gem-quality cordierite with strong pleochroism — it appears deep blue from one angle and nearly colorless from another. Viking navigators may have used thin slices as a polarizing filter to locate the sun on cloudy days.", formation = "Crystallizes in high-grade metamorphic rocks like gneiss and granulite, and in some granites.", hardness = "7–7.5", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Mg₂Al₄Si₅O₁₈", commonColors = listOf("Blue", "Violet-blue", "Grayish-blue", "Colorless (pleochroic)"), whereFound = listOf("Sri Lanka", "India", "Madagascar", "Wyoming, USA"), funFacts = listOf("Iolite's pleochroism is so strong it's called 'dichroite' — meaning two-colored stone.", "Vikings may have used it as a navigational aid — the 'sunstone' of legend.", "It's sometimes marketed as 'water sapphire' in jewelry."), uses = "Gemstone, jewelry, historical navigation.", rarity = "Common"),
        Specimen(id = "crinoid", name = "Crinoid (Sea Lily)", rockClass = RockClass.FOSSIL, category = "Echinoderm — Crinoidea", tagline = "A flower-like animal that anchored to the ancient seafloor.", emoji = "\uD83C\uDF3A", colorHex = 0xFFD4A76A, description = "Crinoids are marine animals related to starfish and sea urchins. Their stalks formed massive underwater 'forests' on Paleozoic seafloors. Stem segments (ossicles) are among the most abundant fossils, often found as tiny ring-shaped 'Indian beads.'", formation = "Crinoid stalks broke apart after death and were buried in carbonate mud, preserving individual ossicles and occasional complete crowns.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite (single crystal per ossicle)", commonColors = listOf("Gray", "Tan", "White"), whereFound = listOf("Indiana, USA", "Iowa, USA", "Germany", "England"), funFacts = listOf("Each crinoid stem segment is a single crystal of calcite.", "The Mississippian Period is called the Age of Crinoids.", "Living crinoids still exist in deep oceans today."), uses = "Collector specimens, jewelry beads, scientific study.", rarity = "Common", geologicalPeriod = "Ordovician – Present", age = "485 mya – today"),
        Specimen(id = "crocoite", name = "Crocoite", rockClass = RockClass.MINERAL, category = "Chromate mineral", tagline = "Saffron-orange needles — Tasmania's fiery treasure.", emoji = "\uD83D\uDD25", colorHex = 0xFFFF4D00, description = "Crocoite is lead chromate, forming brilliant orange-red needle-like crystals. The Dundas district in Tasmania produces specimens so intensely colored they appear to glow from within — among the most desirable minerals on Earth.", formation = "Hydrothermal alteration of lead-rich rocks in the presence of chromium.", hardness = "2.5\u20133", luster = "Adamantine to vitreous", streak = "Orange-yellow", crystalSystem = "Monoclinic", chemicalFormula = "PbCrO\u2084", commonColors = listOf("Orange-red", "Saffron", "Hyacinth-red"), whereFound = listOf("Tasmania, Australia (Dundas)", "Russia", "Brazil", "Philippines"), funFacts = listOf("Dundas, Tasmania is the world's only significant source of fine crocoite.", "Chromium was first discovered from crocoite in 1797.", "The color is so intense it seems to emit its own light."), uses = "Chromium source, collector specimens.", rarity = "Rare"),
        Specimen(id = "danburite", name = "Danburite", rockClass = RockClass.CRYSTAL, category = "Silicate — Tectosilicate", tagline = "Colorless prismatic crystals — Mexico's hidden gem.", emoji = "\uD83D\uDC8E", colorHex = 0xFFFFF8EE, description = "Danburite is a calcium borosilicate forming beautiful colorless to pale pink prismatic crystals with a glassy luster. Named after Danbury, Connecticut, the finest gem material comes from Charcas, Mexico.", formation = "Crystallizes in metamorphosed carbonate rocks and hydrothermal veins.", hardness = "7", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "CaB\u2082(SiO\u2084)\u2082", commonColors = listOf("Colorless", "Pale pink", "Champagne", "White"), whereFound = listOf("Charcas, Mexico", "Connecticut, USA", "Myanmar", "Russia"), funFacts = listOf("Named after Danbury, Connecticut where it was first discovered.", "Mexican danburite rivals diamond in brilliance when faceted.", "It's harder than most collector minerals at Mohs 7."), uses = "Gemstone, collector specimens.", rarity = "Rare"),
        Specimen(id = "datolite", name = "Datolite", rockClass = RockClass.MINERAL, category = "Silicate — Nesosilicate (Borosilicate)", tagline = "Keweenaw's rainbow nodules — pink, red, white, and green polished halves.", emoji = "\uD83D\uDC9A", colorHex = 0xFFBBCC88, description = "Datolite is a calcium borosilicate best known to collectors as the prized nodules from Michigan's Keweenaw Peninsula. When cut and polished, these nodules reveal stunning pink, red, white, and green tones in glassy translucent patterns. Each nodule is unique — some are solid colored, others show dramatic color zoning. Uncut nodules appear as dull brownish rounded pebbles in the basalt, but their interiors are what make them a Lake Superior collector's treasure.", formation = "Crystallizes in cavities and vesicles of basaltic lava flows in the Keweenaw Peninsula, Michigan. Copper-country fluids infused the nodules with iron and other trace elements, creating the distinctive pink and red coloration.", hardness = "5–5.5", luster = "Vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "CaBSiO₄(OH)", commonColors = listOf("Pink", "Red", "White", "Green", "Pale green", "Colorless"), whereFound = listOf("Michigan, USA (Keweenaw)", "New Jersey, USA", "Germany", "Russia"), funFacts = listOf("Keweenaw datolite nodules are cut and polished to reveal vivid pink, red, white, and green interiors — each one unique.", "Named from Greek 'dateisthai' meaning to divide — from its granular texture.", "The finest colored nodules come from the copper mines of Michigan's Upper Peninsula.", "Collectors hunt for the rare 'peach' and 'watermelon' colored nodules."), uses = "Collector specimens, polished halves, cabochons.", rarity = "Uncommon"),
        Specimen(id = "descloizite", name = "Descloizite", rockClass = RockClass.MINERAL, category = "Vanadate mineral", tagline = "Orange-brown pyramidal crystals — lead zinc vanadate.", emoji = "\uD83D\uDD36", colorHex = 0xFFCC6633, description = "Descloizite is a lead zinc vanadate forming orange-brown to reddish-brown pyramidal crystals and botryoidal crusts. The finest specimens come from Namibia's Tsumeb and Berg Aukas mines.", formation = "A secondary mineral formed in the oxidized zone of lead-zinc-vanadium deposits.", hardness = "3\u20133.5", luster = "Resinous to adamantine", streak = "Orange-brown", crystalSystem = "Orthorhombic", chemicalFormula = "PbZn(VO\u2084)(OH)", commonColors = listOf("Orange-brown", "Reddish-brown", "Dark brown"), whereFound = listOf("Namibia (Tsumeb)", "Arizona, USA", "Mexico", "Zambia"), funFacts = listOf("Named after French mineralogist Alfred Des Cloizeaux.", "Tsumeb descloizite is considered the world's finest.", "The zinc end member of the descloizite-mottramite series."), uses = "Collector specimens, vanadium indicator.", rarity = "Uncommon"),
        Specimen(id = "diatomite", name = "Diatomite", rockClass = RockClass.SEDIMENTARY, category = "Biogenic sedimentary rock", tagline = "Billions of glass skeletons — nature's microscopic filter.", emoji = "\uD83D\uDD2C", colorHex = 0xFFF8F8F0, description = "Diatomite is a soft, chalky sedimentary rock made of the silica skeletons of diatoms. So porous that Alfred Nobel used it to stabilize nitroglycerin into dynamite in 1867.", formation = "Diatom shells accumulate on lake and ocean floors over thousands of years.", hardness = "1\u20132", luster = "Earthy", streak = "White", crystalSystem = "Amorphous silica", chemicalFormula = "SiO\u2082 (biogenic opal)", commonColors = listOf("White", "Cream", "Light gray"), whereFound = listOf("California, USA", "Nevada, USA", "Denmark", "China"), funFacts = listOf("Alfred Nobel used diatomite to invent dynamite in 1867.", "It's used to filter beer, wine, and swimming pool water.", "Each cubic inch contains billions of microscopic diatom skeletons."), uses = "Filtration, absorbents, insulation, mild abrasive, dynamite.", rarity = "Common"),
        Specimen(id = "dinosaur-bone", name = "Dinosaur Bone - Fossilized", rockClass = RockClass.FOSSIL, category = "Reptile — Various Dinosauria", tagline = "Agatized cells from the giants that once walked the Earth.", emoji = "\uD83E\uDD96", colorHex = 0xFFB87D4B, description = "Dinosaur bone fossils form when minerals like agate, calcite, or quartz fill the microscopic cell cavities of buried bones. The process preserves internal cell structure in stunning detail — visible as colored speckles when cut and polished.", formation = "Bones buried in sediment were slowly replaced by silica-rich groundwater. The cellular structure became agatized, creating gem-grade 'dino bone' for lapidary work.", hardness = "6.5–7", luster = "Vitreous to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "SiO₂ replacement", commonColors = listOf("Red-orange", "Brown", "Tan", "Blue-gray"), whereFound = listOf("Utah, USA", "Colorado, USA", "Wyoming, USA", "Mongolia"), funFacts = listOf("Cellular structure is visible under magnification — you can see individual bone cells.", "Gem-quality dinosaur bone is used in jewelry and is often called 'gembone'.", "The Morrison Formation in the US yields the best-preserved specimens."), uses = "Collector specimens, cabochons, jewelry, museum displays.", rarity = "Rare", geologicalPeriod = "Triassic – Cretaceous", age = "252 – 66 mya"),
        Specimen(id = "dinosaur-eggshell", name = "Dinosaur Eggshell - Fossilized", rockClass = RockClass.FOSSIL, category = "Trace fossil — Reptile egg", tagline = "Fragments of the eggs that once held baby dinosaurs.", emoji = "\uD83E\uDD5A", colorHex = 0xFFC8B498, description = "Dinosaur eggshell fragments preserve the microscopic structure of the egg, including pores for gas exchange. The shell ornamentation varies by species and can be identified under magnification.", formation = "Eggshells were buried in nesting ground sediments. Their calcite structure preserves well in sandstone and mudstone.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Cream", "Brown", "Gray"), whereFound = listOf("Montana, USA", "China", "Argentina", "France"), funFacts = listOf("Dinosaur eggshell structure is species-specific \u2014 you can identify the dinosaur from a fragment.", "Some nests have been found with embryos still inside the eggs.", "Egg Mountain in Montana yielded the first evidence of dinosaur parental care."), uses = "Collector specimens, scientific study.", rarity = "Uncommon", geologicalPeriod = "Jurassic – Cretaceous", age = "170 – 66 mya"),
        Specimen(id = "dinosaur-track", name = "Dinosaur Track - Fossilized", rockClass = RockClass.FOSSIL, category = "Trace fossil — Reptile footprint", tagline = "A single step frozen for 100 million years.", emoji = "\uD83D\uDC63", colorHex = 0xFF8B6D5B, description = "Dinosaur tracks are trace fossils that capture a single moment of movement \u2014 the impression of a foot in ancient mud that hardened into stone. Trackways can reveal speed, gait, and even social behavior.", formation = "Footprints in soft mud or sand hardened in the sun, were filled with sediment, and lithified into casts or molds.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Sedimentary rock", commonColors = listOf("Gray", "Red-brown", "Tan"), whereFound = listOf("Connecticut, USA", "Texas, USA", "Colorado, USA", "England"), funFacts = listOf("Trackways can show dinosaurs walking, running, and even changing direction.", "The fastest dinosaur tracks suggest speeds over 30 mph.", "Some track sites preserve the footprints of multiple dinosaur species in one place."), uses = "Museum displays, educational study, field trip destinations.", rarity = "Rare", geologicalPeriod = "Triassic – Cretaceous", age = "252 – 66 mya"),
        Specimen(id = "diopside", name = "Diopside", rockClass = RockClass.MINERAL, category = "Silicate — Pyroxene group", tagline = "Chrome-green prisms — a fiery gem when faceted.", emoji = "\uD83D\uDFE2", colorHex = 0xFF228833, description = "Diopside is a calcium magnesium silicate pyroxene. The chromium-rich variety is a brilliant emerald-green gem, and a rare variety from Siberia exhibits four-ray star asterism. It's also a common rock-forming mineral in the mantle. Rarity: Common (gem uncommon).", formation = "Crystallizes in metamorphosed limestones and ultramafic igneous rocks from the Earth's mantle.", hardness = "5.5–6.5", luster = "Vitreous to resinous", streak = "White to pale green", crystalSystem = "Monoclinic", chemicalFormula = "CaMgSi₂O₆", commonColors = listOf("Chrome green", "Emerald", "White", "Colorless", "Black"), whereFound = listOf("Russia", "Finland", "Italy", "New York, USA"), funFacts = listOf("Chrome diopside is a vivid green gem colored by chromium — same element as emerald.", "Star diopside from Siberia shows a 4-ray star when cut as a cabochon.", "It's a major mineral in the Earth's mantle and in meteorites."), uses = "Gemstone (chrome diopside), collector specimens, mantle indicator.", rarity = "Common (gem uncommon)"),
        Specimen(id = "dioptase", name = "Dioptase", rockClass = RockClass.MINERAL, category = "Silicate mineral", tagline = "The most intense emerald-green in the mineral kingdom.", emoji = "\uD83D\uDC9A", colorHex = 0xFF00A86B, description = "Dioptase is a hydrated copper silicate with an astonishing emerald-green to bluish-green color so intense it rivals the finest emeralds. The crystals are small but their color is legendary, and the finest specimens come from Tsumeb, Namibia.", formation = "Crystallizes in the oxidized zone of copper deposits in arid climates, particularly where silica is available.", hardness = "5", luster = "Vitreous", streak = "Green", crystalSystem = "Trigonal (rhombohedral)", chemicalFormula = "CuSiO\u2083\u00B7H\u2082O", commonColors = listOf("Emerald green", "Bluish-green", "Deep teal"), whereFound = listOf("Namibia (Tsumeb)", "Kazakhstan", "Democratic Republic of Congo", "Arizona, USA"), funFacts = listOf("Dioptase's color is so vivid it has been called 'the emerald of the mineral kingdom.'", "The name comes from Greek 'dia' (through) and 'optasia' (to see) — you can see cleavage planes inside.", "Tsumeb dioptase is the gold standard — virtually all world-class specimens come from there."), uses = "Collector specimens, copper indicator.", rarity = "Rare"),
        Specimen(id = "diorite", name = "Diorite", rockClass = RockClass.IGNEOUS, category = "Intrusive plutonic rock", tagline = "Salt-and-pepper rock — granite's darker, moodier cousin.", emoji = "\uD83C\uDFD4\uFE0F", colorHex = 0xFF777777, description = "Diorite is a coarse-grained intrusive igneous rock with a distinctive salt-and-pepper appearance from white plagioclase feldspar and dark amphibole.", formation = "Crystallizes from intermediate magma cooling slowly deep underground.", hardness = "6\u20137", luster = "Dull to vitreous grains", streak = "\u2014", crystalSystem = "Phaneritic aggregate", chemicalFormula = "Intermediate silicates", commonColors = listOf("Black and white (salt-and-pepper)", "Gray", "Dark gray"), whereFound = listOf("Scotland", "Norway", "Minnesota, USA", "Italy"), funFacts = listOf("The Rosetta Stone is carved from granodiorite — a close relative.", "Diorite was used in ancient Egypt for statues of pharaohs.", "Its salt-and-pepper appearance makes it easily recognizable."), uses = "Building stone, countertops, monuments, crushed stone.", rarity = "Common"),
        Specimen(id = "dire-wolf-tooth", name = "Dire Wolf Tooth", rockClass = RockClass.FOSSIL, category = "Mammal — Canidae", tagline = "The tooth of the ice age's most famous wolf.", emoji = "\uD83D\uDC3A", colorHex = 0xFF6B5040, description = "Dire wolves (Canis dirus) were larger and more robust than modern gray wolves. Their teeth, especially the carnassial molars, are heavily built \u2014 designed for bone-crushing rather than just meat-slicing.", formation = "Thousands of dire wolf remains have been found in the La Brea Tar Pits, along with river gravel and cave deposits.", hardness = "—", luster = "Enamel-like", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate / Dentin", commonColors = listOf("Brown", "Dark brown"), whereFound = listOf("California, USA (La Brea)", "Florida, USA", "South Dakota, USA", "Peru"), funFacts = listOf("Dire wolves were the most common predator in Pleistocene North America.", "They went extinct just 10,000 years ago as their megafauna prey disappeared.", "Unlike Smilodon, dire wolves are closely related to modern wolves but were stockier."), uses = "Collector specimens, educational displays.", rarity = "Uncommon", geologicalPeriod = "Pleistocene", age = "250,000 – 10,000 years ago"),
        Specimen(id = "dumortierite", name = "Dumortierite", rockClass = RockClass.MINERAL, category = "Silicate — Nesosilicate (Borosilicate)", tagline = "Deep denim-blue fibrous masses — often mistaken for sodalite.", emoji = "\uD83D\uDC99", colorHex = 0xFF334488, description = "Dumortierite is an aluminum borosilicate with a distinctive denim-blue to violet-blue color. It often occurs in massive, fibrous form and is sometimes confused with sodalite or lapis lazuli — but lacks the white veining.", formation = "Crystallizes in high-temperature aluminum-rich metamorphic rocks and pegmatites.", hardness = "7–8.5", luster = "Vitreous to waxy", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Al₇(BO₃)(SiO₄)₃O₃", commonColors = listOf("Denim blue", "Violet-blue", "Reddish-purple", "Pink"), whereFound = listOf("Nevada, USA", "France", "Madagascar", "Brazil"), funFacts = listOf("Named after French paleontologist Eugène Dumortier.", "It's one of the hardest blue minerals — harder than quartz.", "Often used as imitation lapis lazuli — but without the pyrite flecks."), uses = "Jewelry, ornamental stone, high-grade porcelain.", rarity = "Uncommon"),
        Specimen(id = "dumortierite-quartz", name = "Quartz, Dumortierite", rockClass = RockClass.CRYSTAL, category = "Silicate — Quartz variety (included)", tagline = "Blue haze in quartz — tiny dumortierite needles.", emoji = "\uD83D\uDC99", colorHex = 0xFF4466AA, description = "Dumortierite quartz is clear quartz containing microscopic blue dumortierite needles that give the quartz a beautiful denim-blue color. It's often mistaken for blue aventurine.", formation = "Quartz crystallizes around fine dumortierite needles in pegmatite and metamorphic environments.", hardness = "7", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "SiO\u2082 (with dumortierite)", commonColors = listOf("Denim blue", "Lavender-blue", "Gray-blue"), whereFound = listOf("Brazil", "Madagascar", "Namibia", "California, USA"), funFacts = listOf("The blue color comes from countless microscopic dumortierite needles.", "Often sold as 'blue moon quartz' in the gem trade.", "Distinct from blue aventurine which gets its color from crocidolite."), uses = "Jewelry, cabochons, carved objects.", rarity = "Uncommon"),
        Specimen(id = "eclogite", name = "Eclogite", rockClass = RockClass.METAMORPHIC, category = "High-grade metamorphic rock", tagline = "Red garnets in green pyroxene — the diamond's deep companion.", emoji = "\uD83D\uDD34", colorHex = 0xFF444422, description = "Eclogite is an ultra-high-pressure metamorphic rock of red garnets set in green omphacite pyroxene. It forms at depths over 28 miles in subduction zones and sometimes carries diamonds up from the mantle.", formation = "Basalt metamorphosed at extreme pressures deep in subduction zones (over 10 kbar).", hardness = "6\u20137", luster = "Vitreous", streak = "\u2014", crystalSystem = "Granoblastic", chemicalFormula = "Garnet + Omphacite pyroxene", commonColors = listOf("Red and green", "Dark green with red spots"), whereFound = listOf("Norway", "Alps, Italy", "California, USA", "China"), funFacts = listOf("Eclogite is so dense it's believed to drive plate tectonics.", "Diamonds bring eclogite fragments to the surface from 90+ miles deep.", "The red garnets are pyrope-rich, the same as mantle garnets."), uses = "Diamond exploration indicator, deep-Earth research.", rarity = "Rare"),
        Specimen(id = "ecphora", name = "Ecphora - Fossilized", rockClass = RockClass.FOSSIL, category = "Mollusk — Gastropoda", tagline = "The ribbed snail with four distinctive spiraling ridges.", emoji = "\uD83D\uDC0C", colorHex = 0xFFD4A66A, description = "Ecphora is an extinct predatory snail with a distinctive shell ornamented by four prominent spiral ribs. It's the Maryland state fossil and is found in Miocene marine deposits along the Chesapeake Bay.", formation = "Shells were preserved in marine sands and clays of the Calvert, Choptank, and St. Marys formations.", hardness = "—", luster = "Dull to pearly", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite replacement", commonColors = listOf("Brown", "Orange-brown", "Gray"), whereFound = listOf("Maryland, USA", "Virginia, USA", "North Carolina, USA"), funFacts = listOf("Maryland's official state fossil.", "The four ribs make it one of the easiest gastropod fossils to identify.", "Ecphora lived during the Miocene (15 million years ago) when Maryland was underwater."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Miocene", age = "15 – 10 mya"),
        Specimen(id = "electric-blue-obsidian", name = "Obsidian, Electric Blue", rockClass = RockClass.IGNEOUS, category = "Volcanic glass", tagline = "Brilliant blue sheen from Oregon's Lassen Creek.", emoji = "\uD83D\uDC99", colorHex = 0xFF2255CC, description = "Electric blue obsidian from Lassen Creek, Oregon displays a brilliant metallic blue sheen at the right angle of light. The intense blue flash against dark glass is one of nature's most striking obsidian phenomena.", formation = "Microscopic elongated gas bubbles or mineral crystals reflect blue wavelengths creating the sheen.", hardness = "5-6", luster = "Vitreous with metallic blue sheen", streak = "\u2014", crystalSystem = "Amorphous", chemicalFormula = "SiO2 (glass)", commonColors = listOf("Black with electric blue", "Dark with cobalt sheen"), whereFound = listOf("Lassen Creek, Oregon, USA", "Northern California, USA"), funFacts = listOf("Lassen Creek electric blue is considered the finest blue sheen obsidian.", "The blue is a sheen effect — not pigmentation.", "Collected by Native Americans for thousands of years."), uses = "Jewelry, cabochons.", rarity = "Rare"),
        Specimen(id = "enchodus", name = "Enchodus (Saber-Toothed Herring) - Fossilized", rockClass = RockClass.FOSSIL, category = "Fish — Enchodontidae", tagline = "A small fish with enormous fangs.", emoji = "\uD83D\uDC20", colorHex = 0xFFBFA87A, description = "Enchodus was a small predatory fish with oversized, dagger-like fangs. Despite its small size (typically under 2 feet), its impressive teeth make it one of the most recognized fossil fish from the Cretaceous.", formation = "Teeth and jaw fragments preserved in marine chalk, limestone, and shale of the Western Interior Seaway and Tethys Ocean.", hardness = "—", luster = "Enameloid", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate", commonColors = listOf("Brown", "Cream", "Black (root)"), whereFound = listOf("Morocco", "Kansas, USA", "England", "Israel"), funFacts = listOf("Its fangs are so large relative to its body that paleontologists nicknamed it 'the saber-toothed herring.'", "Enchodus teeth are among the most common vertebrate fossils found in Morocco's phosphate beds.", "It survived the K-Pg extinction that killed the dinosaurs."), uses = "Collector specimens, jewelry (small teeth), educational displays.", rarity = "Common", geologicalPeriod = "Cretaceous – Eocene", age = "145 – 34 mya"),
        Specimen(id = "endoceras", name = "Endoceras (Giant Orthocone) - Fossilized", rockClass = RockClass.FOSSIL, category = "Cephalopod — Endocerida", tagline = "The 13-foot straight-shelled predator of the Ordovician.", emoji = "\uD83E\uDEB3", colorHex = 0xFF8B7D6B, description = "Endoceras was a giant nautiloid cephalopod that could reach over 13 feet long \u2014 making it the largest animal of the Ordovician Period. Its long, straight conical shell was divided into chambers and housed a formidable predator.", formation = "Massive shells were buried in shallow Ordovician sea sediments. Their size made them resistant to complete burial \u2014 many are found as fragments.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan"), whereFound = listOf("New York, USA", "Ohio, USA", "Sweden", "Estonia"), funFacts = listOf("Endoceras was the largest animal alive during the Ordovician.", "Their siphuncle (internal tube) was uniquely large \u2014 up to half the shell's diameter.", "They were the apex predators of Ordovician seas, hunting trilobites and smaller cephalopods."), uses = "Collector specimens, museum displays.", rarity = "Uncommon", geologicalPeriod = "Ordovician", age = "485 – 444 mya"),
        Specimen(id = "enstatite", name = "Enstatite", rockClass = RockClass.MINERAL, category = "Silicate — Pyroxene group", tagline = "Brownish-green prisms — the most abundant mineral in asteroids.", emoji = "\uD83D\uDFE4", colorHex = 0xFF776633, description = "Enstatite is a magnesium silicate pyroxene common in the Earth's mantle and in stony meteorites. Gem-quality enstatite shows a bronze-like schiller and the rare chrome variety is a vivid green.", formation = "Crystallizes in ultramafic igneous rocks and in the Earth's mantle. Also found in meteorites.", hardness = "5.5", luster = "Vitreous to pearly", streak = "Gray", crystalSystem = "Orthorhombic", chemicalFormula = "Mg₂Si₂O₆", commonColors = listOf("Bronze", "Brown", "Green", "Gray", "Colorless"), whereFound = listOf("India", "South Africa", "Myanmar", "Arizona, USA"), funFacts = listOf("Gem enstatite shows a bronze-like metallic schiller when cut as a cabochon.", "It's one of the most common minerals in stony meteorites.", "Named from Greek 'enstates' meaning opponent — from its high melting point."), uses = "Gemstone (rare), mantle/meteorite indicator, refractory ceramics.", rarity = "Common"),
        Specimen(id = "erythrite", name = "Erythrite", rockClass = RockClass.MINERAL, category = "Arsenate mineral", tagline = "Vivid crimson crystals that mark hidden cobalt veins.", emoji = "\uD83C\uDF38", colorHex = 0xFFC8325A, description = "Erythrite is a secondary cobalt arsenate with spectacular crimson to magenta acicular crystals. It forms as a weathering product of cobalt minerals and is so distinctive that prospectors call it 'cobalt bloom' — a reliable surface indicator of cobalt deposits.", formation = "Forms in the oxidation zone of cobalt-arsenic deposits when rainwater alters primary cobalt minerals.", hardness = "1.5\u20132.5", luster = "Adamantine to pearly", streak = "Pale red", crystalSystem = "Monoclinic", chemicalFormula = "Co\u2083(AsO\u2084)\u2082\u00B78H\u2082O", commonColors = listOf("Crimson", "Magenta", "Peach-red"), whereFound = listOf("Morocco", "Germany", "Ontario, Canada", "Idaho, USA"), funFacts = listOf("Erythrite literally means 'red' in Greek.", "Miners called it 'cobalt bloom' as it marked rich cobalt veins.", "The most beautiful specimens come from Bou Azzer, Morocco."), uses = "Cobalt indicator mineral, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "euclase", name = "Euclase", rockClass = RockClass.CRYSTAL, category = "Silicate — Nesosilicate", tagline = "Perfect cleavage in pastel blue — fragile beyond measure.", emoji = "\uD83D\uDC99", colorHex = 0xFFAACCEE, description = "Euclase is beryllium aluminum silicate hydroxide with a perfect cleavage so easy that merely picking up a crystal can split it. Its delicate pale blue to colorless crystals are prized by collectors but nearly impossible to facet.", formation = "Crystallizes in granite pegmatites and metamorphic rocks from beryllium-rich fluids.", hardness = "7.5", luster = "Vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "BeAlSiO\u2084(OH)", commonColors = listOf("Pale blue", "Colorless", "Pale green", "Light yellow"), whereFound = listOf("Brazil", "Zimbabwe", "Russia", "Colorado, USA"), funFacts = listOf("Euclase means 'easy to break' — named for its extreme cleavage.", "A faceted euclase is a lapidary triumph because it's so fragile.", "The blue color comes from trace iron."), uses = "Collector gemstone (extremely fragile), mineral specimens.", rarity = "Rare"),
        Specimen(id = "eurypterid", name = "Eurypterid - Fossilized", rockClass = RockClass.FOSSIL, category = "Arthropod — Eurypterida", tagline = "The largest arthropod ever — a 9-foot aquatic scorpion.", emoji = "\uD83E\uDE82", colorHex = 0xFF988060, description = "Eurypterids were Paleozoic aquatic arthropods related to horseshoe crabs and arachnids. The largest species exceeded 8 feet in length, making them the biggest arthropods to ever live.", formation = "Preserved in fine-grained marine and brackish-water sediments, particularly in New York's famous Silurian-age Bertie Waterlime.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Organic film / Calcite", commonColors = listOf("Brown", "Gray", "Black"), whereFound = listOf("New York, USA", "Ohio, USA", "Scotland", "Estonia"), funFacts = listOf("New York's state fossil is Eurypterus remipes.", "They had compound eyes and a pair of paddle-like appendages.", "Despite their name, they lived in both marine and freshwater."), uses = "Collector specimens, museum displays, scientific study.", rarity = "Rare", geologicalPeriod = "Silurian – Devonian", age = "444 – 359 mya"),
        Specimen(id = "exogyra", name = "Exogyra - Fossilized", rockClass = RockClass.FOSSIL, category = "Mollusk — Bivalvia", tagline = "The coiled, thick-shelled oyster of Cretaceous seas.", emoji = "\uD83D\uDC1A", colorHex = 0xFFB8A088, description = "Exogyra is an extinct oyster with a distinctive coiled, thickened shell. Unlike most oysters which cement to hard surfaces, Exogyra had a spiral-curved shell that rested in soft seafloor mud.", formation = "Shells were buried in Cretaceous marine sediments. Their thick, robust shells preserve exceptionally well.", hardness = "—", luster = "Dull to pearly", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan", "White"), whereFound = listOf("Texas, USA", "Mississippi, USA", "Alabama, USA", "Mexico"), funFacts = listOf("Exogyra oysters are sometimes called 'ram's horn oysters' for their coiled shape.", "They are common index fossils for the Cretaceous.", "Some exogyra shells reach dinner-plate size."), uses = "Index fossils, collector specimens.", rarity = "Common", geologicalPeriod = "Cretaceous", age = "145 – 66 mya"),
        Specimen(id = "favosites", name = "Favosites - Fossilized", rockClass = RockClass.FOSSIL, category = "Cnidarian — Tabulata", tagline = "Stone honeycomb from Paleozoic reefs.", emoji = "\uD83C\uDF6F", colorHex = 0xFFD2B88C, description = "Favosites is an extinct tabulate coral with a distinctive honeycomb-like pattern of polygonal corallites packed tightly together. Each tiny hexagonal cell housed a single coral polyp.", formation = "Colonial skeletons were buried in carbonate mud on shallow Paleozoic seafloors. The fine corallite structure is beautifully preserved in many specimens.", hardness = "—", luster = "Dull to vitreous", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan"), whereFound = listOf("New York, USA", "Michigan, USA", "Ohio, USA", "England"), funFacts = listOf("The name means 'honeycomb' \u2014 the pattern is instantly recognizable.", "Each hexagonal cell housed one tiny coral animal.", "Some favosite corals from Michigan are agatized and can be polished into beautiful cabochons."), uses = "Collector specimens, jewelry (agatized), ornamental stone.", rarity = "Common", geologicalPeriod = "Ordovician – Devonian", age = "450 – 359 mya"),
        Specimen(id = "sunstone", name = "Sunstone", rockClass = RockClass.CRYSTAL, category = "Silicate — Feldspar variety", tagline = "Glittering copper platelets — a galaxy in feldspar.", emoji = "\uD83C\uDF1E", colorHex = 0xFFFF9966, description = "Sunstone is oligoclase feldspar containing tiny copper or hematite platelets that produce a glittering, spangled reflection called aventurescence. Oregon sunstone can contain pure copper crystals visible to the naked eye.", formation = "Crystallizes in basalt lava flows where copper and iron are incorporated into the feldspar.", hardness = "6\u20136.5", luster = "Vitreous with metallic spangles", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "(Na,Ca)(Al,Si)\u2084O\u2088 (with Cu)", commonColors = listOf("Orange", "Red-brown", "Green", "Colorless with copper"), whereFound = listOf("Oregon, USA", "India", "Norway", "Tanzania"), funFacts = listOf("Oregon sunstone is the state gemstone of Oregon.", "Pure copper crystals inside feldspar are unique to Oregon sunstone.", "The glitter is called schiller or aventurescence."), uses = "Gemstone, jewelry.", rarity = "Uncommon"),
        Specimen(id = "fenestella", name = "Fenestella - Fossilized", rockClass = RockClass.FOSSIL, category = "Bryozoan — Fenestrata", tagline = "Delicate stone lace \u2014 fan-shaped colonial animals.", emoji = "\uD83E\uDEB7", colorHex = 0xFFA0907C, description = "Fenestella is an extinct bryozoan that formed delicate fan-shaped colonies looking like finely woven stone lace. Each tiny hole in the 'lace' held a minute filter-feeding animal called a zooid.", formation = "Colonies were buried in shallow sea sediment and preserved as thin carbon films or calcite replacements in shale and limestone.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Black (carbon film)"), whereFound = listOf("Ohio, USA", "Kentucky, USA", "Indiana, USA", "England"), funFacts = listOf("Bryozoans are still alive today, forming delicate colonies in modern oceans.", "Fenestella means 'little window' in Latin \u2014 the holes look like a lattice.", "A single colony could contain thousands of individual animals."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Silurian – Permian", age = "444 – 252 mya"),
        Specimen(id = "ferberite", name = "Ferberite", rockClass = RockClass.MINERAL, category = "Tungstate mineral", tagline = "Iron-rich wolframite — black blades from Bolivia.", emoji = "\u2B1B", colorHex = 0xFF222222, description = "Ferberite is the iron-rich end member of the wolframite series, forming black, bladed crystals with a submetallic luster. Bolivia's mines have produced some of the world's finest specimens.", formation = "Deposited from high-temperature hydrothermal fluids in quartz veins cutting granite.", hardness = "4\u20134.5", luster = "Submetallic", streak = "Brownish-black", crystalSystem = "Monoclinic", chemicalFormula = "FeWO\u2084", commonColors = listOf("Black", "Dark brown", "Iron-gray"), whereFound = listOf("Bolivia", "Portugal", "China", "Colorado, USA"), funFacts = listOf("Named after German mineralogist Rudolf Ferber.", "Ferberite and huebnerite form the wolframite series.", "Important tungsten ore for high-speed cutting tools."), uses = "Tungsten ore, high-temperature alloys.", rarity = "Uncommon"),
        Specimen(id = "flint", name = "Chert, Flint", rockClass = RockClass.SEDIMENTARY, category = "Chemical sedimentary rock", tagline = "The spark that lit human civilization.", emoji = "\uD83D\uDD25", colorHex = 0xFF4A4A4A, description = "Flint is a hard, fine-grained variety of chert that occurs in chalk. Its conchoidal fracture produces razor-sharp edges used by early humans for tools, weapons, and fire-starting. Flint sparked the first technologies.", formation = "Silica from dissolved sponge spicules replaces chalk in nodules and layers.", hardness = "7", luster = "Waxy to vitreous", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO\u2082", commonColors = listOf("Dark gray", "Black", "Brown", "Banded"), whereFound = listOf("England", "Denmark", "Ohio, USA (Flint Ridge)", "France"), funFacts = listOf("Flint Ridge, Ohio is called the 'Great Indian Quarry of Ohio.'", "Striking flint against steel throws sparks hot enough to ignite tinder.", "Flint was the first material humans mined systematically."), uses = "Flint knapping, fire starting, historical tools, roads.", rarity = "Common"),
        Specimen(id = "amber", name = "Amber - Fossilized", rockClass = RockClass.FOSSIL, category = "Organic — Fossilized tree resin", tagline = "Light captured in prehistoric tree sap.", emoji = "\uD83D\uDD36", colorHex = 0xFFE6A817, description = "Amber is fossilized tree resin that can preserve insects, spiders, feathers, and even small lizards in stunning 3D detail. Most commercial amber is 30–90 million years old, from the Eocene and Cretaceous periods. Rarity: Uncommon (with inclusions).", formation = "Tree resin dripped and trapped small organisms, then hardened and was buried. Over millions of years, the resin polymerized into amber.", hardness = "2–2.5", luster = "Resinous", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "C₁₀H₁₆O (polymerized)", commonColors = listOf("Golden", "Honey", "Cherry red", "Green"), whereFound = listOf("Baltic region", "Dominican Republic", "Myanmar", "New Jersey, USA"), funFacts = listOf("Insects trapped in amber are stunningly preserved — you can see individual hairs.", "The movie Jurassic Park was inspired by the idea of extracting DNA from amber.", "Baltic amber is the most abundant, formed 44 million years ago."), uses = "Jewelry, scientific study, carvings.", rarity = "Uncommon (with inclusions)", geologicalPeriod = "Cretaceous – Miocene", age = "125 – 16 mya"),
        Specimen(id = "bivalve-fossil", name = "Bivalve (Clam/Oyster) - Fossilized", rockClass = RockClass.FOSSIL, category = "Mollusk — Bivalvia", tagline = "Ancient shellfish from Mesozoic and Cenozoic seas.", emoji = "\uD83D\uDC1A", colorHex = 0xFFD4C4A8, description = "Fossil bivalves are the preserved shells of ancient clams, oysters, scallops, and mussels. They became the dominant shellfish after the Permian extinction and are abundant in Mesozoic and Cenozoic rocks.", formation = "Shells were buried in marine sediments and replaced by calcite or silica. Many still show original shell structure and growth lines.", hardness = "—", luster = "Pearly to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite / SiO₂ replacement", commonColors = listOf("Gray", "White", "Tan", "Brown"), whereFound = listOf("Texas, USA", "South Dakota, USA", "England", "Japan"), funFacts = listOf("Fossil oysters from Texas can be larger than a dinner plate.", "Some bivalve fossils still have their original pearly luster.", "Bivalves diversified massively after the dinosaurs went extinct."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Cambrian – Present", age = "541 mya – today"),
        Specimen(id = "fossil-coral", name = "Coral - Fossilized", rockClass = RockClass.FOSSIL, category = "Cnidarian — Various coral groups", tagline = "Stone flower beds from ancient tropical seas.", emoji = "\uD83E\uDEB8", colorHex = 0xFFE8C88A, description = "Fossil corals are the preserved skeletons of colonial marine animals. Both ancient tabulate and rugose corals from Paleozoic seas, and modern scleractinian corals from Mesozoic and Cenozoic deposits, are prized by collectors.", formation = "Coral skeletons were buried in shallow sea carbonate sediments. The fine corallite structures were preserved by calcite or silica replacement.", hardness = "—", luster = "Dull to vitreous", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite / SiO₂ replacement", commonColors = listOf("Tan", "Gray", "White", "Agatized colors"), whereFound = listOf("Michigan, USA", "Florida, USA", "Indonesia", "England"), funFacts = listOf("The Petoskey stone is Michigan's state stone — a fossil colonial coral.", "Some fossil corals are agatized and can be cut into brilliant cabochons.", "Coral fossils prove that area was once a warm, shallow tropical sea."), uses = "Jewelry (agatized), collector specimens, decorative stone.", rarity = "Common", geologicalPeriod = "Ordovician – Present", age = "485 mya – today"),
        Specimen(id = "charlevoix-stone", name = "Charlevoix Stone", rockClass = RockClass.FOSSIL, category = "Cnidarian — Colonial coral (Hexagonaria percarinata)", tagline = "Petoskey's smaller, tighter-celled cousin from the same Devonian seas.", emoji = "\uD83E\uDEB8", colorHex = 0xFFD9C9A0, description = "The Charlevoix stone is a fossil colonial coral closely related to the Petoskey stone but with a finer, tighter corallite pattern. Each polyp cup is smaller and the cells pack more densely, giving the polished surface a delicate honeycomb look distinct from the Petoskey's bolder hexagonal cells. Found on the same Lake Michigan and Lake Huron shorelines, Charlevoix stones are the reward of patient beachcombers who know the difference.", formation = "Hexagonaria percarinata colonies grew in the warm Devonian seas covering Michigan ~350 million years ago. Their calcite skeletons were buried in limestone, then glacial action and wave tumbling wore them into beach pebbles.", hardness = "3–4 (calcite)", luster = "Dull to vitreous (polished)", streak = "White", crystalSystem = "N/A (colonial coral)", chemicalFormula = "CaCO₃ (calcite skeleton)", commonColors = listOf("Tan", "Gray", "Honey-brown", "Cream"), whereFound = listOf("Charlevoix, Michigan, USA", "Traverse City, Michigan, USA", "Sleeping Bear Dunes, Michigan, USA", "Lake Michigan shoreline, Michigan"), funFacts = listOf("Charlevoix stones have smaller, tighter corallites than Petoskey stones — the key field difference.", "Named after Charlevoix, Michigan, the lakeside town where they're most often found.", "Both Charlevoix and Petoskey stones are the same genus (Hexagonaria) but different species.", "Wet them with a spray bottle on the beach — the honeycomb pattern jumps out when wet."), uses = "Jewelry, cabochons, polished collector specimens, Michigan souvenirs.", rarity = "Common", geologicalPeriod = "Devonian", age = "~350 mya"),
        Specimen(id = "fossil-fern", name = "Fern - Fossilized", rockClass = RockClass.FOSSIL, category = "Plant — Pteridophyta", tagline = "The delicate carbon print of ancient understory plants.", emoji = "\uD83C\uDF3F", colorHex = 0xFF4D4D3A, description = "Fossil ferns are impressions of ancient fern fronds preserved in shale, siltstone, and coal deposits. The fine-grained rock captures every vein and leaflet in stunning detail, often as a carbon film.", formation = "Fern fronds fell into quiet swamps and were quickly covered by fine silt. The organic material carbonized, leaving a dark film on the rock surface.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Carbon film", commonColors = listOf("Black on gray", "Dark brown"), whereFound = listOf("Pennsylvania, USA", "Mazon Creek, USA", "Germany", "Wales"), funFacts = listOf("The Carboniferous Period is named for its massive coal-forming fern forests.", "Mazon Creek in Illinois produces exquisite concretions with fern fossils inside.", "Some fossil ferns show reproductive spores preserved on the leaves."), uses = "Collector specimens, wall art, educational displays.", rarity = "Common", geologicalPeriod = "Carboniferous", age = "359 – 299 mya"),
        Specimen(id = "fossil-fish", name = "Fish (Knightia) - Fossilized", rockClass = RockClass.FOSSIL, category = "Fish — Clupeomorpha", tagline = "Armored herrings from the Green River Formation.", emoji = "\uD83D\uDC1F", colorHex = 0xFF7A6B5C, description = "Knightia is a small, herring-like fish from the Eocene Green River Formation. It's one of the most common vertebrate fossils in the world, often preserved in exquisite detail with scales and fins intact.", formation = "Mass mortality events in ancient lakes buried thousands of fish. The fine-grained, anoxic sediment preserved even soft tissue details.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Organic film on limestone", commonColors = listOf("Brown on tan", "Dark on cream"), whereFound = listOf("Wyoming, USA", "Utah, USA", "Colorado, USA"), funFacts = listOf("Wyoming's state fossil.", "Often found in mass mortality layers with dozens of fish per slab.", "The Green River Formation produces some of the world's finest fish fossils."), uses = "Collector specimens, wall displays, educational tools.", rarity = "Common", geologicalPeriod = "Eocene", age = "56 – 34 mya"),
        Specimen(id = "gastropod-fossil", name = "Gastropod (Snail) - Fossilized", rockClass = RockClass.FOSSIL, category = "Mollusk — Gastropoda", tagline = "Spirals frozen in stone for over 500 million years.", emoji = "\uD83D\uDC0C", colorHex = 0xFFC4A56A, description = "Fossil gastropods are the preserved shells of ancient snails. They come in a huge variety of forms — from tiny turret shells to large whelks — and are among the most common fossils in marine sedimentary rocks.", formation = "Snail shells were buried in seafloor sediment. Groundwater slowly replaced the shell material with calcite or silica.", hardness = "—", luster = "Dull to vitreous", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite replacement", commonColors = listOf("Gray", "Tan", "White"), whereFound = listOf("Texas, USA", "Florida, USA", "France", "India"), funFacts = listOf("Gastropods have an unbroken fossil record going back 500 million years.", "Some fossil snail shells are filled with crystal-lined cavities.", "Living snails still use the same basic shell design that their ancient ancestors did."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Cambrian – Present", age = "541 mya – today"),

        Specimen(id = "sea-urchin-fossil", name = "Sea Urchin (Echinoid) - Fossilized", rockClass = RockClass.FOSSIL, category = "Echinoderm — Echinoidea", tagline = "Perfect five-petaled stars preserved in stone.", emoji = "\uD83D\uDC62", colorHex = 0xFFC9A86C, description = "Fossil sea urchins preserve the intricate five-fold symmetry of the echinoid test (shell). The pattern of plates, tubercles, and the distinctive star-shaped apical disc are often preserved in exquisite detail.", formation = "Sea urchin tests were buried in chalk and limestone on the seafloor. Their calcite structure fossilizes exceptionally well.", hardness = "—", luster = "Dull to vitreous", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "White", "Tan", "Brown"), whereFound = listOf("England ( chalk cliffs)", "Texas, USA", "Florida, USA", "France"), funFacts = listOf("Fossil sea urchins were called 'fairy loaves' in medieval England.", "The five-fold symmetry is the same pattern you see on starfish and sand dollars.", "Some echinoid fossils still have their spines attached."), uses = "Collector specimens, jewelry, educational displays.", rarity = "Common", geologicalPeriod = "Ordovician – Present", age = "450 mya – today"),
        Specimen(id = "starfish-fossil", name = "Starfish - Fossilized", rockClass = RockClass.FOSSIL, category = "Echinoderm — Asteroidea", tagline = "Five arms frozen in ancient seafloor mud.", emoji = "\u2B50", colorHex = 0xFFD4B88C, description = "Fossil starfish are rare because their multi-plate skeletons typically disarticulate after death. Complete specimens are found in fine-grained sediments that buried them rapidly.", formation = "Rapid burial in fine marine sediment preserved the articulated skeleton before it could disintegrate.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Tan", "Orange-brown"), whereFound = listOf("Germany (Solnhofen)", "Indiana, USA", "England", "Morocco"), funFacts = listOf("Complete fossil starfish are rare and prized \u2014 the arms usually separate after death.", "Starfish can regenerate lost arms \u2014 fossil specimens sometimes show this.", "The Solnhofen limestone in Germany produces some of the finest fossil starfish."), uses = "Collector specimens, educational displays.", rarity = "Rare (complete)", geologicalPeriod = "Ordovician – Present", age = "450 mya – today"),
        Specimen(id = "stingray-barb", name = "Stingray Barb - Fossilized", rockClass = RockClass.FOSSIL, category = "Fish — Myliobatiformes", tagline = "A prehistoric venomous weapon frozen in time.", emoji = "\uD83E\uDEB6", colorHex = 0xFFC4A46A, description = "Fossil stingray barbs are the serrated, barbed spines from the tails of ancient rays. These defensive weapons are found in marine and freshwater deposits worldwide, particularly in Eocene and Miocene sediments.", formation = "Barbs were shed naturally or buried after death. Their dense, enameloid structure preserves well.", hardness = "—", luster = "Enameloid to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate / Enameloid", commonColors = listOf("Brown", "Tan", "Gray"), whereFound = listOf("Florida, USA", "Maryland, USA", "Morocco", "France"), funFacts = listOf("Fossil barbs still have visible serrations along the edges.", "Modern stingrays shed and regrow their barbs annually \u2014 fossils suggest ancient rays did too.", "Some fossil barbs show signs of having been used defensively against predators."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Eocene – Pliocene", age = "56 – 2.6 mya"),
        Specimen(id = "fusulinid", name = "Fusulinid (Giant Foraminifera)", rockClass = RockClass.FOSSIL, category = "Microfossil — Foraminifera", tagline = "Rice-grain fossils that date ancient rocks.", emoji = "\uD83C\uDF3E", colorHex = 0xFFC8B88C, description = "Fusulinids were giant single-celled organisms (foraminifera) that built rice-grain-sized calcite shells. They evolved rapidly and are among the most important index fossils for dating Carboniferous and Permian rocks.", formation = "Microscopic shells accumulated in vast numbers on shallow seafloors, forming fusulinid limestone beds.", hardness = "—", luster = "Dull to vitreous", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("White", "Gray", "Tan"), whereFound = listOf("Kansas, USA", "Texas, USA", "Oklahoma, USA", "China"), funFacts = listOf("Fusulinids are the largest foraminifera ever \u2014 some reached 2 inches.", "They are so abundant that entire limestone beds are made of their shells.", "They went extinct in the Permian mass extinction."), uses = "Index fossils, educational displays, limestone.", rarity = "Common", geologicalPeriod = "Carboniferous – Permian", age = "323 – 252 mya"),
        Specimen(id = "gaspeite", name = "Gaspeite", rockClass = RockClass.MINERAL, category = "Carbonate mineral", tagline = "Apple-green nickel carbonate — Western Australia's gem.", emoji = "\uD83D\uDFE2", colorHex = 0xFF66AA55, description = "Gaspeite is a rare nickel carbonate with a vivid apple-green color. The finest material comes from Western Australia and is cut into stunning cabochons and carvings.", formation = "Forms in the oxidized zone of nickel sulfide deposits in ultramafic rocks.", hardness = "4.5\u20135", luster = "Vitreous to waxy", streak = "Pale green", crystalSystem = "Trigonal", chemicalFormula = "(Ni,Mg,Fe)CO\u2083", commonColors = listOf("Apple green", "Bright green", "Pale green", "Yellowish-green"), whereFound = listOf("Western Australia", "Quebec, Canada", "New Mexico, USA"), funFacts = listOf("Named after the Gasp\u00E9 Peninsula in Quebec where it was discovered.", "Often mixed with magnesite to create striking color contrasts.", "One of the few bright green carbonate minerals."), uses = "Cabochons, jewelry, carvings.", rarity = "Rare"),
        Specimen(id = "giant-sloth-claw", name = "Giant Ground Sloth Claw", rockClass = RockClass.FOSSIL, category = "Mammal — Xenarthra", tagline = "The 12-inch claw of the elephant-sized sloth.", emoji = "\uD83E\uDDA5", colorHex = 0xFFA0805E, description = "Giant ground sloths (Megatherium) were elephant-sized herbivores with enormous curved claws up to 12 inches long. The claws were used to pull down branches and for defense against ice age predators.", formation = "Claws and bones were preserved in caves, river deposits, and occasionally in ancient dung deposits.", hardness = "—", luster = "Dull to horn-like", streak = "—", crystalSystem = "N/A", chemicalFormula = "Keratin / Phosphate", commonColors = listOf("Brown", "Dark brown", "Gray"), whereFound = listOf("Florida, USA", "Arizona, USA", "Argentina", "Brazil"), funFacts = listOf("Giant ground sloths were among the largest land mammals ever \u2014 over 20 feet tall on hind legs.", "Their fossilized dung has been found in caves and studied for ancient plant DNA.", "They walked on the sides of their feet because their claws were too long."), uses = "Collector specimens, museum displays.", rarity = "Rare", geologicalPeriod = "Pleistocene", age = "2.5 million – 10,000 years ago"),
        Specimen(id = "ginkgo-fossil", name = "Ginkgo Fossil", rockClass = RockClass.FOSSIL, category = "Plant — Ginkgophyta", tagline = "The fan-shaped leaf of a 270-million-year-old lineage.", emoji = "\uD83C\uDF43", colorHex = 0xFF7A8B5A, description = "Ginkgo leaves have a distinctive fan shape with radiating veins \u2014 a design that has remained almost unchanged for over 270 million years. Fossil ginkgo leaves are found worldwide from the Permian through the Cenozoic.", formation = "Leaves fell into quiet water and were preserved as carbon films and impressions in fine-grained shale and siltstone.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Carbon film", commonColors = listOf("Black on gray", "Dark brown"), whereFound = listOf("Oregon, USA", "Washington, USA", "China", "Scotland"), funFacts = listOf("The living Ginkgo biloba is the only surviving species of an entire plant division.", "Ginkgo trees survived the Hiroshima atomic bomb \u2014 they're incredibly resilient.", "Fossil ginkgo leaves are virtually identical to modern ones."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Permian – Present", age = "270 mya – today"),
        Specimen(id = "glaucophane", name = "Glaucophane", rockClass = RockClass.MINERAL, category = "Silicate — Amphibole group", tagline = "Lavender-blue prisms — the signature mineral of subduction zones.", emoji = "\uD83D\uDC99", colorHex = 0xFF5566BB, description = "Glaucophane is a sodium amphibole with a distinctive lavender-blue to gray-blue color. It defines the blueschist metamorphic facies and forms in subduction zones where cold oceanic crust plunges deep into the mantle.", formation = "Crystallizes under high pressure and relatively low temperature in subduction zone metamorphic rocks.", hardness = "6–6.5", luster = "Vitreous to pearly", streak = "Grayish-blue", crystalSystem = "Monoclinic", chemicalFormula = "Na₂(Mg₃Al₂)Si₈O₂₂(OH)₂", commonColors = listOf("Lavender-blue", "Gray-blue", "Deep blue", "Black"), whereFound = listOf("California, USA", "Greece", "Japan", "France"), funFacts = listOf("Glaucophane defines the blueschist facies — a key metamorphic indicator.", "Its presence signals that rocks were once in a subduction zone.", "Named from Greek 'glaukos' meaning bluish-gray."), uses = "Metamorphic indicator mineral, collector specimens.", rarity = "Common"),
        Specimen(id = "glossopteris", name = "Glossopteris (Tongue Fern)", rockClass = RockClass.FOSSIL, category = "Plant — Glossopteridales", tagline = "The leaf that proved continental drift.", emoji = "\uD83C\uDF3F", colorHex = 0xFF5B6B3E, description = "Glossopteris was a Permian seed fern with distinctive tongue-shaped leaves. Its fossils were found across all southern continents, providing key evidence for Alfred Wegener's theory of continental drift and the existence of Gondwana.", formation = "Leaves were buried in Permian swamp sediments and preserved as carbon films and impressions in shale and coal deposits.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Carbon film", commonColors = listOf("Black on gray", "Dark brown"), whereFound = listOf("South Africa", "India", "Antarctica", "Australia"), funFacts = listOf("Glossopteris fossils on Antarctica, Africa, India, Australia, and South America proved Gondwana existed.", "Alfred Wegener used Glossopteris as evidence for his theory of continental drift.", "The name means 'tongue fern' \u2014 from the leaf shape."), uses = "Collector specimens, educational displays, scientific study.", rarity = "Common", geologicalPeriod = "Permian", age = "299 – 252 mya"),
        Specimen(id = "goethite", name = "Goethite", rockClass = RockClass.MINERAL, category = "Oxide mineral — Iron hydroxide", tagline = "Rusty-brown botryoidal masses — Mars is covered in it.", emoji = "\uD83E\uDE9B", colorHex = 0xFF6B4226, description = "Goethite is an iron hydroxide mineral that forms dark brown to black botryoidal masses with a velvety interior, often showing iridescent rainbow tarnish. It gives many soils their yellowish-brown color and was named after the German poet Goethe.", formation = "Weathering product of iron-rich minerals. Forms in bogs, swamps, and the oxidized zone of iron deposits.", hardness = "5–5.5", luster = "Adamantine to velvety", streak = "Brownish-yellow", crystalSystem = "Orthorhombic", chemicalFormula = "FeO(OH)", commonColors = listOf("Dark brown", "Black", "Yellowish", "Rainbow tarnish"), whereFound = listOf("Michigan, USA", "Colorado, USA", "Germany", "Brazil"), funFacts = listOf("Goethite is named after Johann Wolfgang von Goethe, the German poet and naturalist.", "Mars is red because of goethite and hematite dust on its surface.", "Botryoidal goethite sometimes shows stunning iridescent rainbow colors."), uses = "Iron ore, yellow/brown pigments, mineral specimens.", rarity = "Common"),
        Specimen(id = "golden-sheen-obsidian", name = "Obsidian, Golden Sheen", rockClass = RockClass.IGNEOUS, category = "Volcanic glass", tagline = "Warm golden glow trapped in obsidian glass.", emoji = "\uD83C\u1F31E", colorHex = 0xFFCC9944, description = "Golden sheen obsidian displays a warm honey-golden metallic reflection across its dark surface. The golden flash looks like captured sunlight frozen in volcanic glass.", formation = "Tiny mineral inclusions or aligned gas bubbles within flowing obsidian reflect golden light.", hardness = "5-6", luster = "Vitreous with golden metallic sheen", streak = "\u2014", crystalSystem = "Amorphous", chemicalFormula = "SiO2 (glass)", commonColors = listOf("Black with gold", "Dark brown with golden flash"), whereFound = listOf("Oregon, USA", "Davis Creek, California, USA", "Mexico"), funFacts = listOf("Golden sheen is rarer than silver sheen.", "Often called 'honey obsidian' for its warm tone.", "The sheen is directional — tilt to see the flash."), uses = "Jewelry, cabochons.", rarity = "Uncommon"),
        Specimen(id = "goniatite", name = "Goniatite", rockClass = RockClass.FOSSIL, category = "Cephalopod — Goniatitida", tagline = "The coiled ancestor of ammonites with simpler shells.", emoji = "\uD83D\uDC0C", colorHex = 0xFFB08E6A, description = "Goniatites were early ammonoid cephalopods that thrived in Devonian and Carboniferous seas. Their shells have simpler, wavy suture patterns compared to the complex frilled sutures of later ammonites \u2014 a key identification feature.", formation = "Shells sank to the seafloor and were buried in marine limestone and shale. The simpler shell structure is easy to identify.", hardness = "—", luster = "Dull to pearly", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite / Aragonite replacement", commonColors = listOf("Brown", "Gray", "Tan"), whereFound = listOf("Morocco", "Germany", "Kentucky, USA", "Ireland"), funFacts = listOf("Goniatite sutures are zigzag 'V' shapes \u2014 simpler than ammonite sutures.", "They evolved rapidly and make excellent index fossils for the Devonian and Carboniferous.", "Goniatites survived the Devonian mass extinction that wiped out many marine species."), uses = "Index fossils, collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Devonian – Permian", age = "419 – 252 mya"),
        Specimen(id = "grandidierite", name = "Grandidierite", rockClass = RockClass.CRYSTAL, category = "Silicate — Nesosilicate", tagline = "Blue-green gem rarer than diamond — Madagascar's treasure.", emoji = "\uD83D\uDC9A", colorHex = 0xFF44AA99, description = "Grandidierite is a magnesium aluminum borosilicate with a distinctive bluish-green color. For decades, only a handful of crystals were known — it's among the rarest and most valuable collector gemstones.", formation = "Crystallizes in high-grade metamorphic rocks rich in boron and aluminum.", hardness = "7.5", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "(Mg,Fe)Al\u2083(BO\u2083)(SiO\u2084)O\u2082", commonColors = listOf("Blue-green", "Teal", "Mint", "Sea green"), whereFound = listOf("Madagascar", "Sri Lanka", "Namibia", "Malawi"), funFacts = listOf("Named after French explorer Alfred Grandidier.", "For decades only a few faceted specimens existed worldwide.", "Its trichroism shows three different colors."), uses = "Ultra-rare collector gemstone.", rarity = "Extremely Rare"),
        Specimen(id = "graptolite", name = "Graptolite - Fossilized", rockClass = RockClass.FOSSIL, category = "Hemichordate — Graptolithina", tagline = "Saw-blade plankton from the earliest oceans.", emoji = "\uD83D\uDCC8", colorHex = 0xFF595959, description = "Graptolites were colonial planktonic animals that drifted in Paleozoic oceans. Their saw-tooth fossil impressions look like tiny hacksaw blades — and they are among the most important index fossils for dating Ordovician and Silurian rocks.", formation = "Colonies sank after death and were preserved as flat, carbonized films in black shales.", hardness = "—", luster = "Dull to metallic", streak = "—", crystalSystem = "N/A", chemicalFormula = "Carbon film", commonColors = listOf("Black", "Gray", "Slightly metallic"), whereFound = listOf("New York, USA", "Wales", "Scotland", "Australia"), funFacts = listOf("Graptolites evolve so rapidly that individual species define narrow time zones.", "Their name means 'written rock' — they look like ancient writing.", "They were once mistaken for plant fossils."), uses = "Index fossils for dating rock layers — extremely important to geology.", rarity = "Common", geologicalPeriod = "Cambrian – Carboniferous", age = "541 – 299 mya"),
        Specimen(id = "wacke", name = "Graywacke", rockClass = RockClass.SEDIMENTARY, category = "Clastic sedimentary rock", tagline = "Dirty sandstone — a jumble of sand, silt, and clay.", emoji = "\uD83E\uDEA8", colorHex = 0xFF666666, description = "Graywacke is a poorly sorted sandstone containing a mix of sand, silt, and clay in a muddy matrix. It forms from submarine landslides (turbidity currents) and is a classic rock of deep-sea fans.", formation = "Deposited by turbidity currents \u2014 underwater avalanches that carry mixed sediment down continental slopes.", hardness = "6\u20137 (hard)", luster = "Dull", streak = "\u2014", crystalSystem = "Clastic aggregate (poorly sorted)", chemicalFormula = "Mixed quartz, feldspar, rock fragments in clay", commonColors = listOf("Dark gray", "Greenish-gray", "Brown"), whereFound = listOf("Wales", "Scotland", "New Zealand", "California, USA"), funFacts = listOf("Graywacke is the most common sandstone type in the geological record.", "Each bed represents an underwater avalanche.", "The name comes from German 'grauwacke' meaning 'gray earthy rock.'"), uses = "Building stone, aggregate, geological research.", rarity = "Common"),
        Specimen(id = "great-white-tooth", name = "Great White Shark Tooth - Fossilized", rockClass = RockClass.FOSSIL, category = "Fish — Lamnidae", tagline = "The triangular blade of the ocean's most famous predator.", emoji = "\uD83E\uDD88", colorHex = 0xFF4A5258, description = "Fossil great white shark teeth are triangular, serrated blades that can reach over 2.5 inches. They are found in Miocene and Pliocene marine deposits worldwide and are highly collectible.", formation = "Sharks constantly shed teeth. Those that settled on the seafloor in phosphate-rich sediment mineralized over millions of years.", hardness = "—", luster = "Enameloid", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate", commonColors = listOf("Gray-blue", "Brown", "Black", "White"), whereFound = listOf("Florida, USA", "California, USA", "Peru", "Japan"), funFacts = listOf("Great white sharks have been around for at least 16 million years.", "Fossil teeth are often larger than modern teeth because the sharks were bigger.", "The serrations are so sharp they can still cut paper after millions of years."), uses = "Collector specimens, jewelry, educational displays.", rarity = "Common", geologicalPeriod = "Miocene – Present", age = "16 mya – today"),
        Specimen(id = "greenschist", name = "Schist, Green", rockClass = RockClass.METAMORPHIC, category = "Low-grade metamorphic rock", tagline = "Green with chlorite — the signature of moderate mountain-building.", emoji = "\uD83D\uDFE2", colorHex = 0xFF446644, description = "Greenschist is a low-grade metamorphic rock colored green by chlorite, epidote, and actinolite. It defines the greenschist facies — a key metamorphic grade indicating moderate temperatures and pressures.", formation = "Basalt or graywacke metamorphosed at moderate temperature and pressure (300-500°C).", hardness = "\u2014", luster = "Dull to pearly", streak = "\u2014", crystalSystem = "Schistose (foliated)", chemicalFormula = "Mixed silicates (mafic)", commonColors = listOf("Green", "Gray-green", "Dark olive"), whereFound = listOf("Alps, Switzerland", "Scotland", "New Zealand", "California, USA"), funFacts = listOf("The green color comes from chlorite.", "Greenschist facies rocks are found in virtually every mountain range.", "It's a key indicator of moderate-grade regional metamorphism."), uses = "Building stone, crushed aggregate, metamorphic research.", rarity = "Common"),
        Specimen(id = "grossular", name = "Garnet, Grossular", rockClass = RockClass.CRYSTAL, category = "Silicate — Garnet group", tagline = "Colorful calcium garnet — from cinnamon to mint green.", emoji = "\uD83C\uDF39", colorHex = 0xFFCC8844, description = "Grossular is the calcium aluminum garnet that spans the widest color range of any garnet species — from colorless to cinnamon-orange (hessonite) to mint green (tsavorite) to vivid green (chrome grossular). Rarity: Uncommon (rare for tsavorite).", formation = "Crystallizes in contact metamorphic rocks, particularly where limestone has been altered by granitic intrusions.", hardness = "6.5–7.5", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "Ca₃Al₂(SiO₄)₃", commonColors = listOf("Cinnamon (hessonite)", "Mint green (tsavorite)", "Emerald green", "Colorless", "Pink"), whereFound = listOf("Kenya (tsavorite)", "Tanzania", "Canada", "Mexico"), funFacts = listOf("Tsavorite is a brilliant green grossular named after Tsavo National Park in Kenya.", "Hessonite is the cinnamon-colored variety — called 'cinnamon stone.'", "Grossular is named from Latin 'grossularia' meaning gooseberry."), uses = "Gemstone (hessonite, tsavorite), collector specimens.", rarity = "Uncommon (rare for tsavorite)"),
        Specimen(id = "gryphaea", name = "Gryphaea - Fossilized", rockClass = RockClass.FOSSIL, category = "Mollusk — Bivalvia", tagline = "The curled oyster that looks like a toenail.", emoji = "\uD83D\uDC63", colorHex = 0xFFB0A090, description = "Gryphaea is an extinct oyster with a distinctive thick, curled shell. The larger left valve is strongly incurved while the right valve is flat \u2014 giving it the nickname 'devil's toenail.' They are common in Jurassic and Cretaceous rocks.", formation = "Shells accumulated on the seafloor and were buried in marine mud. Their thick, calcite shells preserve beautifully.", hardness = "—", luster = "Dull to pearly", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan"), whereFound = listOf("England", "Texas, USA", "Kansas, USA", "France"), funFacts = listOf("Medieval Europeans believed gryphaea fossils were the devil's toenails.", "They were used as a folk remedy for joint pain.", "Gryphaea is a classic index fossil for the Jurassic."), uses = "Collector specimens, educational displays, index fossils.", rarity = "Common", geologicalPeriod = "Jurassic – Cretaceous", age = "201 – 66 mya"),
        Specimen(id = "gyrolite", name = "Gyrolite", rockClass = RockClass.MINERAL, category = "Silicate — Phyllosilicate", tagline = "Pale green spherical clusters — nature's moss balls.", emoji = "\uD83E\uDEA2", colorHex = 0xFFCCDDCC, description = "Gyrolite is a hydrated calcium silicate forming pale green to white spherical aggregates that look like moss balls. It often occurs alongside apophyllite and okenite in Indian basalt quarries.", formation = "Crystallizes in basalt cavities from calcium-rich hydrothermal fluids.", hardness = "3–4", luster = "Pearly to vitreous", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "NaCa₁₆Si₂₃AlO₆₀(OH)₅·15H₂O", commonColors = listOf("Pale green", "White", "Cream"), whereFound = listOf("India (Pune)", "Oregon, USA", "Greenland", "Northern Ireland"), funFacts = listOf("Gyrolite balls look exactly like tiny green moss balls.", "Named from Greek 'gyros' meaning circle — from its spherical habit.", "Often found with apophyllite and okenite in the same cavities."), uses = "Collector specimens.", rarity = "Uncommon"),
        Specimen(id = "halysites", name = "Halysites - Fossilized", rockClass = RockClass.FOSSIL, category = "Cnidarian — Tabulata", tagline = "The coral that looks like a stone chain link fence.", emoji = "\uD83D\uDD17", colorHex = 0xFFC4A66C, description = "Halysites is an extinct tabulate coral whose corallites are arranged in distinctive chains that wind through the rock \u2014 each link connected to its neighbors like a stone chain-link fence. They lived during the Silurian and Devonian.", formation = "Colonies were buried in shallow sea carbonate mud. The unique chain-like corallite arrangement is unmistakable.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan", "White"), whereFound = listOf("Ohio, USA", "Indiana, USA", "Michigan, USA", "England"), funFacts = listOf("The chain pattern is so distinctive that Halysites is also called 'chain coral.'", "The chains were formed when corallites grew in a single file, connected by small tubes.", "Chain coral is a common find in midwestern Silurian-aged limestone."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Silurian – Devonian", age = "444 – 359 mya"),
        Specimen(id = "hambergite", name = "Hambergite", rockClass = RockClass.MINERAL, category = "Borate mineral", tagline = "Colorless beryllium borate — a forgotten gem.", emoji = "\uD83D\uDC8E", colorHex = 0xFFF8F8F0, description = "Hambergite is a rare beryllium borate forming colorless to white prismatic crystals. It's one of the few beryllium-bearing minerals and an extremely obscure collector's stone.", formation = "Crystallizes in alkaline pegmatites and miarolitic cavities in granite.", hardness = "7.5", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Be\u2082BO\u2083(OH)", commonColors = listOf("Colorless", "White", "Grayish"), whereFound = listOf("Madagascar", "Norway", "Afghanistan", "Maine, USA"), funFacts = listOf("Named after Swedish mineralogist Axel Hamberg.", "Harder than quartz at 7.5 — surprisingly durable.", "Extremely rare — most collectors have never seen one."), uses = "Collector specimens only.", rarity = "Rare"),
        Specimen(id = "helicoprion", name = "Helicoprion - Fossilized", rockClass = RockClass.FOSSIL, category = "Fish — Eugeneodontida", tagline = "The shark with a buzzsaw in its mouth.", emoji = "\uD83E\uDE88", colorHex = 0xFF7C7C7C, description = "Helicoprion was a bizarre shark-like fish with a spiral whorl of teeth in its lower jaw. For over a century, paleontologists debated where the whorl was located \u2014 it's now believed to have been inside the lower jaw like a circular saw.", formation = "The tooth whorls were preserved in marine limestone and shale of the Permian period. The rest of the cartilaginous skeleton rarely fossilized.", hardness = "—", luster = "Enameloid", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate", commonColors = listOf("Black", "Dark brown", "Gray"), whereFound = listOf("Idaho, USA", "Russia", "Australia", "China"), funFacts = listOf("The tooth whorl was first described in 1899 and baffled scientists for over 100 years.", "Each tooth in the spiral is a different size, forming a perfect logarithmic spiral.", "Helicoprion lived through the Permian-Triassic extinction \u2014 the worst mass extinction ever."), uses = "Collector specimens, museum displays, scientific study.", rarity = "Rare", geologicalPeriod = "Permian", age = "290 – 252 mya"),
        Specimen(id = "heulandite", name = "Heulandite", rockClass = RockClass.MINERAL, category = "Silicate — Zeolite group", tagline = "Coffin-shaped crystals in warm earthy hues.", emoji = "\uD83E\uDEB9", colorHex = 0xFFCC9966, description = "Heulandite is a zeolite forming distinctive coffin-shaped (tabular) crystals in shades of white, cream, pink, and brown. It's one of the most common and recognizable zeolites in basalt cavities.", formation = "Deposits from low-temperature hydrothermal solutions in basalt cavities and fractures.", hardness = "3.5–4", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "(Ca,Na)₂₋₃Al₃(Al,Si)₅Si₁₃O₃₆·12H₂O", commonColors = listOf("White", "Cream", "Pink", "Brown", "Red"), whereFound = listOf("Iceland", "India", "Nova Scotia, Canada", "Oregon, USA"), funFacts = listOf("Named after English mineral collector Henry Heuland.", "The distinctive coffin-shaped crystals are easy to identify.", "It's found in virtually every zeolite locality worldwide."), uses = "Collector specimens, mineral displays.", rarity = "Common"),
        Specimen(id = "hibonite", name = "Hibonite", rockClass = RockClass.MINERAL, category = "Oxide mineral", tagline = "Black-brown crystals older than Earth itself.", emoji = "\uD83C\uDF0C", colorHex = 0xFF332211, description = "Hibonite is a rare calcium aluminum oxide mineral found in some of the oldest meteorites. Some hibonite grains predate the Solar System — they're literally stardust older than Earth.", formation = "Condensed in the atmospheres of ancient stars before being incorporated into meteorites.", hardness = "7.5\u20138", luster = "Vitreous", streak = "Brownish", crystalSystem = "Hexagonal", chemicalFormula = "(Ca,Ce)(Al,Ti,Mg)\u2081\u2082O\u2081\u2089", commonColors = listOf("Black", "Dark brown", "Brownish-black"), whereFound = listOf("Madagascar", "Myanmar", "In meteorites worldwide"), funFacts = listOf("Some hibonite grains are older than the Solar System itself.", "Named after French prospector Paul Hibon who discovered it in Madagascar.", "It's one of the earliest minerals to condense from a cooling gas cloud."), uses = "Scientific research, pre-solar system studies.", rarity = "Rare"),
        Specimen(id = "hornfels", name = "Hornfels", rockClass = RockClass.METAMORPHIC, category = "Contact metamorphic rock", tagline = "Baked and hardened by magma — nature's ceramic.", emoji = "\uD83C\uDF76", colorHex = 0xFF665544, description = "Hornfels is a fine-grained contact metamorphic rock formed when shale or other rocks are baked by an adjacent magma intrusion. The heat recrystallizes the rock into a hard, splintery, almost ceramic-like material.", formation = "Sedimentary rocks are baked and recrystallized by the heat of a nearby igneous intrusion.", hardness = "6\u20137 (hard)", luster = "Dull to vitreous", streak = "\u2014", crystalSystem = "Granoblastic", chemicalFormula = "Mixed silicates (recrystallized)", commonColors = listOf("Dark gray", "Black", "Brown", "Greenish"), whereFound = listOf("England", "Germany", "Scotland", "California, USA"), funFacts = listOf("Hornfels is so hard it rings when struck \u2014 like ceramic.", "Named from German 'horn' (horn) for its toughness.", "It's one of the hardest metamorphic rocks."), uses = "Road aggregate, building stone, whetstones.", rarity = "Common"),
        Specimen(id = "horseshoe-crab", name = "Horseshoe Crab - Fossilized", rockClass = RockClass.FOSSIL, category = "Arthropod — Xiphosura", tagline = "The living fossil that predates the dinosaurs.", emoji = "\uD83E\uDEB2", colorHex = 0xFF8B6D4E, description = "Horseshoe crabs have remained virtually unchanged for over 450 million years. Their fossilized carapaces and occasional complete specimens are found in Paleozoic and Mesozoic rocks worldwide.", formation = "Molted exoskeletons and carcasses were buried in shallow marine sediments. The distinctive horseshoe shape fossilizes well.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite / Limonite", commonColors = listOf("Brown", "Gray", "Dark tan"), whereFound = listOf("New York, USA", "Germany (Solnhofen)", "England", "Canada"), funFacts = listOf("Horseshoe crabs are more closely related to spiders and scorpions than crabs.", "Their blue blood is used to test for bacterial contamination in medical equipment.", "They survived all five mass extinctions with virtually no change in body plan."), uses = "Collector specimens, educational displays, scientific study.", rarity = "Uncommon", geologicalPeriod = "Ordovician – Present", age = "450 mya – today"),
        Specimen(id = "huebnerite", name = "Huebnerite", rockClass = RockClass.MINERAL, category = "Tungstate mineral", tagline = "Manganese-rich wolframite — reddish-brown blades.", emoji = "\uD83E\uDE9B", colorHex = 0xFF663322, description = "Huebnerite is the manganese-rich end member of the wolframite series, with reddish-brown to brownish-black bladed crystals. It's named after Adolph Huebner, a German mineralogist.", formation = "Deposited from high-temperature hydrothermal fluids in quartz veins, similar to ferberite.", hardness = "4\u20134.5", luster = "Submetallic to resinous", streak = "Greenish-gray to reddish-brown", crystalSystem = "Monoclinic", chemicalFormula = "MnWO\u2084", commonColors = listOf("Reddish-brown", "Brownish-black", "Dark brown"), whereFound = listOf("Peru", "Bolivia", "Colorado, USA", "China"), funFacts = listOf("Huebnerite is the manganese end member of the wolframite series.", "It shows a distinctive reddish internal reflection.", "Often found alongside quartz and fluorite in vein deposits."), uses = "Tungsten ore, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "hybodus", name = "Hybodus Tooth - Fossilized", rockClass = RockClass.FOSSIL, category = "Fish — Hybodontiformes", tagline = "The survivor shark with horns and two types of teeth.", emoji = "\uD83E\uDD88", colorHex = 0xFF6B5B4E, description = "Hybodus was a prehistoric shark that survived from the Permian through the Cretaceous \u2014 over 200 million years. It had two types of teeth: sharp front teeth for seizing and flat back teeth for crushing.", formation = "Teeth and dorsal fin spines were preserved in marine and freshwater sediments.", hardness = "—", luster = "Enameloid", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate", commonColors = listOf("Brown", "Black", "Gray"), whereFound = listOf("England", "Morocco", "Kansas, USA", "China"), funFacts = listOf("Hybodus had two dorsal fin spines that may have been defensive weapons.", "It survived the Permian-Triassic extinction that killed 96% of marine life.", "The dual-tooth system made it a versatile hunter."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Permian – Cretaceous", age = "299 – 66 mya"),
        Specimen(id = "hypersthene", name = "Hypersthene", rockClass = RockClass.MINERAL, category = "Silicate — Pyroxene group", tagline = "Bronze-brown with copper flash — a stone of inner vision.", emoji = "\uD83D\uDD36", colorHex = 0xFF886644, description = "Hypersthene is an iron-magnesium pyroxene with a distinctive bronze-brown color and metallic copper-red schiller. When cut as cabochons, the reflective flash across its surface is dramatic and beautiful.", formation = "Crystallizes in mafic igneous rocks like norite and gabbro, and in some metamorphic rocks.", hardness = "5.5–6", luster = "Vitreous to metallic (schiller)", streak = "Grayish-white", crystalSystem = "Orthorhombic", chemicalFormula = "(Mg,Fe)SiO₃", commonColors = listOf("Bronze-brown", "Copper-red (schiller)", "Black", "Greenish-brown"), whereFound = listOf("Canada", "Norway", "New York, USA", "India"), funFacts = listOf("The copper-red schiller on hypersthene is called 'labradorescence' — but it's iron, not labradorite.", "Named from Greek 'hyper' (above) and 'sthenos' (strength).", "Often found alongside labradorite in the Adirondack Mountains."), uses = "Cabochons, collector specimens, ornamental stone.", rarity = "Common"),
        Specimen(id = "ichthyosaur-vertebra", name = "Ichthyosaur Vertebra", rockClass = RockClass.FOSSIL, category = "Reptile — Ichthyosauria", tagline = "The fish-lizard backbone of Jurassic seas.", emoji = "\uD83E\uDD96", colorHex = 0xFF8B7355, description = "Ichthyosaurs were dolphin-shaped marine reptiles that swam Jurassic and Cretaceous seas. Their distinctive vertebrae are short and spool-shaped — often found isolated on beaches and in Jurassic clay deposits.", formation = "Vertebrae became separated after death and were buried in marine sediments. Their dense bone structure makes them resistant to erosion.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate / Calcite", commonColors = listOf("Brown", "Gray", "Black"), whereFound = listOf("England (Jurassic Coast)", "Germany", "Nevada, USA", "Alberta, Canada"), funFacts = listOf("Ichthyosaurs gave live birth — fossils have been found with embryos inside.", "Mary Anning discovered the first complete ichthyosaur skeleton at age 12.", "They had the largest eyes of any vertebrate — up to 10 inches across."), uses = "Collector specimens, educational displays.", rarity = "Uncommon", geologicalPeriod = "Jurassic – Cretaceous", age = "201 – 90 mya"),
        Specimen(id = "inoceramus", name = "Inoceramus - Fossilized", rockClass = RockClass.FOSSIL, category = "Mollusk — Bivalvia", tagline = "The dinner-plate-sized clam of the Cretaceous seaway.", emoji = "\uD83D\uDC1A", colorHex = 0xFFC4B090, description = "Inoceramus was a genus of giant clams that could grow over 3 feet across. Their large, thin-shelled fossils are common in Cretaceous marine deposits worldwide and are especially abundant in the Western Interior Seaway.", formation = "Shells were buried in chalk and marine shale. Their distinctive growth rings and fibrous calcite shell structure are often well preserved.", hardness = "—", luster = "Pearly to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "White (weathered)"), whereFound = listOf("Kansas, USA", "South Dakota, USA", "England", "Germany"), funFacts = listOf("Some Inoceramus shells reached over 3 feet in diameter \u2014 the size of a manhole cover.", "They are so common in parts of Kansas that farmers plow them up regularly.", "The shell is made of fibrous calcite that looks like silky fibers under magnification."), uses = "Collector specimens, index fossils, educational displays.", rarity = "Common", geologicalPeriod = "Jurassic – Cretaceous", age = "170 – 66 mya"),
        Specimen(id = "jeremejevite", name = "Jeremejevite", rockClass = RockClass.CRYSTAL, category = "Borate mineral", tagline = "Cornflower-blue prisms from Namibia's desert.", emoji = "\uD83D\uDC99", colorHex = 0xFF5588CC, description = "Jeremejevite is aluminum borate forming delicate cornflower-blue hexagonal prisms. The finest crystals come from the Erongo Mountains of Namibia and are among the most sought-after rare gem minerals.", formation = "Crystallizes in granitic pegmatites and miarolitic cavities.", hardness = "6.5\u20137.5", luster = "Vitreous", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "Al\u2086B\u2085O\u2081\u2085(F,OH)\u2083", commonColors = listOf("Cornflower blue", "Colorless", "Pale yellow", "Lilac"), whereFound = listOf("Erongo Mountains, Namibia", "Tajikistan", "Germany", "Siberia, Russia"), funFacts = listOf("Named after Russian mineralogist Pavel Jeremejev.", "Namibian jeremejevite is considered the world's finest.", "A faceted jeremejevite is a museum piece."), uses = "Ultra-rare collector gemstone.", rarity = "Extremely Rare"),
        Specimen(id = "joaquinite", name = "Joaquinite", rockClass = RockClass.MINERAL, category = "Silicate — Cyclosilicate", tagline = "Honey-brown crystals — another California exclusive.", emoji = "\uD83C\uDF6F", colorHex = 0xFFCC9944, description = "Joaquinite is a rare barium sodium cerium iron titanium silicate found alongside benitoite and neptunite in California. Honey-brown and extremely rare, it's one of the few titanium rare-earth silicates.", formation = "Crystallizes in the same glaucophane schist veins as benitoite.", hardness = "5\u20135.5", luster = "Vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "Ba\u2082NaCe\u2082FeTi\u2082Si\u2088O\u2082\u2086(OH,F)\u00B7H\u2082O", commonColors = listOf("Honey-brown", "Yellow", "Orange-brown"), whereFound = listOf("San Benito County, California, USA"), funFacts = listOf("Joaquinite is named after the Joaquin Valley in California.", "Found only at the same deposit as benitoite.", "It's one of the world's rarest rare-earth silicate minerals."), uses = "Collector specimens.", rarity = "Extremely Rare"),
        Specimen(id = "komatiite", name = "Komatiite", rockClass = RockClass.IGNEOUS, category = "Extrusive volcanic rock (ultramafic)", tagline = "Earth's hottest lava — only erupted in the Archean Eon.", emoji = "\uD83D\uDD25", colorHex = 0xFF334422, description = "Komatiite is a rare ultramafic volcanic rock that erupted at temperatures exceeding 1,600°C. Its distinctive spinifex texture of intergrown bladed olivine crystals looks like blades of grass frozen in stone.", formation = "Erupted from Earth's much hotter mantle during the Archean Eon, over 2.5 billion years ago.", hardness = "5.5\u20136.5", luster = "Dull to vitreous", streak = "\u2014", crystalSystem = "Spinifex (bladed olivine)", chemicalFormula = "Ultramafic silicates (high Mg)", commonColors = listOf("Dark green", "Black", "Gray-green"), whereFound = listOf("Western Australia", "South Africa (Barberton)", "Ontario, Canada", "Zimbabwe"), funFacts = listOf("Komatiite erupted at over 1,600°C \u2014 300 degrees hotter than modern lava.", "The spinifex texture looks like blades of grass frozen in stone.", "Named after the Komati River in South Africa."), uses = "Nickel ore, geological research, Earth's thermal history.", rarity = "Rare"),
        Specimen(id = "spectrolite", name = "Labradorite, Spectrolite", rockClass = RockClass.MINERAL, category = "Silicate — Feldspar variety", tagline = "The full-color labradorite — every spectrum flash at once.", emoji = "\uD83C\uDF08", colorHex = 0xFF335577, description = "Spectrolite is the trade name for high-grade labradorite from Finland that displays the full visible spectrum in its labradorescence — blues, greens, golds, pinks, and purples in a single stone.", formation = "Crystallized in anorthosite bodies under specific conditions that created the perfect labradorescence.", hardness = "6\u20136.5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "(Ca,Na)(Al,Si)\u2084O\u2088", commonColors = listOf("Full spectrum", "Blue-gold-pink", "Peacock"), whereFound = listOf("Yl\u00E4maa, Finland"), funFacts = listOf("Spectrolite is found only in Yl\u00E4maa, Finland.", "It was discovered during WWII while building fortifications.", "Named for the full spectrum of colors it shows."), uses = "Gemstone, jewelry, collector specimens.", rarity = "Rare"),
        Specimen(id = "lazulite", name = "Lazulite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Deep sky-blue crystals — not to be confused with lazurite.", emoji = "\uD83D\uDC99", colorHex = 0xFF3355AA, description = "Lazulite is a magnesium aluminum phosphate with a beautiful sky-blue to azure-blue color. It's often confused with lazurite (lapis lazuli) but is a completely different phosphate mineral.", formation = "Crystallizes in high-grade metamorphic rocks and quartz veins.", hardness = "5.5\u20136", luster = "Vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "MgAl\u2082(PO\u2084)\u2082(OH)\u2082", commonColors = listOf("Azure blue", "Sky blue", "Blue-green"), whereFound = listOf("Austria", "Brazil", "Yukon, Canada", "Georgia, USA"), funFacts = listOf("Lazulite is a phosphate; lazurite (lapis) is a silicate \u2014 completely different.", "Named from Arabic 'lazaward' meaning blue.", "The Graves Mountain locality in Georgia produces stunning specimens."), uses = "Collector specimens, gemstone (rare).", rarity = "Uncommon"),
        Specimen(id = "lepidocrocite", name = "Lepidocrocite", rockClass = RockClass.MINERAL, category = "Oxide mineral — Iron hydroxide", tagline = "Ruby-red scales — goethite's rarer polymorph.", emoji = "\uD83D\uDD34", colorHex = 0xFF992222, description = "Lepidocrocite is a polymorph of goethite — same chemistry but different crystal structure. It forms distinctive ruby-red to reddish-brown scaly crystals that look like tiny mica flakes embedded in quartz or other minerals.", formation = "Oxidation of iron minerals in the presence of water, often in the oxidized zone of ore deposits.", hardness = "5", luster = "Submetallic to adamantine", streak = "Dull orange", crystalSystem = "Orthorhombic", chemicalFormula = "FeO(OH)", commonColors = listOf("Ruby red", "Reddish-brown", "Orange-red"), whereFound = listOf("Germany", "Brazil", "Spain", "New York, USA"), funFacts = listOf("Lepidocrocite means 'scale fiber' — from its scaly crystal habit.", "It's a polymorph of goethite — same chemistry, different structure.", "The ruby-red scaly crystals are often included in rutilated quartz."), uses = "Collector specimens, iron indicator mineral.", rarity = "Uncommon"),
        Specimen(id = "lepidodendron", name = "Lepidodendron (Scale Tree)", rockClass = RockClass.FOSSIL, category = "Plant — Lycopodiophyta", tagline = "The diamond-patterned trunk of the Carboniferous giant.", emoji = "\uD83C\uDF33", colorHex = 0xFF5C5C3A, description = "Lepidodendron was a giant lycopod tree that grew over 100 feet tall in Carboniferous swamps. Its bark is covered in distinctive diamond-shaped leaf scars that look like alligator skin or scales \u2014 hence the name 'scale tree.'", formation = "Bark and trunks were buried in swamp sediments that became coal. The distinctive scale pattern fossilizes beautifully as impressions and casts.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Carbon film", commonColors = listOf("Black on gray", "Dark brown"), whereFound = listOf("Pennsylvania, USA", "Illinois, USA", "England", "Scotland"), funFacts = listOf("Lepidodendron bark looks like reptile scales but is plant tissue.", "They grew rapidly \u2014 reaching full height in 10-15 years \u2014 then reproduced and died.", "The diamond-shaped scars are where leaves were once attached."), uses = "Collector specimens, wall displays, educational displays.", rarity = "Common", geologicalPeriod = "Carboniferous", age = "359 – 299 mya"),
        Specimen(id = "lepidolite", name = "Lepidolite", rockClass = RockClass.MINERAL, category = "Silicate — Phyllosilicate (Mica)", tagline = "Lilac mica — the most important lithium mica mineral.", emoji = "\uD83D\uDC9C", colorHex = 0xFFB088C8, description = "Lepidolite is a lithium-rich mica with a distinctive lilac-to-pink color and pearly luster. It's a major lithium ore and its color is caused by trace manganese — unusual for a mica mineral.", formation = "Crystallizes in lithium-rich granite pegmatites alongside tourmaline and spodumene.", hardness = "2.5–3", luster = "Pearly to vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "K(Li,Al)₃(Si,Al)₄O₁₀(F,OH)₂", commonColors = listOf("Lilac", "Pink", "Purple-gray", "Rose"), whereFound = listOf("Brazil", "California, USA", "Madagascar", "Russia"), funFacts = listOf("Lepidolite is one of the few pink/purple micas — most others are silvery or brown.", "Named from Greek 'lepidos' meaning scale — it flakes like fish scales.", "It's an important lithium ore for batteries."), uses = "Lithium ore, ornamental stone, mineral specimens.", rarity = "Common"),
        Specimen(id = "linarite", name = "Linarite", rockClass = RockClass.MINERAL, category = "Sulfate mineral", tagline = "Electric azure-blue crystals — the most intense blue in the mineral kingdom.", emoji = "\uD83D\uDD35", colorHex = 0xFF0055CC, description = "Linarite is a lead copper sulfate hydroxide with one of the most intense blues found in nature. Its deep azure-blue, bladed crystals rival the finest blue pigments and are instantly recognizable to collectors.", formation = "Weathering of copper and lead sulfide ores in the presence of sulfate-rich water.", hardness = "2.5", luster = "Vitreous to subadamantine", streak = "Pale blue", crystalSystem = "Monoclinic", chemicalFormula = "PbCu(SO\u2084)(OH)\u2082", commonColors = listOf("Deep azure blue", "Cobalt", "Sky blue"), whereFound = listOf("Arizona, USA", "California, USA", "Spain", "Namibia"), funFacts = listOf("Linarite's blue is so intense it's considered the finest blue of any mineral.", "Named after Linares, Spain where it was first found.", "Often mistaken for azurite but has a lighter, more electric blue."), uses = "Collector specimens, lead-copper indicator mineral.", rarity = "Rare"),
        Specimen(id = "lingula", name = "Lingula Brachiopod", rockClass = RockClass.FOSSIL, category = "Brachiopoda — Lingulata", tagline = "The brachiopod that's barely changed in 500 million years.", emoji = "\uD83E\uDEB2", colorHex = 0xFFC4A070, description = "Lingula is a living fossil brachiopod whose shell design has remained virtually unchanged since the Cambrian. The fossil shells are thin, phosphatic, and tongue-shaped \u2014 hence the name (Latin for 'little tongue').", formation = "Phosphatic shells were preserved in marine shales and sandstones. Lingula lived in burrows, and some are preserved in life position.", hardness = "—", luster = "Dull to pearly", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcium phosphate", commonColors = listOf("Dark brown", "Black", "Blue-gray"), whereFound = listOf("Ohio, USA", "New York, USA", "Wales", "China"), funFacts = listOf("Living Lingula still exist today \u2014 almost identical to their 500-million-year-old ancestors.", "They're among the most unchanging organisms in the fossil record.", "The shell is phosphatic rather than calcitic \u2014 unusual for brachiopods."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Cambrian – Present", age = "541 mya – today"),
        Specimen(id = "magnesite", name = "Magnesite", rockClass = RockClass.MINERAL, category = "Carbonate mineral", tagline = "White magnesium carbonate — the mineral for fireproof floors.", emoji = "\uD83E\uDEA7", colorHex = 0xFFF8F8F0, description = "Magnesite is magnesium carbonate, often forming white, porcelain-like masses that look like cauliflower. It's one of the most important magnesium ores and is used to make heat-resistant bricks.", formation = "Forms when magnesium-rich water alters serpentinite and other ultramafic rocks.", hardness = "3.5\u20134.5", luster = "Earthy to vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "MgCO\u2083", commonColors = listOf("White", "Gray", "Yellowish", "Brown"), whereFound = listOf("Austria", "China", "Brazil", "Nevada, USA"), funFacts = listOf("Magnesite is the primary source of magnesium for industry.", "It's used to make firebricks that line steel furnaces.", "Cauliflower magnesite is a distinctive botryoidal form."), uses = "Magnesium ore, refractory bricks, fertilizers, fireproofing.", rarity = "Common"),
        Specimen(id = "malacholla", name = "Malacholla", rockClass = RockClass.MINERAL, category = "Mixed copper mineral", tagline = "Blue and green swirling together — the ultimate copper ore combo.", emoji = "\uD83D\uDC99\uD83D\uDC9A", colorHex = 0xFF339988, description = "Malacholla is a natural mixture of chrysocolla (blue) and malachite (green), creating stunning blue-and-green swirled specimens. It's a lapidary favorite for its dramatic color contrast.", formation = "Forms in copper deposits where both copper carbonate and copper silicate minerals crystallize together.", hardness = "2\u20134", luster = "Vitreous to earthy", streak = "Green to blue", crystalSystem = "Mixed (cryptocrystalline)", chemicalFormula = "Cu-silicate + Cu-carbonate", commonColors = listOf("Blue-green swirls", "Teal and emerald", "Turquoise"), whereFound = listOf("Arizona, USA", "Democratic Republic of Congo", "Chile", "Peru"), funFacts = listOf("Malacholla isn't a single mineral — it's an intimate mix of two.", "The blue-green contrast makes it a favorite among lapidary artists.", "It's a reliable sign of a rich copper deposit."), uses = "Jewelry, cabochons, carvings.", rarity = "Uncommon"),
        Specimen(id = "mammoth-tooth", name = "Mammoth Tooth", rockClass = RockClass.FOSSIL, category = "Mammal — Proboscidea", tagline = "The ridged grinder of the ice age titan.", emoji = "\uD83E\uDDA3", colorHex = 0xFF6E5C4A, description = "Mammoth teeth are highly distinctive with their flat, ridged chewing surfaces — like a rasp designed to grind tough ice-age grasses. They are commonly found in Pleistocene river deposits across North America, Europe, and Siberia.", formation = "Teeth were shed or left after death and buried in river gravels, glacial sediments, and permafrost. Cold, anoxic conditions often preserve them beautifully.", hardness = "—", luster = "Enamel to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate / Dentin", commonColors = listOf("Brown", "Dark gray", "Cream enamel"), whereFound = listOf("Siberia, Russia", "Alaska, USA", "Florida, USA", "England"), funFacts = listOf("Mammoths had up to 6 sets of teeth in their lifetime.", "Frozen mammoth carcasses have been found in Siberian permafrost with flesh intact.", "Mammoth ivory is still carved today and is legal to collect."), uses = "Collector specimens, educational displays, ivory carving.", rarity = "Uncommon", geologicalPeriod = "Pleistocene", age = "2.6 million – 10,000 years ago"),
        Specimen(id = "megalodon-tooth", name = "Megalodon Tooth - Fossilized", rockClass = RockClass.FOSSIL, category = "Fish — Lamniformes (Shark)", tagline = "The hand-sized tooth of the largest shark to ever live.", emoji = "\uD83E\uDD88", colorHex = 0xFF4A505A, description = "Megalodon teeth are the fossilized remains of Carcharocles megalodon, a shark that grew to 50–60 feet long. These serrated triangular teeth can reach over 7 inches and are found in marine deposits worldwide.", formation = "Sharks constantly shed teeth throughout life — megalodon shed tens of thousands. Teeth that settled on the seafloor mineralized over millions of years, often in phosphate-rich sediments.", hardness = "—", luster = "Enameloid to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate replacement", commonColors = listOf("Gray", "Black", "Brown", "Bluish"), whereFound = listOf("South Carolina, USA", "North Carolina, USA", "Peru", "Chile"), funFacts = listOf("A megalodon could swallow a great white shark whole.", "Their bite force was over 10 tons — the strongest of any known animal.", "Divers still find them off the coast of North Carolina and South Carolina."), uses = "Collector specimens, jewelry, educational displays.", rarity = "Common", geologicalPeriod = "Miocene – Pliocene", age = "23 – 3.6 mya"),
        Specimen(id = "mesolite", name = "Mesolite", rockClass = RockClass.MINERAL, category = "Silicate — Zeolite group", tagline = "Hair-like white needles — the most delicate zeolite.", emoji = "\uD83E\uDEA2", colorHex = 0xFFF8F8F8, description = "Mesolite is a sodium calcium zeolite forming incredibly fine, hair-like white needles that radiate in cotton-ball-like clusters. It's one of the most delicate and beautiful zeolites, often growing alongside green apophyllite.", formation = "Crystallizes in cavities of basaltic lava where calcium and sodium-rich groundwater circulates.", hardness = "5", luster = "Silky to vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Na₂Ca₂Al₆Si₉O₃₀·8H₂O", commonColors = listOf("White", "Colorless", "Pale yellow"), whereFound = listOf("India", "Oregon, USA", "New Jersey, USA", "Iceland"), funFacts = listOf("Mesolite needles are so fine they look like cotton candy.", "Named from Greek 'mesos' meaning middle — intermediate between natrolite and scolecite.", "Combination specimens with green apophyllite are stunning and highly prized."), uses = "Collector specimens, mineral displays.", rarity = "Uncommon"),
        Specimen(id = "migmatite", name = "Migmatite", rockClass = RockClass.METAMORPHIC, category = "Mixed metamorphic-igneous rock", tagline = "Half metamorphic, half igneous — rock frozen mid-melting.", emoji = "\uD83C\uDF0A", colorHex = 0xFFAAAACC, description = "Migmatite is a rock caught between metamorphic and igneous — heated so intensely that parts began to melt while other parts stayed solid. It's literally frozen mid-transition.", formation = "High-grade metamorphic rock heated to partial melting, with the melted fraction forming light-colored veins.", hardness = "\u2014", luster = "Mixed", streak = "\u2014", crystalSystem = "Mixed (metamorphic + igneous)", chemicalFormula = "Mixed silicates (partially melted)", commonColors = listOf("Light and dark banded", "Pink-gray swirls", "White-black"), whereFound = listOf("Canadian Shield", "Finland", "Brazil", "India"), funFacts = listOf("Migmatite represents the exact boundary between metamorphic and igneous rocks.", "The light bands are former melt — the dark bands never melted.", "It's some of the oldest continental crust on Earth."), uses = "Building stone, countertops, geological research.", rarity = "Common"),
        Specimen(id = "mimetite", name = "Mimetite", rockClass = RockClass.MINERAL, category = "Arsenate mineral", tagline = "Golden-orange hexagonal crystals — the arsenic twin of pyromorphite.", emoji = "\uD83C\uDF4A", colorHex = 0xFFF39C12, description = "Mimetite is lead arsenate chloride, the arsenic analog of pyromorphite. It forms brilliant yellow-to-orange hexagonal prisms and botryoidal crusts in the oxidized zone of lead deposits.", formation = "Alteration of lead arsenide minerals in the oxidized zone of ore deposits.", hardness = "3.5\u20134", luster = "Resinous to adamantine", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "Pb\u2085(AsO\u2084)\u2083Cl", commonColors = listOf("Golden yellow", "Orange", "Brown", "Green", "Colorless"), whereFound = listOf("Mexico", "Namibia (Tsumeb)", "Czech Republic", "Arizona, USA"), funFacts = listOf("Mimetite means 'imitator' — it mimics pyromorphite in crystal form.", "Tsumeb, Namibia produces the world's finest specimens.", "Forms a solid solution series with pyromorphite."), uses = "Lead ore, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "mosasaur-tooth", name = "Mosasaur Tooth", rockClass = RockClass.FOSSIL, category = "Reptile — Mosasauridae", tagline = "The fang of the ocean's Cretaceous apex predator.", emoji = "\uD83E\uDD95", colorHex = 0xFF6B4E31, description = "Mosasaurs were giant marine reptiles that dominated the world's oceans during the Late Cretaceous. Their conical teeth were designed for gripping slippery prey like fish, squid, and smaller marine reptiles.", formation = "Teeth fell to the seafloor and were preserved in chalk and marine sediments, especially abundant in the phosphate beds of Morocco.", hardness = "—", luster = "Enamel-like", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate preservation", commonColors = listOf("Brown", "Tan", "Black"), whereFound = listOf("Morocco", "Kansas, USA", "Netherlands", "Angola"), funFacts = listOf("Mosasaurs could reach 50 feet — longer than a school bus.", "They are more closely related to monitor lizards and snakes than dinosaurs.", "The first mosasaur fossil was found in a Dutch mine in 1764."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Late Cretaceous", age = "101 – 66 mya"),
        Specimen(id = "mottramite", name = "Mottramite", rockClass = RockClass.MINERAL, category = "Vanadate mineral", tagline = "Dark green-black crusts — lead copper vanadate.", emoji = "\u2B1B", colorHex = 0xFF223322, description = "Mottramite is a lead copper vanadate forming dark green to black botryoidal crusts. It's the copper analog of descloizite and often found in the oxidized zone of lead-copper deposits.", formation = "A secondary mineral formed in the oxidized zone of lead-copper-vanadium deposits.", hardness = "3\u20133.5", luster = "Resinous to subadamantine", streak = "Greenish", crystalSystem = "Orthorhombic", chemicalFormula = "PbCu(VO\u2084)(OH)", commonColors = listOf("Dark green", "Black", "Greenish-black"), whereFound = listOf("Arizona, USA", "Namibia", "England", "Mexico"), funFacts = listOf("Named after the locality of Mottram St. Andrew in England.", "The copper end member of the descloizite-mottramite series.", "Vanadium gives it the dark coloration."), uses = "Collector specimens, vanadium indicator.", rarity = "Uncommon"),
        Specimen(id = "musgravite", name = "Musgravite", rockClass = RockClass.CRYSTAL, category = "Oxide mineral", tagline = "The taaffeite twin — even rarer and harder to pronounce.", emoji = "\uD83D\uDC8E", colorHex = 0xFF9966AA, description = "Musgravite is magnesium beryllium aluminum oxide and a close relative of taaffeite. For years it was confused with taaffeite — it's actually distinct and even rarer, with only a few faceted gems known worldwide.", formation = "Crystallizes in high-grade metamorphic rocks under granulite facies conditions.", hardness = "8\u20138.5", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "MgBeAl\u2084O\u2088", commonColors = listOf("Grayish-purple", "Mauve", "Greenish-gray"), whereFound = listOf("Musgrave Ranges, South Australia", "Greenland", "Sri Lanka", "Tanzania"), funFacts = listOf("Named after the Musgrave Ranges in Australia.", "For decades, musgravite and taaffeite were considered the same mineral.", "A faceted musgravite is one of the rarest gems in existence."), uses = "Ultra-rare collector gemstone.", rarity = "Extremely Rare"),
        Specimen(id = "mylonite", name = "Mylonite", rockClass = RockClass.METAMORPHIC, category = "Fault-rock (dynamic metamorphism)", tagline = "Rock ground to dust in an earthquake zone.", emoji = "\uD83C\uDF0A", colorHex = 0xFFCCBBAA, description = "Mylonite is a fine-grained, banded rock formed by extreme shearing along fault zones during earthquakes. The intense grinding creates beautiful swirling patterns and reduces mineral grains to microscopic size.", formation = "Rocks are pulverized and recrystallized under intense shear stress in fault zones.", hardness = "Varies", luster = "Vitreous to dull", streak = "\u2014", crystalSystem = "Porphyroclastic", chemicalFormula = "Mixed silicates (sheared)", commonColors = listOf("Gray", "Brown", "Banded", "Green"), whereFound = listOf("Scotland (Moine Thrust)", "California, USA (San Andreas)", "Norway", "Brazil"), funFacts = listOf("Mylonite is literally earthquake rock \u2014 formed in active fault zones.", "The swirling bands are from the grinding action of tectonic forces.", "Named from Greek 'mylon' meaning mill \u2014 it's been milled to dust."), uses = "Geological research, earthquake zone studies.", rarity = "Common"),
        Specimen(id = "natrolite", name = "Natrolite", rockClass = RockClass.MINERAL, category = "Silicate — Zeolite group", tagline = "Delicate white needles — the most common zeolite, lining basalt cavities worldwide.", emoji = "\uD83E\uDEA2", colorHex = 0xFFF8F8F8, description = "Natrolite is a sodium zeolite forming delicate, radiating sprays of needle-like white crystals. It's the most common zeolite and often lines cavities in basalt alongside other zeolites.", formation = "Crystallizes in cavities of basaltic lava flows where sodium-rich water circulates.", hardness = "5–5.5", luster = "Vitreous to silky", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Na₂Al₂Si₃O₁₀·2H₂O", commonColors = listOf("White", "Colorless", "Pale yellow", "Pinkish"), whereFound = listOf("New Jersey, USA", "Oregon, USA", "India", "Iceland"), funFacts = listOf("Natrolite needles can be several inches long and are incredibly delicate.", "It's named from Greek 'natron' meaning soda — from its sodium content.", "Zeolites like natrolite are used in water softeners and cat litter."), uses = "Collector specimens, ion exchange, water purification.", rarity = "Common"),
        Specimen(id = "nautiloid", name = "Nautiloid", rockClass = RockClass.FOSSIL, category = "Cephalopod — Nautiloidea", tagline = "The ancient spiral-shelled predator that saw the dinosaurs.", emoji = "\uD83D\uDC0C", colorHex = 0xFFBF9B6A, description = "Nautiloids are shelled cephalopods with smooth, coiled or straight shells. They are the ancestors of ammonites and the distant cousins of the living chambered nautilus — often called 'living fossils' themselves.", formation = "Shells buried in marine limestone and shale, often with beautiful internal crystal growth in the chambers.", hardness = "—", luster = "Pearly to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "White", "Brown"), whereFound = listOf("Ohio, USA", "Indiana, USA", "Madagascar", "Morocco"), funFacts = listOf("The living chambered nautilus is virtually unchanged from its 500-million-year-old ancestors.", "Nautiloids survived all five mass extinctions.", "Their shells follow the golden ratio — a near-perfect logarithmic spiral."), uses = "Collector specimens, jewelry.", rarity = "Common", geologicalPeriod = "Cambrian – Present", age = "500 mya – today"),
        Specimen(id = "neptunite", name = "Neptunite", rockClass = RockClass.MINERAL, category = "Silicate — Inosilicate", tagline = "Deep red-black prisms with benitoite in California.", emoji = "\u2694\uFE0F", colorHex = 0xFF331111, description = "Neptunite is a potassium sodium lithium titanium silicate forming striking deep red to black prismatic crystals. It's famous for occurring with benitoite at the California state gem locality.", formation = "Crystallizes in natrolite veins within glaucophane schist, alongside benitoite.", hardness = "5\u20136", luster = "Vitreous", streak = "Reddish-brown", crystalSystem = "Monoclinic", chemicalFormula = "KNa\u2082Li(Fe,Mn)\u2082Ti\u2082Si\u2088O\u2082\u2084", commonColors = listOf("Deep red-black", "Dark brown", "Black"), whereFound = listOf("San Benito County, California, USA", "Greenland", "Russia"), funFacts = listOf("The finest neptunite occurs with benitoite in California.", "Named after Neptune, Roman god of the sea.", "It's one of very few titanium silicate minerals."), uses = "Collector specimens.", rarity = "Rare"),
        Specimen(id = "norite", name = "Norite", rockClass = RockClass.IGNEOUS, category = "Intrusive plutonic rock", tagline = "Gabbro's orthopyroxene-rich cousin.", emoji = "\u2B1B", colorHex = 0xFF3A3A3A, description = "Norite is a mafic intrusive igneous rock similar to gabbro but containing orthopyroxene instead of clinopyroxene. It's common in large layered intrusions that host platinum and chromium deposits.", formation = "Crystallizes from mafic magma in large, slowly cooling intrusions.", hardness = "6\u20137", luster = "Dull to vitreous", streak = "\u2014", crystalSystem = "Phaneritic aggregate", chemicalFormula = "Mafic silicates with orthopyroxene", commonColors = listOf("Dark gray", "Black", "Brownish-black"), whereFound = listOf("South Africa (Bushveld)", "Montana, USA (Stillwater)", "Norway", "Canada"), funFacts = listOf("Named after Norge (Norway) where it was first described.", "The Bushveld norite hosts the world's largest platinum deposits.", "It's the host rock for the Stillwater chromite deposits in Montana."), uses = "Platinum and chromium ore host, building stone.", rarity = "Common"),
        Specimen(id = "novaculite", name = "Chert, Novaculite", rockClass = RockClass.SEDIMENTARY, category = "Chemical sedimentary rock", tagline = "Arkansas's whetstone \u2014 the sharpest rock on Earth.", emoji = "\uD83D\uDD2A", colorHex = 0xFFEEEEE8, description = "Novaculite is a very hard, fine-grained sedimentary rock composed of microcrystalline quartz. Arkansas novaculite is famous worldwide as the best natural whetstone material for sharpening blades.", formation = "Deep-sea siliceous ooze is compacted and cemented into dense, hard chert-like rock.", hardness = "7", luster = "Waxy to dull", streak = "White", crystalSystem = "Microcrystalline", chemicalFormula = "SiO\u2082", commonColors = listOf("White", "Cream", "Gray", "Pink"), whereFound = listOf("Arkansas, USA (Ouachita Mountains)", "Texas, USA", "Oklahoma, USA"), funFacts = listOf("Arkansas novaculite is considered the finest whetstone in the world.", "Native Americans quarried it for arrowheads and tools for thousands of years.", "It's the official state rock of Arkansas."), uses = "Whetstones, sharpening stones, tools, abrasive.", rarity = "Common"),
        Specimen(id = "nummulites", name = "Nummulites", rockClass = RockClass.FOSSIL, category = "Microfossil — Foraminifera", tagline = "Coin-shaped shells that built the pyramids' stone.", emoji = "\uD83E\uDE99", colorHex = 0xFFD4C8A8, description = "Nummulites were giant foraminifera with flat, coin-shaped calcite shells. The Eocene nummulitic limestone of Egypt was used to build the Great Pyramids of Giza.", formation = "Shells accumulated in vast numbers on the floor of the ancient Tethys Ocean, forming thick limestone beds.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("White", "Gray", "Cream"), whereFound = listOf("Egypt", "Libya", "Turkey", "India"), funFacts = listOf("The Great Pyramids are built from nummulitic limestone.", "Nummulites means 'little coin' in Latin \u2014 from their flat, round shape.", "Some nummulites reached over 6 inches across \u2014 giant for a single-celled organism."), uses = "Building stone, index fossils, educational displays.", rarity = "Common", geologicalPeriod = "Eocene", age = "56 – 34 mya"),
        Specimen(id = "okenite", name = "Okenite", rockClass = RockClass.MINERAL, category = "Silicate — Phyllosilicate", tagline = "Fluffy white cotton balls — the mineral that looks like snow.", emoji = "\u2601\uFE0F", colorHex = 0xFFF8F8F0, description = "Okenite is a hydrated calcium silicate forming incredibly fine, fluffy white fibers that look like tiny snowballs or cotton puffs. It's so soft and delicate that touching it can collapse the crystal sprays.", formation = "Crystallizes in basalt cavities at low temperatures, often with gyrolite and apophyllite.", hardness = "4.5–5", luster = "Silky to pearly", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "CaSi₂O₅·2H₂O", commonColors = listOf("White", "Colorless", "Cream"), whereFound = listOf("India (Pune)", "Greenland", "Ireland", "Chile"), funFacts = listOf("Okenite looks like tiny balls of snow or cotton — one of the softest-looking minerals.", "Named after German naturalist Lorenz Oken.", "The fibers are so delicate that a gentle touch can ruin the specimen."), uses = "Collector specimens (handle with extreme care).", rarity = "Uncommon"),
        Specimen(id = "olivenite", name = "Olivenite", rockClass = RockClass.MINERAL, category = "Arsenate mineral", tagline = "Olive-green needles — copper's other green mineral.", emoji = "\uD83E\uDEAD", colorHex = 0xFF556633, description = "Olivenite is a copper arsenate hydroxide forming olive-green to dark green acicular crystals and fibrous masses. It's one of the most common copper arsenates in oxidized copper deposits.", formation = "A secondary copper mineral formed by the weathering of copper arsenides.", hardness = "3", luster = "Vitreous to silky", streak = "Olive green", crystalSystem = "Monoclinic", chemicalFormula = "Cu\u2082(AsO\u2084)(OH)", commonColors = listOf("Olive green", "Dark green", "Yellowish-green"), whereFound = listOf("Cornwall, England", "Arizona, USA", "Namibia", "Chile"), funFacts = listOf("Olivenite means 'olive' \u2014 named for its olive-green color.", "Cornwall, England is the type locality.", "Often confused with malachite but much softer."), uses = "Collector specimens, copper indicator mineral.", rarity = "Uncommon"),
        Specimen(id = "black-opal", name = "Opal, Black", rockClass = RockClass.MINERAL, category = "Hydrated silica (mineraloid)", tagline = "The most valuable opal type — dark body with electric fire.", emoji = "\uD83C\uDF19", colorHex = 0xFF111133, description = "Black opal is the rarest and most valuable opal, with a dark body tone that makes its play-of-color dramatically vivid. Lightning Ridge, Australia produces the world's finest specimens.", formation = "Forms in Cretaceous claystone and sandstone when silica-rich water fills cavities and slowly hardens over millions of years.", hardness = "5.5-6.5", luster = "Vitreous to resinous", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "SiO2.nH2O", commonColors = listOf("Black with red flash", "Dark with blue-green", "Black with full spectrum"), whereFound = listOf("Lightning Ridge, Australia", "Mintabie, Australia", "Andamooka, Australia"), funFacts = listOf("A top black opal can fetch over $15,000 per carat.", "Lightning Ridge is the undisputed capital of black opal.", "The dark body tone makes color play dramatically visible."), uses = "Fine jewelry, investment-grade gemstones.", rarity = "Rare"),
        Specimen(id = "blue-opal", name = "Opal, Blue", rockClass = RockClass.MINERAL, category = "Hydrated silica (mineraloid)", tagline = "Soft sky-blue opal from Oregon's high desert.", emoji = "\uD83E\uDE9E", colorHex = 0xFF99BBCC, description = "Common blue opal from Oregon is a translucent to opaque pastel blue variety with a waxy luster. Its beauty is in the soft, dreamy periwinkle to sky-blue body color without play-of-color.", formation = "Deposited from silica-rich water in volcanic rock cavities in Oregon's high desert.", hardness = "5.5-6.5", luster = "Waxy to resinous", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "SiO2.nH2O", commonColors = listOf("Sky blue", "Periwinkle", "Pale blue-gray"), whereFound = listOf("Oregon, USA (Richardson Ranch)", "Oregon, USA (Opal Butte)", "Peru"), funFacts = listOf("Discovered in Oregon in the mid-20th century.", "Richardson Ranch is the most famous Oregon opal locality.", "Fine blue opal is highly sought by lapidary artists."), uses = "Cabochons, jewelry, carved objects.", rarity = "Common"),
        Specimen(id = "boulder-opal", name = "Opal, Boulder", rockClass = RockClass.MINERAL, category = "Hydrated silica (mineraloid)", tagline = "Opal veins slicing through ironstone like lightning.", emoji = "\u26A1", colorHex = 0xFF553322, description = "Boulder opal forms as thin veins and patches of precious opal running through dark brown ironstone. Queensland produces the world's best with brilliant color flashes.", formation = "Silica-rich water seeps into cracks in ironstone, depositing opal as thin seams.", hardness = "5.5-6.5", luster = "Vitreous to resinous", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "SiO2.nH2O", commonColors = listOf("Blue-green veins", "Full spectrum seams", "Purple-blue patches"), whereFound = listOf("Quilpie, Queensland, Australia", "Winton, Queensland, Australia", "Yowah, Queensland, Australia"), funFacts = listOf("Cut with its ironstone backing — nature's doublet.", "Yowah nuts are ironstone concretions with opal centers.", "Quilpie boulder opal is famous for vivid blue and green."), uses = "Jewelry, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "crystal-opal", name = "Opal, Crystal", rockClass = RockClass.MINERAL, category = "Hydrated silica (mineraloid)", tagline = "Transparent opal with spectral fire floating inside.", emoji = "\uD83D\uDC8E", colorHex = 0xFFCCDDFF, description = "Crystal opal is transparent precious opal where play-of-color appears to float inside like captured aurora. The clarity shows a three-dimensional color display.", formation = "Silica spheres arrange in orderly grids within clear, water-filled cavities, diffracting light as it passes through.", hardness = "5.5-6.5", luster = "Vitreous", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "SiO2.nH2O", commonColors = listOf("Clear with rainbow", "Transparent with blue-green", "Water-clear with red flash"), whereFound = listOf("Coober Pedy, Australia", "Andamooka, Australia", "Lightning Ridge, Australia", "Ethiopia"), funFacts = listOf("Shows color from both front and back — 3D color.", "Second most valuable opal type after black opal.", "Ethiopian crystal opal can absorb water temporarily."), uses = "Fine jewelry, collector gemstones.", rarity = "Uncommon"),
        Specimen(id = "ethiopian-opal", name = "Opal, Ethiopian", rockClass = RockClass.MINERAL, category = "Hydrated silica (mineraloid)", tagline = "Hydrophane opal from Africa's Rift Valley — vivid fire.", emoji = "\uD83C\u1F30D", colorHex = 0xFFDD7744, description = "Ethiopian opal is a recent discovery found in volcanic rhyolite. It's hydrophane — absorbing water — and shows spectacular play-of-color in reds, oranges, and greens against honey to chocolate body tones.", formation = "Deposited in volcanic rhyolite cavities by silica-rich hot spring water from East African Rift volcanism.", hardness = "5.5-6.5", luster = "Vitreous to waxy", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "SiO2.nH2O", commonColors = listOf("Honey with red flash", "Chocolate with green", "Golden with full spectrum"), whereFound = listOf("Wollo Province, Ethiopia", "Gondar, Ethiopia", "Shewa Province, Ethiopia"), funFacts = listOf("Discovered in 1994 — the newest major opal source.", "Can absorb water, turn transparent, then dry back.", "Some specimens show patterns like starry skies."), uses = "Jewelry, cabochons.", rarity = "Uncommon"),
        Specimen(id = "fire-opal", name = "Opal, Fire", rockClass = RockClass.MINERAL, category = "Hydrated silica (mineraloid)", tagline = "Sunset trapped in stone — Mexican fire opals.", emoji = "\uD83D\uDD25", colorHex = 0xFFFF5500, description = "Fire opal is a transparent to translucent opal with a warm yellow, orange, or red body color. Unlike precious opal, it may or may not show play-of-color — its value comes from its intense, fiery hues.", formation = "Deposited from silica-rich volcanic waters in gas cavities of rhyolite lava.", hardness = "5.5\u20136.5", luster = "Vitreous to resinous", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "SiO\u2082\u00B7nH\u2082O", commonColors = listOf("Fiery orange", "Cherry red", "Golden yellow", "Sunset"), whereFound = listOf("Mexico (Quer\u00E9taro)", "Oregon, USA", "Brazil", "Australia"), funFacts = listOf("Mexico produces the world's finest fire opals.", "Unlike other opals, fire opal is often faceted, not cabochon-cut.", "The Aztecs called it 'vitzitziltecpal' — hummingbird stone."), uses = "Gemstone, jewelry.", rarity = "Uncommon"),
        Specimen(id = "matrix-opal", name = "Opal, Matrix", rockClass = RockClass.MINERAL, category = "Hydrated silica (mineraloid)", tagline = "Opal speckled through dark host rock like a starry night.", emoji = "\uD83C\u1F31F", colorHex = 0xFF1A1A22, description = "Matrix opal is precious opal intimately mixed with dark host rock — usually basalt or ironstone. Honduran matrix opal in black basalt creates dramatic contrast with glittering pinfire flashes.", formation = "Silica-bearing solutions permeate porous volcanic rock, depositing opal in countless tiny cavities.", hardness = "5.5-6.5", luster = "Waxy to vitreous", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "SiO2.nH2O", commonColors = listOf("Blue-green pinfire", "Red-orange speckles", "Rainbow pinpoints"), whereFound = listOf("Honduras (Gracias)", "Andamooka, Australia", "Mexico"), funFacts = listOf("Honduran matrix opal occurs in black basalt — finest contrast.", "Andamooka matrix opal can be sugar-acid treated to darken.", "Often called pinfire opal for the tiny pinpricks of light."), uses = "Jewelry, cabochons.", rarity = "Uncommon"),
        Specimen(id = "white-opal", name = "Opal, Coober Pedy", rockClass = RockClass.MINERAL, category = "Hydrated silica (mineraloid)", tagline = "Milky white with pastel fire — Coober Pedy's gift.", emoji = "\uD83E\uDDC1", colorHex = 0xFFFFF8EE, description = "White opal has a pale milky body tone with delicate pastel play-of-color. Coober Pedy, South Australia produces the finest white opals — miners live underground to escape the desert heat.", formation = "Deposited in Cretaceous sandstone when silica-rich groundwater filled ancient seabed cracks.", hardness = "5.5-6.5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Amorphous", chemicalFormula = "SiO2.nH2O", commonColors = listOf("Milky with pink flash", "Cream with green", "White with blue"), whereFound = listOf("Coober Pedy, Australia", "Mintabie, Australia", "White Cliffs, Australia"), funFacts = listOf("Coober Pedy residents live underground in dugout homes.", "Coober Pedy means 'white man in a hole' in Aboriginal.", "White opal is Australia's national gemstone."), uses = "Jewelry, gemstones.", rarity = "Common"),
        Specimen(id = "orthoceras", name = "Orthoceras", rockClass = RockClass.FOSSIL, category = "Cephalopod — Orthocerida", tagline = "Straight-shelled ancestor of squid and octopus.", emoji = "\uD83E\uDEB3", colorHex = 0xFFA0896C, description = "Orthoceras is an extinct nautiloid cephalopod with a long, straight conical shell divided into chambers. These sleek predators swam the Ordovician and Silurian seas, and their fossils are found in massive beds in Morocco.", formation = "Shells accumulated on the seafloor after death and were buried in fine-grained limestones. The chambered interior often displays stunning calcite crystal growth.", hardness = "—", luster = "Dull to vitreous", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite replacement", commonColors = listOf("Black", "Gray", "White"), whereFound = listOf("Morocco", "Sweden", "Estonia"), funFacts = listOf("Orthoceras means 'straight horn' in Greek.", "The fossil beds in Morocco contain thousands per square meter.", "They are distant relatives of modern squid, octopus, and nautilus."), uses = "Collector specimens, carvings, decorative objects.", rarity = "Common", geologicalPeriod = "Ordovician – Silurian", age = "485 – 419 mya"),
        Specimen(id = "painite", name = "Painite", rockClass = RockClass.CRYSTAL, category = "Borate mineral", tagline = "Once the rarest mineral on Earth — Guinness World Record holder.", emoji = "\uD83D\uDC8E", colorHex = 0xFF882222, description = "Painite held the Guinness World Record for rarest mineral for decades. This calcium zirconium borate forms dark red-brown hexagonal crystals of extraordinary rarity from Myanmar's Mogok region.", formation = "Crystallizes in metamorphosed limestones in the Mogok region under very specific conditions.", hardness = "8", luster = "Vitreous", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "CaZrAl\u2089O\u2081\u2085(BO\u2083)", commonColors = listOf("Dark red", "Ruby-brown", "Orange-brown"), whereFound = listOf("Mogok, Myanmar", "Mong Hsu, Myanmar"), funFacts = listOf("For decades, only three painite crystals were known to exist.", "Held the Guinness World Record for rarest mineral.", "Named after British gemologist Arthur Pain."), uses = "Ultra-rare collector gemstone.", rarity = "Extremely Rare"),
        Specimen(id = "pargasite", name = "Pargasite", rockClass = RockClass.MINERAL, category = "Silicate — Amphibole group", tagline = "Deep green-black amphibole — the skarn-forming mineral.", emoji = "\uD83D\uDFE2", colorHex = 0xFF223322, description = "Pargasite is a sodium calcium magnesium aluminum amphibole forming deep green to black prismatic crystals in metamorphic marbles. It's a key component of skarn deposits and its gem-quality green crystals are highly prized.", formation = "Crystallizes during high-temperature metamorphism of impure limestones and dolomites.", hardness = "5–6", luster = "Vitreous", streak = "White to pale green", crystalSystem = "Monoclinic", chemicalFormula = "NaCa₂(Mg₄Al)(Si₆Al₂)O₂₂(OH)₂", commonColors = listOf("Deep green", "Black-green", "Brownish-green"), whereFound = listOf("Finland (Pargas)", "New York, USA", "Pakistan", "Myanmar"), funFacts = listOf("Named after Pargas, Finland where it was first discovered.", "Gem-quality green pargasite from Pakistan is a rare collector stone.", "It's the magnesium-rich end member of the amphibole family."), uses = "Gemstone (rare), collector specimens, metamorphic indicator.", rarity = "Uncommon"),
        Specimen(id = "petrified-wood", name = "Petrified Wood - Fossilized", rockClass = RockClass.FOSSIL, category = "Plant — Various tree species", tagline = "Ancient trees turned to stone — a general entry covering petrified wood worldwide.", emoji = "\uD83E\uDEB5", colorHex = 0xFFC67E4A, description = "Petrified wood forms when trees are buried by volcanic ash or sediment and silica-rich groundwater slowly replaces every cell of the wood with quartz, agate, or opal. The result keeps every ring and cell perfectly preserved in stone. This general entry covers petrified wood from any locality — from the rainbow logs of Arizona to the blue forests of Wyoming.", formation = "Volcanic ash buried entire forests. Silica from the ash dissolved in groundwater and slowly replaced the wood's organic material.", hardness = "7", luster = "Vitreous", streak = "—", crystalSystem = "N/A", chemicalFormula = "SiO₂ replacement", commonColors = listOf("Red", "Orange", "Brown", "Green", "Rainbow"), whereFound = listOf("Arizona, USA", "Oregon, USA", "Argentina", "Madagascar"), funFacts = listOf("Arizona's Petrified Forest National Park preserves 225-million-year-old trees.", "Trace elements create the colors: iron makes red, manganese makes pink, cobalt makes green.", "Some petrified logs are over 100 feet long."), uses = "Jewelry, bookends, tabletops, collector specimens.", rarity = "Common", geologicalPeriod = "Triassic – Miocene", age = "225 – 5 mya"),
        Specimen(id = "pezzottaite", name = "Beryl, Pezzottaite", rockClass = RockClass.CRYSTAL, category = "Silicate — Cyclosilicate", tagline = "Raspberry-pink gem — beryl's rarest variety.", emoji = "\uD83C\uDF47", colorHex = 0xFFDD3388, description = "Pezzottaite is a cesium-rich beryl variety with a vivid raspberry-pink color. Discovered in Madagascar in 2002, it was initially mistaken for morganite before being recognized as a distinct mineral species.", formation = "Crystallizes in lithium-cesium-rich granite pegmatites.", hardness = "8", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Cs(Be\u2082Li)Al\u2082Si\u2086O\u2081\u2088", commonColors = listOf("Raspberry pink", "Magenta", "Hot pink"), whereFound = listOf("Madagascar", "Afghanistan", "Myanmar"), funFacts = listOf("Discovered in 2002 — one of the newest recognized gem minerals.", "Named after Italian mineralogist Federico Pezzotta.", "Initially sold as 'raspberry beryl' before being identified as a new species."), uses = "Ultra-rare collector gemstone.", rarity = "Extremely Rare"),
        Specimen(id = "phenakite", name = "Phenakite", rockClass = RockClass.CRYSTAL, category = "Silicate — Nesosilicate", tagline = "Brilliant colorless crystals — beryllium's lesser-known gem.", emoji = "\uD83D\uDC8E", colorHex = 0xFFF0F4FF, description = "Phenakite is beryllium silicate forming brilliant, colorless trigonal crystals that can be confused with quartz — but it's harder and has a higher refractive index. It's one of the few beryllium gem minerals.", formation = "Crystallizes in granite pegmatites and hydrothermal veins with beryl and topaz.", hardness = "7.5\u20138", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Be\u2082SiO\u2084", commonColors = listOf("Colorless", "White", "Pale yellow", "Pink"), whereFound = listOf("Russia (Ural Mountains)", "Brazil", "Colorado, USA", "Myanmar"), funFacts = listOf("Phenakite means 'deceiver' — it was often mistaken for quartz.", "Faceted phenakite has more fire than quartz.", "It's much rarer than the beryl group beryllium minerals."), uses = "Gemstone, beryllium ore, collector specimens.", rarity = "Rare"),
        Specimen(id = "phlogopite", name = "Phlogopite", rockClass = RockClass.MINERAL, category = "Silicate — Phyllosilicate (Mica)", tagline = "Golden-brown mica — the fireproof mineral.", emoji = "\uD83D\uDD36", colorHex = 0xFFCC9933, description = "Phlogopite is a magnesium-rich mica with a warm golden-brown to copper color. It has exceptional heat resistance — it can withstand temperatures over 1,000°C, making it valuable for industrial insulation.", formation = "Crystallizes in magnesium-rich metamorphic rocks, particularly marble and ultramafic rocks.", hardness = "2.5–3", luster = "Pearly to submetallic", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "KMg₃(AlSi₃O₁₀)(OH)₂", commonColors = listOf("Golden brown", "Copper", "Reddish-brown", "Dark brown"), whereFound = listOf("Finland", "Madagascar", "Canada", "New York, USA"), funFacts = listOf("Phlogopite withstands temperatures over 1,000°C — used in blast furnace windows.", "Named from Greek 'phlogopos' meaning fire-like — from its reddish glow.", "Large, transparent sheets were used as oven windows before heat-proof glass."), uses = "Electrical insulation, high-temperature windows, lubricant.", rarity = "Common"),
        Specimen(id = "phosphosiderite", name = "Phosphosiderite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Orchid-purple crusts — the rare phosphate beauty.", emoji = "\uD83D\uDC9C", colorHex = 0xFFBB66AA, description = "Phosphosiderite is a hydrated iron phosphate with a beautiful orchid-purple to pink color. It's the iron analog of variscite and forms botryoidal crusts popular with lapidary artists.", formation = "Forms in the oxidized zone of iron phosphate deposits.", hardness = "3.5\u20134", luster = "Vitreous to waxy", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "FePO\u2084\u00B72H\u2082O", commonColors = listOf("Orchid purple", "Pink", "Reddish-purple"), whereFound = listOf("Chile", "Germany", "Portugal", "California, USA"), funFacts = listOf("Phosphosiderite is the iron analog of variscite (aluminum).", "Often cut into cabochons showing beautiful purple swirls.", "Named from Greek for 'phosphate' and 'iron.'"), uses = "Cabochons, jewelry, ornamental carvings.", rarity = "Uncommon"),
        Specimen(id = "pietersite", name = "Pietersite", rockClass = RockClass.MINERAL, category = "Silicate — Quartz (brecciated)", tagline = "Swirling blue-gold storms frozen in quartz.", emoji = "\uD83C\uDF2A\uFE0F", colorHex = 0xFF335599, description = "Pietersite is a brecciated quartz containing blue crocidolite and golden tigereye fibers, creating dramatic swirling patterns that look like storms or ocean waves. It's found in only two places on Earth — Namibia and China.", formation = "Forms when crocidolite-rich rock is brecciated (shattered) and cemented by quartz, with the fibers creating the chatoyant swirls.", hardness = "7", luster = "Vitreous to silky", streak = "White", crystalSystem = "Microcrystalline (quartz)", chemicalFormula = "SiO₂ (with amphibole fibers)", commonColors = listOf("Blue-gold swirls", "Navy", "Stormy gray", "Red-brown"), whereFound = listOf("Namibia", "China", "Henan Province, China"), funFacts = listOf("Named after Sid Pieters, who discovered it in Namibia in 1962.", "Only two deposits exist worldwide — Namibia and China.", "The swirling patterns are created by chaotically oriented amphibole fibers."), uses = "Jewelry, cabochons, ornamental carvings.", rarity = "Rare"),
        Specimen(id = "pink-halite", name = "Halite, Pink", rockClass = RockClass.MINERAL, category = "Halide mineral", tagline = "Edible pink crystals — salt with a vivid color.", emoji = "\uD83E\uDDC2", colorHex = 0xFFFFAAAA, description = "Pink halite is rock salt colored vivid pink by bacterial carotene pigments trapped in the crystal during evaporation. The finest pink halite comes from Searles Lake in California.", formation = "Evaporating lake water traps halophilic bacteria that impart pink color to growing halite crystals.", hardness = "2.5", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "NaCl (with organic pigments)", commonColors = listOf("Pink", "Peach", "Salmon", "Bright pink"), whereFound = listOf("Searles Lake, California, USA", "Utah, USA", "Poland", "Australia"), funFacts = listOf("The pink color comes from halophilic bacteria \u2014 living organisms trapped in crystal.", "Searles Lake pink halite forms perfect cubic hopper crystals.", "Yes, you can lick it \u2014 it's salt."), uses = "Collector specimens, gourmet salt, decorative.", rarity = "Uncommon"),
        Specimen(id = "plesiosaur-tooth", name = "Plesiosaur Tooth - Fossilized", rockClass = RockClass.FOSSIL, category = "Reptile — Plesiosauria", tagline = "The needle-toothed hunter of Jurassic and Cretaceous seas.", emoji = "\uD83E\uDD95", colorHex = 0xFF7A6B4D, description = "Plesiosaurs were long-necked marine reptiles with four paddle-like flippers and mouths full of sharp, curved teeth. Their teeth are distinctive — slender, curved cones with fine striations along the enamel.", formation = "Teeth were shed or deposited after death on the seafloor and preserved in marine sediments, often in chalk and limestone formations.", hardness = "—", luster = "Enamel-like", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate preservation", commonColors = listOf("Brown", "Dark gray", "Black", "Cream (root)"), whereFound = listOf("England (Jurassic Coast)", "Morocco", "Kansas, USA", "Australia"), funFacts = listOf("The Loch Ness Monster legend may have been inspired by plesiosaur fossils.", "Plesiosaurs gave live birth \u2014 a rare trait for reptiles.", "Their necks could have up to 76 vertebrae \u2014 more than any other animal."), uses = "Collector specimens, educational displays.", rarity = "Uncommon", geologicalPeriod = "Jurassic – Cretaceous", age = "201 – 66 mya"),
        Specimen(id = "pliosaur-tooth", name = "Pliosaur Tooth - Fossilized", rockClass = RockClass.FOSSIL, category = "Reptile — Pliosauridae", tagline = "The banana-sized fang of the Jurassic sea monster.", emoji = "\uD83E\uDD95", colorHex = 0xFF7B5E3A, description = "Pliosaurs were short-necked, massive-headed marine reptiles with jaws full of enormous conical teeth. Their teeth are much thicker and more robust than plesiosaur teeth.", formation = "Teeth were preserved in Jurassic and Cretaceous marine sediments. Their robust structure makes them one of the more common marine reptile fossils.", hardness = "—", luster = "Enamel-like", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate", commonColors = listOf("Dark brown", "Black", "Tan"), whereFound = listOf("England (Jurassic Coast)", "Morocco", "Russia", "Australia"), funFacts = listOf("Pliosaurs had the strongest bite of any known marine reptile.", "The largest pliosaur skull ever found was over 8 feet long.", "They hunted ichthyosaurs and other marine reptiles."), uses = "Collector specimens, museum displays.", rarity = "Uncommon", geologicalPeriod = "Jurassic – Cretaceous", age = "170 – 90 mya"),
        Specimen(id = "poudretteite", name = "Poudretteite", rockClass = RockClass.CRYSTAL, category = "Silicate — Cyclosilicate", tagline = "Pink gem from a Canadian quarry — known from only a handful of stones.", emoji = "\uD83D\uDC95", colorHex = 0xFFFFAAAA, description = "Poudretteite is an extremely rare potassium sodium borosilicate first discovered at Mont Saint-Hilaire, Quebec. For decades less than 10 crystals were known, and faceted stones are among the rarest gems on Earth.", formation = "Crystallizes in marble xenoliths within alkaline intrusive complexes.", hardness = "5", luster = "Vitreous", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "KNa\u2082B\u2083Si\u2081\u2082O\u2083\u2080", commonColors = listOf("Pink", "Colorless", "Pale lavender"), whereFound = listOf("Mont Saint-Hilaire, Quebec, Canada", "Myanmar"), funFacts = listOf("Named after the Poudrette family who operated the quarry.", "First described in 1987 — one of the newest gem minerals.", "A faceted poudretteite can sell for more than a fine diamond per carat."), uses = "Ultra-rare collector gemstone.", rarity = "Extremely Rare"),
        Specimen(id = "prehnite", name = "Prehnite", rockClass = RockClass.MINERAL, category = "Silicate — Phyllosilicate", tagline = "Pale green botryoidal bubbles — the first mineral named after a person.", emoji = "\uD83C\uDFF5", colorHex = 0xFFA8C878, description = "Prehnite is a calcium aluminum silicate forming pale green botryoidal masses and crusts. It holds the distinction of being the first mineral ever named after a person — Dutch Colonel Hendrik von Prehn in 1788.", formation = "Crystallizes in cavities and veins of basaltic rocks, often with zeolites and calcite.", hardness = "6–6.5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Ca₂Al(AlSi₃O₁₀)(OH)₂", commonColors = listOf("Pale green", "Yellow-green", "White", "Colorless"), whereFound = listOf("New Jersey, USA", "South Africa", "Australia", "China"), funFacts = listOf("Prehnite was the first mineral ever named after a person (1788).", "Its bubbly botryoidal habit looks like frozen green bubbles.", "Often found with zeolites in basalt cavities."), uses = "Collector specimens, cabochons, ornamental stone.", rarity = "Common"),
        Specimen(id = "productus", name = "Productus - Fossilized", rockClass = RockClass.FOSSIL, category = "Brachiopoda — Productida", tagline = "The spiny-shelled brachiopod of Carboniferous seas.", emoji = "\uD83E\uDEB2", colorHex = 0xFFC8A878, description = "Productus brachiopods had a convex, ear-shaped shell covered in fine spines that anchored them in soft seafloor mud. They are among the most common fossils in Carboniferous and Permian limestone.", formation = "Spiny shells were buried in shallow sea carbonate mud. The spines often broke off but the shell body fossilizes well.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan"), whereFound = listOf("Kansas, USA", "Texas, USA", "England", "Russia"), funFacts = listOf("The spines helped productids stay anchored in soft, shifting seafloor sediment.", "Productus is one of the most abundant brachiopod fossils in the Carboniferous.", "Some had a tail-like extension that helped stabilize them in the mud."), uses = "Collector specimens, index fossils.", rarity = "Common", geologicalPeriod = "Carboniferous – Permian", age = "359 – 252 mya"),
        Specimen(id = "psilomelane", name = "Psilomelane", rockClass = RockClass.MINERAL, category = "Oxide mineral — Manganese oxide", tagline = "Black grape-like clusters — the primary manganese ore.", emoji = "\uD83C\uDF47", colorHex = 0xFF1A1A1A, description = "Psilomelane is a complex barium manganese oxide forming black, botryoidal masses that look like clusters of dark grapes. It's one of the most important manganese ores and often shows beautiful concentric growth bands when cut.", formation = "Forms in the oxidized zone of manganese deposits, often as stalactitic and botryoidal masses.", hardness = "5–6", luster = "Submetallic to dull", streak = "Brownish-black", crystalSystem = "Monoclinic (usually amorphous)", chemicalFormula = "(Ba,H₂O)₂Mn₅O₁₀", commonColors = listOf("Iron-black", "Dark gray", "Bluish-black"), whereFound = listOf("Germany", "Brazil", "India", "Arizona, USA"), funFacts = listOf("Psilomelane means 'smooth black' in Greek.", "Cut sections reveal beautiful concentric growth bands.", "It was used as a black pigment by prehistoric cave painters."), uses = "Manganese ore, pigment, collector specimens.", rarity = "Common"),
        Specimen(id = "ptychodus", name = "Ptychodus - Fossilized", rockClass = RockClass.FOSSIL, category = "Fish — Hybodontiformes", tagline = "The shark with pavement teeth for crushing shells.", emoji = "\uD83E\uDD88", colorHex = 0xFF8B7D6E, description = "Ptychodus was a Cretaceous shark with distinctive flat, ridged teeth arranged like cobblestones in its mouth \u2014 designed for crushing shells and armored prey rather than cutting flesh.", formation = "Teeth were buried in marine chalk and limestone of the Western Interior Seaway. Their unusual shape makes them easy to identify.", hardness = "—", luster = "Enameloid", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate", commonColors = listOf("Dark brown", "Black", "Gray"), whereFound = listOf("Kansas, USA", "Texas, USA", "England", "France"), funFacts = listOf("Ptychodus teeth look more like molars than shark teeth \u2014 designed to crush, not slice.", "They could grow to over 30 feet long.", "The ridged teeth form distinctive patterns that make them popular with collectors."), uses = "Collector specimens, educational displays.", rarity = "Uncommon", geologicalPeriod = "Late Cretaceous", age = "100 – 66 mya"),
        Specimen(id = "pumpellyite", name = "Pumpellyite", rockClass = RockClass.MINERAL, category = "Silicate — Sorosilicate", tagline = "Olive-green fibrous crystals — the copper country's hidden gem.", emoji = "\uD83E\uDEA2", colorHex = 0xFF556633, description = "Pumpellyite is a calcium magnesium aluminum silicate forming olive-green to bluish-green fibrous masses and radiating sprays. It's a common mineral in the Lake Superior copper district and an important metamorphic indicator.", formation = "Forms during low-grade metamorphism of basaltic rocks, particularly in the presence of copper deposits.", hardness = "5.5–6", luster = "Vitreous to silky", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "Ca₂MgAl₂(SiO₄)(Si₂O₇)(OH)₂·H₂O", commonColors = listOf("Olive green", "Bluish-green", "Brown"), whereFound = listOf("Michigan, USA (Keweenaw)", "California, USA", "New Zealand", "Japan"), funFacts = listOf("Named after American geologist Raphael Pumpelly.", "It's a key indicator of the pumpellyite-prehnite metamorphic facies.", "Keweenaw Peninsula specimens often have a distinctive bluish cast."), uses = "Metamorphic indicator mineral, collector specimens.", rarity = "Common"),
        Specimen(id = "purpurite", name = "Purpurite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Rich purple crusts — manganese's answer to amethyst.", emoji = "\uD83D\uDC9C", colorHex = 0xFF883388, description = "Purpurite is a manganese iron phosphate with a distinctive deep purple to reddish-purple color. It forms as an alteration product of lithiophilite in granite pegmatites and is valued for its unusual, vivid color.", formation = "Secondary mineral formed by the oxidation of manganese-rich primary phosphates in pegmatites.", hardness = "4–4.5", luster = "Dull to earthy", streak = "Purple to red", crystalSystem = "Orthorhombic", chemicalFormula = "MnPO₄", commonColors = listOf("Deep purple", "Reddish-purple", "Brownish-purple"), whereFound = listOf("South Dakota, USA", "Namibia", "Portugal", "Australia"), funFacts = listOf("Purpurite literally means 'purple' — from Latin 'purpura.'", "Its purple streak is unusual — few minerals leave a colored streak.", "Often grows on or replaces lithiophilite in pegmatites."), uses = "Collector specimens, lapidary material.", rarity = "Rare"),
        Specimen(id = "pyrolusite", name = "Pyrolusite", rockClass = RockClass.MINERAL, category = "Oxide mineral — Manganese dioxide", tagline = "Sooty black dendrites — the tree-like patterns in agate.", emoji = "\uD83C\uDF33", colorHex = 0xFF222222, description = "Pyrolusite is manganese dioxide, the most common manganese mineral. It forms sooty black masses and beautiful dendritic patterns that look like tiny ferns frozen in stone — often seen in moss agate and dendritic agate.", formation = "Deposited from manganese-rich solutions in fractures and along bedding planes in sedimentary and metamorphic rocks.", hardness = "2–6 (variable)", luster = "Metallic to earthy", streak = "Black to bluish-black", crystalSystem = "Tetragonal", chemicalFormula = "MnO₂", commonColors = listOf("Black", "Dark gray", "Iron-black"), whereFound = listOf("Germany", "Brazil", "India", "Virginia, USA"), funFacts = listOf("Pyrolusite was used as a black pigment by prehistoric cave painters.", "The dendritic patterns in moss agate are pyrolusite inclusions.", "Its name means 'fire wash' — it was used to remove color from glass."), uses = "Manganese ore, glass decolorizer, dry cell batteries.", rarity = "Common"),
        Specimen(id = "pyromorphite", name = "Pyromorphite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Grass-green hexagonal prisms from lead deposits.", emoji = "\uD83D\uDFE2", colorHex = 0xFF3B7A3B, description = "Pyromorphite is lead phosphate chloride forming brilliant green, barrel-shaped hexagonal crystals. The finest specimens are a vivid grass-green with a resinous luster that makes them highly photogenic and prized by collectors.", formation = "Weathering product of lead deposits in the presence of phosphate-rich water.", hardness = "3.5\u20134", luster = "Resinous to adamantine", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "Pb\u2085(PO\u2084)\u2083Cl", commonColors = listOf("Grass green", "Apple green", "Yellow", "Brown", "Orange"), whereFound = listOf("Germany", "Pennsylvania, USA", "Idaho, USA", "China"), funFacts = listOf("Named from Greek 'pyro' (fire) and 'morphe' (form) — it crystallizes from molten lead.", "Idaho's Bunker Hill Mine produces world-class specimens.", "The green color comes from trace chromium and vanadium."), uses = "Lead ore, collector specimens, phosphate indicator.", rarity = "Uncommon"),
        Specimen(id = "ametrine", name = "Ametrine", rockClass = RockClass.CRYSTAL, category = "Silicate — Quartz variety", tagline = "Purple and gold in one crystal — nature's bicolor miracle.", emoji = "\uD83D\uDC9C\uD83D\uDC9B", colorHex = 0xFFAA66CC, description = "Ametrine is a naturally occurring bicolor quartz displaying zones of both purple amethyst and golden citrine in a single crystal. The Anahi mine in Bolivia produces virtually all the world's commercial ametrine.", formation = "Different oxidation states of iron in different growth zones create the two colors during crystallization.", hardness = "7", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "SiO\u2082 (with Fe)", commonColors = listOf("Purple and gold", "Violet and yellow"), whereFound = listOf("Bolivia (Anahi Mine)", "Brazil", "India"), funFacts = listOf("Virtually all ametrine comes from a single mine in Bolivia.", "The color zones follow the crystal structure \u2014 not random.", "Legend says it was introduced to the world by a Spanish conquistador."), uses = "Gemstone, jewelry, collector specimens.", rarity = "Rare (natural)"),
        Specimen(id = "prasiolite", name = "Prasiolite (Green Amethyst)", rockClass = RockClass.CRYSTAL, category = "Silicate — Quartz variety", tagline = "Pale green quartz — amethyst heated by nature or man.", emoji = "\uD83D\uDFE2", colorHex = 0xFF88BB88, description = "Prasiolite is green quartz, also called green amethyst or vermarine. Most commercial prasiolite is heat-treated amethyst or yellowish quartz — true natural prasiolite is extremely rare.", formation = "Natural prasiolite forms when amethyst-bearing rock is heated by nearby volcanic activity. Most commercial material is heated amethyst.", hardness = "7", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "SiO\u2082 (with Fe)", commonColors = listOf("Pale green", "Leek green", "Mint"), whereFound = listOf("Brazil", "Poland", "Arizona, USA", "Canada"), funFacts = listOf("Also called green amethyst or vermarine.", "Natural prasiolite is thousands of times rarer than heat-treated material.", "Most green quartz sold as prasiolite started as amethyst."), uses = "Jewelry, gemstones, collector specimens.", rarity = "Rare (natural)"),
        Specimen(id = "rutilated-quartz", name = "Quartz, Rutilated", rockClass = RockClass.CRYSTAL, category = "Silicate — Quartz variety (included)", tagline = "Golden needles of rutile trapped in clear quartz.", emoji = "\u2728", colorHex = 0xFFDDAA44, description = "Rutilated quartz is clear quartz containing needle-like inclusions of golden rutile (titanium dioxide). The needles create stunning patterns — like captured sunlight or angel hair frozen in crystal.", formation = "Quartz crystallizes around rutile needles that formed earlier in the same pocket.", hardness = "7", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "SiO\u2082 (with TiO\u2082 needles)", commonColors = listOf("Clear with gold", "Smoky with red", "Milky with copper"), whereFound = listOf("Brazil", "Madagascar", "Pakistan", "Colorado, USA"), funFacts = listOf("The angel-hair-like inclusions are pure titanium dioxide.", "Each rutile needle is a single crystal inside the quartz.", "Called 'Venus hair stone' by ancient Romans."), uses = "Jewelry, gemstone, collector specimens.", rarity = "Common"),
        Specimen(id = "smoky-quartz", name = "Quartz, Smoky", rockClass = RockClass.CRYSTAL, category = "Silicate — Quartz variety", tagline = "Earthy brown to black quartz — colored by natural radiation.", emoji = "\uD83C\uDF2B", colorHex = 0xFF554433, description = "Smoky quartz is quartz colored brown to black by natural radiation from surrounding rocks over millions of years. Scotland's national gem, it's found in the Cairngorm Mountains and prized for jewelry.", formation = "Trace aluminum in quartz is irradiated by natural radioactivity, creating smoky color centers.", hardness = "7", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "SiO\u2082 (with Al + radiation)", commonColors = listOf("Smoky brown", "Black (morion)", "Gray-brown", "Champagne"), whereFound = listOf("Scotland (Cairngorm)", "Colorado, USA", "Brazil", "Switzerland"), funFacts = listOf("Scotland's national gemstone — called Cairngorm after the mountain range.", "The color comes from natural radiation damaging the crystal structure.", "Heating smoky quartz can turn it into citrine."), uses = "Jewelry, collector specimens, ornamental carvings.", rarity = "Common"),
        Specimen(id = "tourmalinated-quartz", name = "Quartz, Tourmalinated", rockClass = RockClass.CRYSTAL, category = "Silicate — Quartz variety (included)", tagline = "Black tourmaline rods piercing through clear quartz.", emoji = "\u26AB", colorHex = 0xFF444444, description = "Tourmalinated quartz is clear quartz with black tourmaline (schorl) crystals running through it like dark lightning bolts frozen in ice. The stark black-and-clear contrast is dramatic and unmistakable.", formation = "Quartz crystallizes around earlier-formed black tourmaline crystals in pegmatite pockets.", hardness = "7", luster = "Vitreous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "SiO\u2082 with black tourmaline", commonColors = listOf("Clear with black", "Smoky with black"), whereFound = listOf("Brazil", "Madagascar", "Maine, USA", "Namibia"), funFacts = listOf("Each black rod is a crystal of schorl tourmaline.", "The contrast makes it popular for jewelry and metaphysical use.", "No two specimens are alike."), uses = "Jewelry, collector specimens, ornamental carvings.", rarity = "Common"),
        Specimen(id = "rainbow-lattice", name = "Rainbow Lattice Sunstone", rockClass = RockClass.CRYSTAL, category = "Silicate — Feldspar variety", tagline = "Grids of iridescent color — the rarest feldspar phenomenon.", emoji = "\uD83C\uDF08", colorHex = 0xFF886644, description = "Rainbow lattice sunstone from Australia's Northern Territory is orthoclase feldspar with oriented inclusions of magnetite and ilmenite that create a grid-like lattice of iridescent rainbow colors. It's one of the rarest feldspar gems.", formation = "Oriented mineral inclusions in feldspar form a geometric grid that diffracts light.", hardness = "6\u20136.5", luster = "Vitreous with iridescent lattice", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "KAlSi\u2083O\u2088 (with Fe/Ti)", commonColors = listOf("Orange-brown with rainbow grid", "Honey"), whereFound = listOf("Northern Territory, Australia"), funFacts = listOf("Found only in a single remote area of Australia's Northern Territory.", "The lattice pattern is perfectly geometric and natural.", "Discovered in 1985 \u2014 one of the newest gem discoveries."), uses = "Rare collector gemstone, jewelry.", rarity = "Extremely Rare"),
        Specimen(id = "rainbow-obsidian", name = "Obsidian, Rainbow", rockClass = RockClass.IGNEOUS, category = "Volcanic glass", tagline = "Iridescent bands of color hiding in black glass.", emoji = "\uD83C\uDF08", colorHex = 0xFF112233, description = "Rainbow obsidian reveals brilliant bands of purple, green, gold, and blue when light catches it at the right angle. Davis Creek, California is the most famous locality for rainbow obsidian.", formation = "Extremely thin layers of different composition form during lava flow, creating a natural diffraction grating.", hardness = "5-6", luster = "Vitreous with iridescent bands", streak = "\u2014", crystalSystem = "Amorphous", chemicalFormula = "SiO2 (glass)", commonColors = listOf("Black with purple bands", "Black with green flash", "Full rainbow iridescence"), whereFound = listOf("Davis Creek, California, USA", "Glass Buttes, Oregon, USA", "Mexico"), funFacts = listOf("Davis Creek rainbow obsidian is world-renowned for its intense color.", "The rainbow is from microscopic layers like an oil slick on water.", "One of the most photographed obsidian varieties."), uses = "Jewelry, cabochons, decorative slabs.", rarity = "Uncommon"),
        Specimen(id = "rhyolite", name = "Rhyolite", rockClass = RockClass.IGNEOUS, category = "Extrusive volcanic rock", tagline = "Fine-grained granite — the lava that built Yellowstone.", emoji = "\uD83C\uDF0B", colorHex = 0xFFCC9988, description = "Rhyolite is the volcanic equivalent of granite, formed from silica-rich lava that cools quickly at the surface. It can show stunning flow banding and contains beautiful spherulites.", formation = "Erupts as thick, sticky lava that flows slowly or forms domes.", hardness = "6\u20137", luster = "Dull to vitreous", streak = "\u2014", crystalSystem = "Aphanitic (fine-grained)", chemicalFormula = "Mixed silicates (felsic)", commonColors = listOf("Pink", "Gray", "Green", "Brown", "Banded"), whereFound = listOf("Yellowstone, USA", "Iceland", "Germany", "New Zealand"), funFacts = listOf("Yellowstone National Park sits on a massive rhyolite lava flow.", "Wonderstone and bird's-eye rhyolite are prized lapidary materials.", "Its high silica content makes it the most explosive type of lava."), uses = "Building stone, lapidary material, decorative aggregate.", rarity = "Common"),
        Specimen(id = "riebeckite", name = "Riebeckite", rockClass = RockClass.MINERAL, category = "Silicate — Amphibole group", tagline = "Dark blue fibrous crystals — source of the tiger-eye gem.", emoji = "\uD83D\uDC38", colorHex = 0xFF224466, description = "Riebeckite is a sodium iron amphibole forming dark blue to black fibrous crystals. When replaced by quartz, riebeckite creates the chatoyant gem tiger-eye — one of the most famous mineral replacement processes.", formation = "Crystallizes in sodium-rich granites and syenites, and in some metamorphic rocks.", hardness = "5–6", luster = "Vitreous to silky", streak = "Bluish-gray", crystalSystem = "Monoclinic", chemicalFormula = "Na₂(Fe₃Fe₂)Si₈O₂₂(OH)₂", commonColors = listOf("Dark blue", "Black", "Navy"), whereFound = listOf("South Africa", "Namibia", "Scotland", "Brazil"), funFacts = listOf("The crocidolite variety of riebeckite creates tiger-eye and hawk-eye gems.", "Named after German explorer Emil Riebeck.", "Fibrous riebeckite is a form of asbestos — handle with care."), uses = "Source of tiger-eye/hawk-eye (when silicified), ornamental stone.", rarity = "Common"),
        Specimen(id = "rugose-coral", name = "Rugose Coral (Horn Coral)", rockClass = RockClass.FOSSIL, category = "Cnidarian — Rugosa", tagline = "The solitary cone that paved Paleozoic seafloors.", emoji = "\uD83D\uDC0F", colorHex = 0xFFC49A6C, description = "Rugose corals, also called horn corals, are extinct solitary and colonial corals that built reefs during the Paleozoic. Their distinctive ridged, cone-shaped fossils are common in Devonian and Mississippian limestone.", formation = "Individual corallites were buried in carbonate mud. The fine radial septa (walls) inside the cup are beautifully preserved in many specimens.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan", "White"), whereFound = listOf("New York, USA", "Kentucky, USA", "Michigan, USA", "England"), funFacts = listOf("They are called horn corals because of their distinctive horn shape.", "Rugose corals went extinct in the Permian mass extinction.", "They show daily and annual growth lines — proving Earth days were shorter in the Paleozoic."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Ordovician – Permian", age = "485 – 252 mya"),
        Specimen(id = "smilodon-tooth", name = "Sabertooth Cat Tooth (Smilodon)", rockClass = RockClass.FOSSIL, category = "Mammal — Felidae", tagline = "The 7-inch serrated dagger of the ice age.", emoji = "\uD83D\uDC05", colorHex = 0xFF8B6914, description = "Smilodon fatalis teeth are unmistakable \u2014 flattened, curved blades up to 7 inches long with fine serrations. These canines were designed to slice through the soft tissue of large prey like bison and mammoths.", formation = "Teeth and bones were preserved in the La Brea Tar Pits (California), Pleistocene caves, and river gravels.", hardness = "—", luster = "Enamel-like", streak = "—", crystalSystem = "N/A", chemicalFormula = "Phosphate / Dentin", commonColors = listOf("Brown", "Dark brown", "Cream"), whereFound = listOf("California, USA (La Brea)", "Florida, USA", "Texas, USA", "Argentina"), funFacts = listOf("Smilodon had the longest canines of any cat \u2014 proportionally longer than any living feline.", "The La Brea Tar Pits have yielded over 2,000 Smilodon individuals.", "Despite the name, they're not closely related to modern tigers."), uses = "Collector specimens, museum displays.", rarity = "Rare", geologicalPeriod = "Pleistocene", age = "2.5 million – 10,000 years ago"),
        Specimen(id = "scaphites", name = "Scaphites (Boat-Shaped Ammonite)", rockClass = RockClass.FOSSIL, category = "Cephalopod — Ammonoidea", tagline = "The ammonite shaped like a paper boat.", emoji = "\uD83D\uDEA3", colorHex = 0xFFC9A86C, description = "Scaphites is an unusual ammonite whose shell starts as a normal coil but then straightens out, then hooks back in a paper-boat shape. This heteromorph form is distinctive and prized by collectors.", formation = "Shells were preserved in Late Cretaceous marine shales and limestones of the Western Interior Seaway.", hardness = "—", luster = "Iridescent to dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite / Aragonite", commonColors = listOf("Brown", "Gray", "Iridescent"), whereFound = listOf("South Dakota, USA", "Montana, USA", "Wyoming, USA", "France"), funFacts = listOf("The uncoiled shape is called 'heteromorph' \u2014 meaning 'different form.'", "Scaphites lived during the last 20 million years of the Cretaceous.", "Their boat shape may have helped them hover at specific depths."), uses = "Collector specimens, index fossils, jewelry.", rarity = "Common", geologicalPeriod = "Late Cretaceous", age = "90 – 66 mya"),
        Specimen(id = "scheelite", name = "Scheelite", rockClass = RockClass.MINERAL, category = "Tungstate mineral", tagline = "Brilliant blue-white fluorescence — the prospector's blacklight gem.", emoji = "\uD83D\uDC8E", colorHex = 0xFFFFF8DC, description = "Scheelite is calcium tungstate and an important tungsten ore. Its brilliant blue-white fluorescence under shortwave UV light is so distinctive that prospectors use UV lamps to find it in the dark — making it one of the easiest ores to locate.", formation = "Forms in high-temperature hydrothermal veins and skarn deposits at the contact of granite and limestone.", hardness = "4.5–5", luster = "Vitreous to adamantine", streak = "White", crystalSystem = "Tetragonal", chemicalFormula = "CaWO₄", commonColors = listOf("White", "Colorless", "Orange", "Brown", "Yellow"), whereFound = listOf("China", "South Korea", "Bolivia", "California, USA"), funFacts = listOf("Scheelite fluoresces brilliant blue-white — prospectors find it at night with UV lamps.", "Named after Swedish chemist Carl Wilhelm Scheele.", "It's surprisingly dense — almost twice as heavy as quartz."), uses = "Tungsten ore, UV fluorescent display mineral.", rarity = "Common"),
        Specimen(id = "scoria", name = "Scoria", rockClass = RockClass.IGNEOUS, category = "Extrusive volcanic rock", tagline = "Dark, bubbly cinders — heavier and darker than pumice.", emoji = "\uD83E\uDEA8", colorHex = 0xFF442222, description = "Scoria is a dark, vesicular volcanic rock filled with gas bubbles. It's like pumice but heavier and darker because it's from basaltic lava, and forms the cinder cones that dot volcanic landscapes worldwide.", formation = "Gas-charged basaltic lava is thrown into the air during fire-fountain eruptions and solidifies around bubbles before hitting the ground.", hardness = "\u2014 (friable)", luster = "Dull", streak = "\u2014", crystalSystem = "Amorphous (volcanic glass)", chemicalFormula = "Mafic silicates (basaltic glass)", commonColors = listOf("Red-brown", "Black", "Dark gray"), whereFound = listOf("Sunset Crater, Arizona, USA", "Hawaii", "Italy (Etna)", "Iceland"), funFacts = listOf("Scoria is heavier than pumice and usually doesn't float.", "Cinder cones are made entirely of scoria fragments.", "It's excellent for drainage in gardening and green roofs."), uses = "Lightweight aggregate, landscaping, barbecue lava rocks.", rarity = "Common"),
        Specimen(id = "sepiolite", name = "Sepiolite", rockClass = RockClass.MINERAL, category = "Silicate — Phyllosilicate", tagline = "The foam of the sea — carved into the finest pipes.", emoji = "\uD83D\uDEAC", colorHex = 0xFFF8F0D8, description = "Sepiolite, also called meerschaum (German for 'sea foam'), is a soft, porous magnesium silicate that's been carved into ornate smoking pipes for centuries. It's so light it floats on water.", formation = "Forms from the alteration of serpentinite in arid environments, often as nodules in clay.", hardness = "2", luster = "Earthy to dull", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Mg\u2084Si\u2086O\u2081\u2085(OH)\u2082\u00B76H\u2082O", commonColors = listOf("White", "Cream", "Yellowish", "Gray"), whereFound = listOf("Turkey (Eskisehir)", "Tanzania", "Spain", "New Mexico, USA"), funFacts = listOf("Meerschaum means 'sea foam' — it's so light it floats.", "The finest meerschaum pipes come from Eskisehir, Turkey.", "It's so soft you can carve it with a pocket knife."), uses = "Carved pipes, ornamental objects, absorbents, cat litter.", rarity = "Uncommon"),
        Specimen(id = "shattuckite", name = "Shattuckite", rockClass = RockClass.MINERAL, category = "Silicate mineral", tagline = "Vivid cobalt-blue fibrous sprays from the Arizona desert.", emoji = "\uD83D\uDD35", colorHex = 0xFF1E5FAA, description = "Shattuckite is a copper silicate hydroxide with a brilliant cobalt-blue color. It forms fibrous, botryoidal masses and is often found intergrown with chrysocolla and malachite in stunning blue-green combination specimens.", formation = "A secondary copper mineral formed in the oxidized zone of copper deposits, especially in arid environments.", hardness = "3.5", luster = "Silky to vitreous", streak = "Pale blue", crystalSystem = "Orthorhombic", chemicalFormula = "Cu\u2085(SiO\u2083)\u2084(OH)\u2082", commonColors = listOf("Cobalt blue", "Dark blue", "Sky blue"), whereFound = listOf("Arizona, USA", "Namibia", "Democratic Republic of Congo", "Greece"), funFacts = listOf("Named after the Shattuck Mine in Bisbee, Arizona.", "Often confused with chrysocolla — shattuckite is a richer, deeper blue.", "Combination specimens with chrysocolla and malachite are highly prized by collectors."), uses = "Collector specimens, jewelry, ornamental carvings.", rarity = "Rare"),
        Specimen(id = "shortite", name = "Shortite", rockClass = RockClass.MINERAL, category = "Carbonate mineral", tagline = "Green River Formation's unique carbonate.", emoji = "\uD83D\uDC8E", colorHex = 0xFFFFF8DD, description = "Shortite is a rare sodium calcium carbonate mineral found in the Green River Formation of Wyoming. It was first discovered in an oil well core sample.", formation = "Precipitated in Eocene lake sediments of the Green River Formation.", hardness = "3", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Na\u2082Ca\u2082(CO\u2083)\u2083", commonColors = listOf("Colorless", "White", "Pale yellow"), whereFound = listOf("Green River Formation, Wyoming, USA", "Colorado, USA"), funFacts = listOf("First discovered in a Wyoming oil well core in 1939.", "Named after American mineralogist Maxwell Short.", "Found almost exclusively in the Green River Formation."), uses = "Collector specimens, geological indicator.", rarity = "Rare"),
        Specimen(id = "siderite", name = "Siderite", rockClass = RockClass.MINERAL, category = "Carbonate mineral", tagline = "Brown iron carbonate — the mineral that makes clay red.", emoji = "\uD83E\uDE9B", colorHex = 0xFF886633, description = "Siderite is iron carbonate, forming brown rhombohedral crystals and massive deposits. When weathered, it turns into reddish-brown iron oxides — the same process that colors red beds and terra cotta.", formation = "Precipitates in iron-rich sedimentary environments like bogs, swamps, and shallow marine basins.", hardness = "3.5\u20134", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "FeCO\u2083", commonColors = listOf("Brown", "Tan", "Reddish-brown", "Gray"), whereFound = listOf("England", "Brazil", "Colorado, USA", "Portugal"), funFacts = listOf("Siderite means 'iron' in Greek.", "Weathered siderite gives red beds their color.", "It's an important iron ore in some regions."), uses = "Iron ore, pigment, steelmaking.", rarity = "Common"),
        Specimen(id = "sillimanite", name = "Sillimanite", rockClass = RockClass.MINERAL, category = "Silicate — Nesosilicate", tagline = "Silky fibers — the high-temperature aluminum silicate.", emoji = "\uD83E\uDEA2", colorHex = 0xFFDDDDCC, description = "Sillimanite is the highest-temperature polymorph of aluminum silicate, forming fibrous or prismatic crystals in high-grade metamorphic rocks. Gem-quality sillimanite has a beautiful silky luster when cut as cabochons.", formation = "Crystallizes during high-temperature, high-grade metamorphism of aluminum-rich rocks.", hardness = "6.5–7.5", luster = "Vitreous to silky", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Al₂SiO₅", commonColors = listOf("White", "Gray", "Brown", "Green"), whereFound = listOf("Delaware, USA", "India", "Brazil", "Myanmar"), funFacts = listOf("Named after American geologist Benjamin Silliman.", "It's the third Al₂SiO₅ polymorph alongside kyanite and andalusite.", "Fibrous sillimanite is called fibrolite and has a silky sheen."), uses = "Refractory ceramics, gemstone (cat's-eye sillimanite).", rarity = "Common"),
        Specimen(id = "siltstone", name = "Siltstone", rockClass = RockClass.SEDIMENTARY, category = "Clastic sedimentary rock", tagline = "Between shale and sandstone — the middle-child sedimentary rock.", emoji = "\uD83E\uDEA8", colorHex = 0xFF998877, description = "Siltstone is a sedimentary rock made of silt-sized particles \u2014 finer than sand but coarser than clay. It forms in quieter water than sandstone and often shows delicate sedimentary structures.", formation = "Silt settles in slow-moving or still water and is compacted and cemented.", hardness = "3\u20136", luster = "Dull", streak = "\u2014", crystalSystem = "Clastic aggregate", chemicalFormula = "Mixed quartz and clay", commonColors = listOf("Gray", "Brown", "Red", "Green"), whereFound = listOf("Every continent", "River floodplains", "Lake beds", "Deep sea floors"), funFacts = listOf("It feels slightly gritty to the touch \u2014 unlike shale which feels smooth.", "Siltstone preserves delicate fossils that would be destroyed in coarser rock.", "It's one of the most abundant sedimentary rocks."), uses = "Building stone, crushed stone, cement production.", rarity = "Common"),
        Specimen(id = "silver-sheen-obsidian", name = "Obsidian, Silver Sheen", rockClass = RockClass.IGNEOUS, category = "Volcanic glass", tagline = "Mirror-like silver flash across black volcanic glass.", emoji = "\uD83E\uDE99", colorHex = 0xFF888899, description = "Silver sheen obsidian displays a brilliant mirror-like silvery reflection across jet-black obsidian from microscopic gas bubbles aligned in layers.", formation = "Microscopic elongated gas bubbles stretched by flowing lava before freezing create reflective layers.", hardness = "5-6", luster = "Vitreous with silver metallic sheen", streak = "\u2014", crystalSystem = "Amorphous", chemicalFormula = "SiO2 (glass)", commonColors = listOf("Black with silver", "Dark with white-gray flash"), whereFound = listOf("Glass Buttes, Oregon, USA", "Davis Creek, California, USA", "Mexico"), funFacts = listOf("Silver sheen is caused by microscopic stretched gas bubbles.", "Glass Buttes is a premier obsidian collecting location.", "Native Americans traded obsidian across thousands of miles."), uses = "Jewelry, cabochons.", rarity = "Uncommon"),
        Specimen(id = "skarn", name = "Skarn", rockClass = RockClass.METAMORPHIC, category = "Contact metamorphic rock", tagline = "Garnet-rich rock born where magma meets limestone.", emoji = "\uD83C\uDF76", colorHex = 0xFF886644, description = "Skarn is a contact metamorphic rock formed when magma intrudes into limestone. Many of the world's finest mineral specimens and most valuable ore deposits come from skarn environments.", formation = "Hot, silica-rich fluids from cooling granite react with carbonate rocks, creating unique mineral assemblages.", hardness = "Varies (5\u20137)", luster = "Vitreous to resinous", streak = "\u2014", crystalSystem = "Granoblastic aggregate", chemicalFormula = "Ca-Fe-Mg silicates (+ ore)", commonColors = listOf("Brown-red (garnet)", "Green", "Mixed", "Dark brown"), whereFound = listOf("Arizona, USA", "Romania", "Russia", "Peru"), funFacts = listOf("Many of the world's greatest mineral specimens come from skarns.", "Skarn deposits are major sources of copper, iron, gold, and tungsten.", "Named from an old Swedish mining term for waste rock."), uses = "Ore deposits, collector minerals, geological research.", rarity = "Common"),
        Specimen(id = "snowflake-obsidian", name = "Obsidian, Snowflake", rockClass = RockClass.IGNEOUS, category = "Volcanic glass", tagline = "Jet-black glass dotted with white crystalline snowflakes.", emoji = "\u2744\uFE0F", colorHex = 0xFF111122, description = "Snowflake obsidian is black volcanic glass with white cristobalite spherulite inclusions that look like snowflakes on a dark sky. Utah's Black Rock Desert is world-famous for it.", formation = "Obsidian cools slowly enough for cristobalite to crystallize as radial spherulites within the glass.", hardness = "5-6", luster = "Vitreous", streak = "\u2014", crystalSystem = "Amorphous (with cristobalite)", chemicalFormula = "SiO2 (glass + cristobalite)", commonColors = listOf("Black with white", "Dark gray with gray spots"), whereFound = listOf("Black Rock Desert, Utah, USA", "Glass Buttes, Oregon, USA", "Mexico", "Iceland"), funFacts = listOf("Each snowflake is a radial cluster of cristobalite crystals.", "Spherulites formed while lava was still cooling.", "Utah's Black Rock Desert is famous for snowflake obsidian."), uses = "Jewelry, cabochons, carvings.", rarity = "Common"),
        Specimen(id = "spirifer", name = "Spirifer Brachiopod", rockClass = RockClass.FOSSIL, category = "Brachiopoda — Spiriferida", tagline = "The wing-shelled filter-feeder of Devonian seas.", emoji = "\uD83E\uDEB2", colorHex = 0xFFC4A87C, description = "Spirifer brachiopods have a distinctive wing-like shell extension with a long hinge line. These beautiful 'winged' shells are among the most common fossils in Devonian and Mississippian rocks worldwide.", formation = "Shells buried in shallow sea carbonate and shale deposits. The winged shape fossilizes beautifully and makes them easy to identify.", hardness = "—", luster = "Dull to pearly", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "Brown", "Tan"), whereFound = listOf("New York, USA", "Iowa, USA", "Ohio, USA", "Germany"), funFacts = listOf("The wings made spirifers look like small stone butterflies.", "They were particularly abundant in the Devonian \u2014 the 'Age of Brachiopods.'", "Spirifer fossils are often pyritized \u2014 preserved in brassy pyrite."), uses = "Collector specimens, index fossils for Devonian rocks.", rarity = "Common", geologicalPeriod = "Devonian – Permian", age = "419 – 252 mya"),
        Specimen(id = "hiddenite", name = "Hiddenite", rockClass = RockClass.CRYSTAL, category = "Silicate — Pyroxene (Spodumene)", tagline = "The emerald-green spodumene found only in North Carolina.", emoji = "\uD83D\uDC9A", colorHex = 0xFF44AA44, description = "Hiddenite is the vivid green chromium-bearing variety of spodumene. It's far rarer than its pink cousin kunzite and the finest crystals are found exclusively in Hiddenite, North Carolina — the town named after the gem.", formation = "Crystallizes in lithium-rich pegmatites where chromium is present — a rare combination.", hardness = "6.5–7", luster = "Vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "LiAlSi₂O₆ (with Cr)", commonColors = listOf("Emerald green", "Yellow-green", "Apple green"), whereFound = listOf("Hiddenite, North Carolina, USA", "Brazil", "Afghanistan", "Madagascar"), funFacts = listOf("Named after W.E. Hidden, who discovered it in North Carolina in 1879.", "A town in North Carolina was literally renamed after this gem.", "Like kunzite, hiddenite can fade with prolonged sun exposure."), uses = "Gemstone, collector specimens.", rarity = "Rare"),
        Specimen(id = "kunzite", name = "Kunzite", rockClass = RockClass.CRYSTAL, category = "Silicate — Pyroxene (Spodumene)", tagline = "Delicate pink-lavender gem named after Tiffany's gemologist.", emoji = "\uD83C\uDF38", colorHex = 0xFFE8B4C8, description = "Kunzite is the pink-to-violet variety of spodumene, colored by trace manganese. Its delicate pastel color and strong pleochroism make it a favorite among gem collectors — but it can fade in prolonged sunlight.", formation = "Crystallizes in lithium-rich granite pegmatites alongside tourmaline and beryl.", hardness = "6.5–7", luster = "Vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "LiAlSi₂O₆ (with Mn)", commonColors = listOf("Pink", "Lilac", "Lavender", "Peach"), whereFound = listOf("California, USA", "Afghanistan", "Brazil", "Madagascar"), funFacts = listOf("Named after George F. Kunz, the legendary gemologist at Tiffany & Co.", "Kunzite can fade in sunlight — store it in a dark box.", "The largest faceted kunzite weighs over 880 carats."), uses = "Gemstone, jewelry, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "stilbite", name = "Stilbite", rockClass = RockClass.MINERAL, category = "Silicate — Zeolite group", tagline = "Peach-colored sheaf-like crystals — the prettiest zeolite.", emoji = "\uD83C\uDF51", colorHex = 0xFFFFAA88, description = "Stilbite is a beautiful zeolite forming sheaf-like bundles of tabular crystals in shades of white, peach, and pink. It's one of the most attractive and popular zeolite minerals for collectors.", formation = "Crystallizes in cavities and veins of basaltic lava flows, often with other zeolites.", hardness = "3.5–4", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "NaCa₄(Si₂₇Al₉)O₇₂·28H₂O", commonColors = listOf("Peach", "Pink", "White", "Cream", "Orange"), whereFound = listOf("India", "Iceland", "New Jersey, USA", "Nova Scotia, Canada"), funFacts = listOf("Stilbite's crystal bundles look like flower petals or sheaves of wheat.", "Named from Greek 'stilbein' meaning to shine — from its pearly luster.", "The finest peach-colored crystals come from the Deccan Traps in India."), uses = "Collector specimens, decorative mineral displays.", rarity = "Common"),
        Specimen(id = "stromatolite", name = "Stromatolite - Fossilized", rockClass = RockClass.FOSSIL, category = "Microbial — Cyanobacteria", tagline = "The oldest fossil on Earth — layered mats of life.", emoji = "\uD83E\uDEB7", colorHex = 0xFFB8A878, description = "Stromatolites are layered sedimentary structures formed by cyanobacteria mats trapping and binding sediment. They are the oldest macroscopic fossils on Earth, with examples dating back 3.5 billion years. Rarity: Rare (ancient).", formation = "Photosynthetic cyanobacteria grow in mats. Sediment sticks to the sticky surface, and new mats grow on top, building layer upon layer over thousands of years.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcium carbonate / Silica", commonColors = listOf("Tan", "Gray", "Brown"), whereFound = listOf("Montana, USA", "Australia", "Bolivia", "South Africa"), funFacts = listOf("Stromatolites created Earth's oxygen atmosphere over billions of years.", "Living stromatolites still exist at Shark Bay, Australia.", "They are the first visible evidence of life on our planet."), uses = "Collector specimens, scientific study.", rarity = "Rare (ancient)", geologicalPeriod = "Archean – Present", age = "3.5 billion years – today"),
        Specimen(id = "stromatoporoid", name = "Stromatoporoid (Fossil Sponge)", rockClass = RockClass.FOSSIL, category = "Porifera — Stromatoporoidea", tagline = "The reef-building sponge of Paleozoic seas.", emoji = "\uD83E\uDEB8", colorHex = 0xFFB8A890, description = "Stromatoporoids were calcareous sponges that were among the primary reef builders of the Silurian and Devonian periods. Their massive, layered skeletons look like cabbage heads in cross-section.", formation = "Massive skeletons accumulated in shallow carbonate seas and became major components of ancient reef structures.", hardness = "—", luster = "Dull", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite", commonColors = listOf("Gray", "White", "Tan", "Brown"), whereFound = listOf("Michigan, USA", "Ohio, USA", "New York, USA", "England"), funFacts = listOf("Stromatoporoids built reefs before corals took over that role.", "Petoskey stones (fossil coral) are often found alongside stromatoporoids.", "They went extinct in the Devonian mass extinction."), uses = "Collector specimens, educational displays.", rarity = "Common", geologicalPeriod = "Ordovician – Devonian", age = "450 – 359 mya"),
        Specimen(id = "strontianite", name = "Strontianite", rockClass = RockClass.MINERAL, category = "Carbonate mineral", tagline = "The Scottish mineral that gave us strontium.", emoji = "\uD83D\uDC8E", colorHex = 0xFFDDEEBB, description = "Strontianite is strontium carbonate, discovered in Strontian, Scotland in 1790. It was the mineral from which the element strontium was first isolated — and the Scottish village gave its name to the element.", formation = "Crystallizes in low-temperature hydrothermal veins and cavities in limestone.", hardness = "3.5", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "SrCO\u2083", commonColors = listOf("Colorless", "White", "Pale green", "Yellowish"), whereFound = listOf("Strontian, Scotland", "Germany", "Ohio, USA", "Canada"), funFacts = listOf("The element strontium was discovered from this mineral in Scotland.", "Named after the village of Strontian in the Scottish Highlands.", "Strontium gives red fireworks their brilliant crimson color."), uses = "Strontium ore, fireworks (red), sugar refining.", rarity = "Uncommon"),
        Specimen(id = "sugilite", name = "Sugilite", rockClass = RockClass.MINERAL, category = "Silicate — Cyclosilicate", tagline = "Rich purple masses from South Africa's manganese fields.", emoji = "\uD83D\uDC9C", colorHex = 0xFF664288, description = "Sugilite is a rare potassium sodium lithium manganese aluminum silicate with a distinctive rich purple to magenta color. The finest gem-grade material comes from the Kalahari Manganese Field in South Africa.", formation = "Forms in metamorphosed manganese deposits under oxidizing conditions.", hardness = "5.5–6.5", luster = "Vitreous to waxy", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "KNa₂(Fe,Mn,Al)₂Li₃Si₁₂O₃₀", commonColors = listOf("Deep purple", "Magenta", "Lavender", "Pinkish-purple"), whereFound = listOf("South Africa", "Japan", "Canada", "Italy"), funFacts = listOf("Named after Japanese petrologist Ken-ichi Sugi.", "Gem-quality sugilite can be worth more than fine amethyst.", "It's sometimes called 'royal lavulite' in the gem trade."), uses = "Gemstone, collector specimens, jewelry.", rarity = "Rare"),
        Specimen(id = "sylvite", name = "Sylvite", rockClass = RockClass.MINERAL, category = "Halide mineral", tagline = "Red potash crystals — the fertilizer that feeds the world.", emoji = "\uD83D\uDD34", colorHex = 0xFFFF6644, description = "Sylvite is potassium chloride, the most important source of potash for fertilizer. It forms cubic crystals that can be colorless, white, or stunning shades of red and blue from impurities.", formation = "Evaporates from the last stages of ancient sea water evaporation, after halite has crystallized.", hardness = "2", luster = "Vitreous", streak = "White", crystalSystem = "Cubic", chemicalFormula = "KCl", commonColors = listOf("Red-orange", "Blue", "Colorless", "White"), whereFound = listOf("Saskatchewan, Canada", "Russia", "Germany", "New Mexico, USA"), funFacts = listOf("Sylvite is the world's primary source of potassium for fertilizer.", "It tastes salty but bitter — unlike halite (table salt).", "Named after Dutch chemist Franciscus Sylvius."), uses = "Potassium fertilizer, chemical industry, salt substitute.", rarity = "Common"),
        Specimen(id = "taaffeite", name = "Taaffeite", rockClass = RockClass.CRYSTAL, category = "Oxide mineral", tagline = "A million times rarer than diamond — discovered by accident.", emoji = "\uD83D\uDC8E", colorHex = 0xFFCC66AA, description = "Taaffeite is magnesium beryllium aluminum oxide and one of the rarest gem minerals on Earth. It was discovered by accident in 1945 when a gemologist found one in a parcel of spinel — the only gemstone first identified from a faceted stone.", formation = "Crystallizes in metamorphosed limestones and skarns under very specific conditions.", hardness = "8\u20138.5", luster = "Vitreous", streak = "White", crystalSystem = "Hexagonal", chemicalFormula = "MgBeAl\u2084O\u2088", commonColors = listOf("Mauve", "Lilac", "Colorless", "Greenish"), whereFound = listOf("Sri Lanka", "Myanmar", "Tanzania", "China"), funFacts = listOf("Taaffeite is millions of times rarer than diamond.", "It was the first gemstone discovered from a faceted stone.", "Named after Count Edward Taaffe, who spotted it in a parcel of spinel."), uses = "Extremely rare collector gemstone.", rarity = "Extremely Rare"),
        Specimen(id = "thomsonite", name = "Thomsonite", rockClass = RockClass.MINERAL, category = "Silicate — Zeolite group", tagline = "Pink-eyed pebbles from the shores of Lake Superior.", emoji = "\uD83E\uDE9D", colorHex = 0xFFE8C8C8, description = "Thomsonite is a zeolite mineral that forms distinctive pink, white, and green concentric patterns — often called 'thomsonite eyes' when cut as cabochons. Lake Superior's north shore produces the world's finest gem thomsonite.", formation = "Crystallizes in the gas cavities of basaltic lava flows, often with other zeolites.", hardness = "5–5.5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "NaCa₂Al₅Si₅O₂₀·6H₂O", commonColors = listOf("Pink with white", "Green with pink eyes", "Colorless", "Orange"), whereFound = listOf("Minnesota, USA (Lake Superior)", "Oregon, USA", "India", "Scotland"), funFacts = listOf("Thomsonite eyes from Minnesota's Lake Superior shore are world-famous.", "Named after Scottish chemist Thomas Thomson.", "Each cabochon shows a unique eye-like pattern."), uses = "Cabochons, jewelry, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "torbernite", name = "Torbernite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Emerald-green crystals — uranium's poison beauty.", emoji = "\uD83D\uDC9A", colorHex = 0xFF1E8C4C, description = "Torbernite is a hydrated copper uranium phosphate forming stunning emerald-green square tabular crystals. It's one of the most beautiful radioactive minerals, prized by collectors who understand and respect its risks.", formation = "A secondary uranium mineral formed in the oxidized zone of uranium-copper deposits.", hardness = "2\u20132.5", luster = "Vitreous to pearly", streak = "Pale green", crystalSystem = "Tetragonal", chemicalFormula = "Cu(UO\u2082)\u2082(PO\u2084)\u2082\u00B78-12H\u2082O", commonColors = listOf("Emerald green", "Grass green", "Dark olive"), whereFound = listOf("Democratic Republic of Congo", "France", "Cornwall, England", "South Australia"), funFacts = listOf("Like autunite, torbernite dehydrates and loses water over time.", "Named after Swedish chemist Torbern Bergman.", "The square, tabular crystal habit is unmistakable among uranium minerals."), uses = "Uranium ore indicator, high-end collector specimens.", rarity = "Rare"),
        Specimen(id = "travertine", name = "Travertine", rockClass = RockClass.SEDIMENTARY, category = "Chemical sedimentary rock", tagline = "The stone of Rome — layered calcite from hot springs.", emoji = "\uD83C\uDFDB\uFE0F", colorHex = 0xFFEEE8D5, description = "Travertine is a form of limestone deposited by mineral springs, especially hot springs. Its characteristic holes and pitted surface made it the signature building stone of ancient Rome.", formation = "Calcium carbonate precipitates from mineral-rich spring water at the surface, creating layered, porous deposits.", hardness = "3\u20134", luster = "Dull to vitreous", streak = "White", crystalSystem = "Layered aggregate", chemicalFormula = "CaCO\u2083", commonColors = listOf("Cream", "Tan", "White", "Ivory", "Pink"), whereFound = listOf("Italy (Tivoli)", "Yellowstone, USA", "Turkey (Pamukkale)", "Iran"), funFacts = listOf("The Colosseum in Rome is built from travertine.", "Pamukkale's stunning white terraces in Turkey are travertine.", "It forms in caves as stalactites and stalagmites."), uses = "Building stone, countertops, flooring, decorative tile.", rarity = "Common"),
        Specimen(id = "tremolite", name = "Tremolite", rockClass = RockClass.MINERAL, category = "Silicate — Amphibole group", tagline = "White to green fibrous crystals — from marble to nephrite jade.", emoji = "\uD83E\uDEA2", colorHex = 0xFFDDFFDD, description = "Tremolite is a calcium magnesium amphibole forming white to pale green fibrous or bladed crystals in metamorphosed limestones. It's the primary mineral of nephrite jade when it forms as a dense, tough aggregate.", formation = "Forms during contact and regional metamorphism of dolomitic limestones.", hardness = "5–6", luster = "Vitreous to silky", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "Ca₂(Mg₅)(Si₈O₂₂)(OH)₂", commonColors = listOf("White", "Pale green", "Gray", "Lavender (hexagonite)"), whereFound = listOf("New York, USA", "Italy", "Pakistan", "Canada"), funFacts = listOf("Tremolite is the primary constituent of nephrite — one of the two jade minerals.", "The purple variety is called hexagonite and is unique to New York state.", "Named after the Tremola Valley in Switzerland."), uses = "Nephrite jade, ornamental stone, mineral specimens.", rarity = "Common"),
        Specimen(id = "trilobite", name = "Trilobite", rockClass = RockClass.FOSSIL, category = "Arthropod — Trilobita", tagline = "The armored bug that ruled Paleozoic seas for 270 million years.", emoji = "\uD83E\uDEB2", colorHex = 0xFFB8956E, description = "Trilobites were marine arthropods with a distinctive three-lobed body plan. One of Earth's most successful animal groups, they survived for over 270 million years and left an incredible fossil record with thousands of species.", formation = "Trilobites molted their exoskeletons as they grew, leaving many fossilized shells. Rapid burial in seafloor sediment preserved even delicate details like eyes and antennae.", hardness = "—", luster = "Dull to waxy", streak = "—", crystalSystem = "N/A", chemicalFormula = "Calcite replacement", commonColors = listOf("Brown", "Black", "Gray"), whereFound = listOf("Ohio, USA", "Utah, USA", "Morocco", "Czech Republic"), funFacts = listOf("Trilobites had the first complex eyes — some with lenses of calcite.", "They could roll up like pill bugs for protection.", "Over 20,000 species have been described."), uses = "Collector specimens, scientific study, jewelry.", rarity = "Common", geologicalPeriod = "Cambrian – Permian", age = "521 – 252 mya"),
        Specimen(id = "tuff", name = "Tuff", rockClass = RockClass.IGNEOUS, category = "Pyroclastic rock", tagline = "Compacted volcanic ash — the soft stone of ancient cities.", emoji = "\uD83C\uDF0B", colorHex = 0xFFDDCCAA, description = "Tuff is rock formed from compacted volcanic ash and pumice fragments ejected during explosive eruptions. It's soft enough to carve easily, which made it a favorite building stone for ancient civilizations.", formation = "Volcanic ash and pumice settle after explosive eruptions and are compacted and cemented over time.", hardness = "Soft to moderate", luster = "Earthy", streak = "\u2014", crystalSystem = "Pyroclastic aggregate", chemicalFormula = "Mixed volcanic glass and crystals", commonColors = listOf("Tan", "Cream", "Gray", "Pink", "Brown"), whereFound = listOf("Cappadocia, Turkey", "Yellowstone, USA", "Italy", "New Zealand"), funFacts = listOf("The underground cities of Cappadocia were carved into soft tuff.", "Mount Vesuvius buried Pompeii under tuff and ash.", "Tuff can contain fossils of animals caught in volcanic eruptions."), uses = "Building stone, carved architecture, pozzolanic cement.", rarity = "Common"),
        Specimen(id = "ulexite", name = "Ulexite", rockClass = RockClass.MINERAL, category = "Borate mineral", tagline = "Natural fiber optics — transmits images through stone.", emoji = "\uD83D\uDCFA", colorHex = 0xFFFFFFFF, description = "Ulexite is a sodium calcium borate with a remarkable optical property — its parallel fibrous crystals act like natural fiber optics, transmitting an image from one side of the crystal to the other. Place it on a newspaper and the text appears on top.", formation = "Evaporates from boron-rich playa lakes in arid desert basins.", hardness = "2.5", luster = "Silky to vitreous", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "NaCaB₅O₆(OH)₆·5H₂O", commonColors = listOf("White", "Colorless", "Grayish"), whereFound = listOf("California, USA (Boron)", "Nevada, USA", "Chile", "Argentina"), funFacts = listOf("Ulexite is the only mineral that acts as natural fiber optics.", "Called 'TV rock' because images appear to float on the crystal's surface.", "Named after German chemist Georg Ulex."), uses = "Optical novelty, boron ore, educational demonstrations.", rarity = "Common"),
        Specimen(id = "vanadinite-new", name = "Vanadinite", rockClass = RockClass.MINERAL, category = "Vanadate mineral", tagline = "Blood-red hexagonal prisms from the Moroccan desert.", emoji = "\uD83D\uDD34", colorHex = 0xFFCC2200, description = "Vanadinite is lead vanadate chloride, forming brilliant red to orange hexagonal prisms. The finest specimens come from Mibladen, Morocco and are instantly recognizable by their intense color and glassy luster on a white barite matrix.", formation = "Forms in the oxidized zone of lead deposits in arid climates where vanadium is present.", hardness = "3\u20134", luster = "Resinous to adamantine", streak = "Yellowish-white", crystalSystem = "Hexagonal", chemicalFormula = "Pb\u2085(VO\u2084)\u2083Cl", commonColors = listOf("Blood red", "Ruby", "Orange-red", "Brown"), whereFound = listOf("Morocco (Mibladen)", "Arizona, USA", "Mexico", "Namibia"), funFacts = listOf("Mibladen, Morocco has produced the world's largest and finest vanadinite crystals.", "The hexagonal prisms often look like miniature ruby crystals.", "Named after its vanadium content."), uses = "Vanadium ore, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "variscite", name = "Variscite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Apple-green phosphate — the softer, rarer cousin of turquoise.", emoji = "\uD83D\uDFE2", colorHex = 0xFF55AA55, description = "Variscite is a hydrated aluminum phosphate with a bright apple-green color often confused with turquoise. Unlike turquoise, it lacks copper and is somewhat softer. Utah produces world-class nodular variscite.", formation = "Forms near the surface when phosphate-rich water interacts with aluminum-bearing rocks.", hardness = "3.5–4.5", luster = "Vitreous to waxy", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "AlPO₄·2H₂O", commonColors = listOf("Apple green", "Emerald green", "Yellowish-green", "White veined"), whereFound = listOf("Utah, USA", "Nevada, USA", "Australia", "Poland"), funFacts = listOf("Often sold as 'Utah turquoise' — but it's a different mineral.", "The best variscite nodules from Utah rival fine Chinese turquoise.", "Named after Variscia, the ancient Latin name for the Vogtland region of Germany."), uses = "Jewelry, ornamental carvings, cabochons.", rarity = "Uncommon"),
        Specimen(id = "vesuvianite", name = "Vesuvianite", rockClass = RockClass.MINERAL, category = "Silicate — Sorosilicate", tagline = "Green-brown prisms from Vesuvius — a volcano's signature mineral.", emoji = "\uD83C\uDF0B", colorHex = 0xFF668844, description = "Vesuvianite, also called idocrase, was first discovered in the ejected blocks of Mount Vesuvius in Italy. It forms tetragonal prismatic crystals in green, brown, yellow, and blue colors from contact metamorphism of limestone.", formation = "Crystallizes in skarn deposits where magma intrudes into limestone, and in regionally metamorphosed rocks.", hardness = "6.5", luster = "Vitreous to resinous", streak = "White", crystalSystem = "Tetragonal", chemicalFormula = "Ca₁₀(Mg,Fe)₂Al₄(SiO₄)₅(Si₂O₇)₂(OH,F)₄", commonColors = listOf("Green", "Brown", "Yellow", "Blue (cyprine)"), whereFound = listOf("Mount Vesuvius, Italy", "Quebec, Canada", "Kenya", "California, USA"), funFacts = listOf("Named after Mount Vesuvius in Italy where it was first discovered.", "The blue variety is called cyprine and is highly prized.", "Good crystals are often confused with grossular garnet."), uses = "Gemstone, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "vivianite", name = "Vivianite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Colorless crystals that turn deathly dark green in light.", emoji = "\uD83D\uDFE2", colorHex = 0xFF224422, description = "Vivianite is a hydrated iron phosphate with a remarkable property — it's colorless when first exposed but darkens to deep dark green or green-black upon exposure to light. This photochromic reaction makes it a fascinating mineral for collectors.", formation = "Forms in organic-rich sedimentary environments, particularly in peat bogs, lake sediments, and as an alteration product in ore deposits.", hardness = "1.5–2", luster = "Vitreous to pearly (fresh), dull (oxidized)", streak = "White to greenish", crystalSystem = "Monoclinic", chemicalFormula = "Fe₃(PO₄)₂·8H₂O", commonColors = listOf("Colorless (fresh)", "Deep dark green", "Green-black", "Dark green"), whereFound = listOf("Bolivia", "Colorado, USA", "Ukraine", "England"), funFacts = listOf("Vivianite is colorless underground but darkens to deep green in sunlight.", "Named after English mineralogist J.G. Vivian.", "Some crystals found in peat bogs can be several feet long."), uses = "Collector specimens, iron phosphate indicator.", rarity = "Uncommon"),
        Specimen(id = "wavellite", name = "Wavellite", rockClass = RockClass.MINERAL, category = "Phosphate mineral", tagline = "Green radiating spheres — nature's green sunbursts.", emoji = "\uD83D\uDFE2", colorHex = 0xFF669944, description = "Wavellite is a hydrated aluminum phosphate forming beautiful green to yellow-green radiating spherical aggregates that look like sunbursts. The best specimens come from Arkansas and are highly prized by collectors.", formation = "Crystallizes in fractures and cavities of aluminum-rich sedimentary and metamorphic rocks.", hardness = "3.5\u20134", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "Al\u2083(PO\u2084)\u2082(OH)\u2083\u00B75H\u2082O", commonColors = listOf("Green", "Yellow-green", "White", "Blue-green"), whereFound = listOf("Arkansas, USA", "Bolivia", "England", "Germany"), funFacts = listOf("Named after English physician William Wavell.", "Arkansas wavellite is world-famous for its vivid green color.", "The radiating crystal clusters look like miniature green fireworks."), uses = "Collector specimens, aluminum phosphate indicator.", rarity = "Uncommon"),
        Specimen(id = "willemite", name = "Willemite", rockClass = RockClass.MINERAL, category = "Silicate — Nesosilicate", tagline = "Electric green fluorescence — the king of UV minerals.", emoji = "\uD83D\uDFE2", colorHex = 0xFF44AA44, description = "Willemite is zinc silicate famous for its astonishing bright green fluorescence under shortwave UV light. The Franklin-Sterling Hill district in New Jersey produces the world's finest specimens, often intergrown with fluorescent calcite (red) for a stunning red-green display.", formation = "Crystallizes in metamorphosed zinc ore deposits under unique geological conditions.", hardness = "5.5", luster = "Vitreous to resinous", streak = "White", crystalSystem = "Trigonal", chemicalFormula = "Zn₂SiO₄", commonColors = listOf("Green (fluorescent)", "White", "Yellow-green", "Brown"), whereFound = listOf("Franklin, New Jersey, USA", "Namibia", "Belgium", "Greenland"), funFacts = listOf("The Franklin-Sterling Hill mines in NJ produce willemite that glows an otherworldly green under UV.", "Named after King Willem I of the Netherlands.", "Combined with red-fluorescing calcite, it creates a natural red-green UV Christmas display."), uses = "Zinc ore, fluorescent mineral displays, collector specimens.", rarity = "Uncommon"),
        Specimen(id = "witherite", name = "Witherite", rockClass = RockClass.MINERAL, category = "Carbonate mineral", tagline = "Poisonous barium carbonate — heavy, white, and deadly.", emoji = "\u2620\uFE0F", colorHex = 0xFFF8F8E8, description = "Witherite is barium carbonate, forming white to colorless pseudo-hexagonal crystals. It's surprisingly heavy for a white mineral and is toxic if ingested — historically used as rat poison.", formation = "Deposited from barium-rich hydrothermal fluids in veins, often with barite and galena.", hardness = "3\u20133.5", luster = "Vitreous", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "BaCO\u2083", commonColors = listOf("White", "Colorless", "Gray", "Yellowish"), whereFound = listOf("England", "Illinois, USA", "Germany", "China"), funFacts = listOf("Named after Dr. William Withering, who discovered it.", "It's highly toxic — historically used as rat poison.", "Witherite is much heavier than it looks due to barium."), uses = "Barium chemicals, glassmaking, rat poison (historical).", rarity = "Uncommon"),
